/* 平成14年委員会データ（自動生成・分割ファイル） */
window.SHINAGAWA_DB.years.h14.committeeSessions.push(...[{"id":"h14-20021105-5","meetingId":"h14-cm11","date":"2002年11月5日","dateIso":"2002-11-05","committee":"総務委員会","time":"午後１時０８分～午後４時２３分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を53件整理しています。","topics":[{"id":"topic-01","title":"の中央防波堤埋立地の帰属","agenda":"の中央防波堤埋立地の帰属","exchanges":[{"speaker":"林（宏）委員","kind":"質問","question":"２ページの(3)の1)が申請の取り下げで、2)が国庫補助の申請を改めてということなんだけど、2)の国庫補助の申請に都市計画決定告示が必要であると書かれているんだけど、これは事実か尋ねました。","respondent":"小野（孝）政策担当課長","answer":"これが必要であるというふうに聞いております。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"１４年度は都市計画決定の告示があったということか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"１４年度は都市計画決定をするということを前提というか、それを条件として一応計画を提出をさせて、保留をずっとしていただいたという状況です。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"意見","question":"１４年度中に都市計画決定の告示ができなければ、１５年度に施設建設に向けてはできないという、そういう流れになるわけです。その辺の事実も書いてくれたほうがいいんじゃないのかなと思うので、その辺を説明するよう求めました。","respondent":"小野（孝）政策担当課長","answer":"都市計画決定の告示の見込みについて、まだそういう点では１４年度末までに都市計画決定の手続は残されているというふうに考えております。そういう点で確かに非常に厳しいというふうな状況は認識していますけれども、ただ全くないというふうなことではないです。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"質問","question":"ほかの３施設がそこにあるんだけど、国庫補助というのはつかないというような話もちらっと聞くんだけど、その辺はどうなんですか。東京都がつくった施設だからわかりにくいかもしれないけど、その辺は聞いていますか。","respondent":"小野（孝）政策担当課長","answer":"都市計画決定がきちんと告示ができていないと補助がつかないというふうには聞いております。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"本題のほうで、外側の全部埋め立ても含めた帰属について主張しているということは、品川区はやっていたわけだけども、５区が全員合意したんですか。その辺の合意した理由がわかれば、相手の考え方が難しいのかもわからないけど、わかれば説明を求めました。","respondent":"小野（孝）政策担当課長","answer":"それから港区、こちらについては内外一体ということを主張しておりまして、江東区と大田区が内側だけということで当初スタートしております。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"意見","question":"早くやればいいから全体に帰属問題を広げちゃっていいよと２区が言い出したというのは、そういうふらちなというか、その魂胆を聞きたいなと思う。わかりませんかとの意見を述べました。","respondent":"中尾根企画部長","answer":"一つには、はっきり言うと、大田区は一つは勘違いしていたんじゃないかというふうに思います。みんな４区がこれでおさまりそうだということになれば、スムーズにいくためなら４区に合わせます、こういうことで変わっていったというのが現実です。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"質問","question":"それが埋立地を１個もらった、１個とった。それで、今隣になっているわけだから、それはちょっとおかしいなという気がするんだけど、その辺の議論はなかったんか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"１３号地のときに、これはどういうふうな考え方、やはり飛び地を認めないという非常に難しいという認識をせざるを得ないです。中心市街地から遠いということを主張してまいりましたけれども、これは次の調停という形になりますと非常に難しいというふうに考えております。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"意見","question":"公園にするのかいろいろな、カジノということも含めて、やっぱり２４区目においておけという考え方も一つあると思うんだよね。今ここで議論しても、どう転ぶわけでもないので、一つの考え方としてそれはお願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-008"},{"speaker":"桜井委員","kind":"質問","question":"実体的に議案というのはどういうふうな、ほかの４区ですか、内容になるのかというのを知りたい。灰溶融施設というのは、所有物というのかしら、東京都の施設、あるいは関係する機関というんですか、そこを説明するよう求めました。","respondent":"小野（孝）政策担当課長","answer":"スポーツ施設につきましては、５区の中で、そこをひとつ希望者が使えるような形で要望していきたいというのが一応５区の中で大筋のところです。","id":"exchange-009"},{"speaker":"桜井委員","kind":"確認","question":"今回スポーツ施設ということで、１０月１５日に確認していますよね。そうすると、今度５区との関係というんですか、このことについての品川区の位置というのはどういうふうな形なんか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"内外一体の考え方ですけれども、過去の１３号地の調停が基本になってまだ十数年ぐらいの、調停に行くまで１０年ぐらいかかっていた。","id":"exchange-010"},{"speaker":"桜井委員","kind":"質問","question":"いや、これはもういいですよと、皆さんでおやりになってくださいと。ついては、うちは一切係わりませんという、そういう態度ということなんか尋ねました。","respondent":"中尾根企画部長","answer":"行革を進めている品川区にとって、とにかく要求しましょうかというレベルでは、議会等でもとても説明はできません。じゃあこういうことについて、これは先ほど冒頭で説明しましたように別途品川区は品川区としての物の考え方に基づいたもので、そういう部分です。","id":"exchange-011"},{"speaker":"土井委員","kind":"提案","question":"そういうのはだれも提案しなかったということなんじゃないかと思うんですけれども、その辺はどうなのかということをちょっとお伺いしておきたい。","respondent":"小野（孝）政策担当課長","answer":"どうしても帰属の方向に、なかなかそういうところが、本来大切な議論のところがなかなかできないというような実情です。非常に行革をきちっと進めていく上で、ほんとうに必要な施設なのか、ここの部分については協議会の中できちっとした考え方を述べているです。","id":"exchange-012"},{"speaker":"土井委員","kind":"質問・要望","question":"要望にとどめますけれども、５区中心にお使いくださいなんていうそんなうまい話は、今どう考えたって考えられないという状況だと思うんですね。負担だけを背負うということになりかねないような気がしますので、その辺は十分な配慮と思慮を持って進めていただきたいなと、こんなふうに思います。","respondent":"小野（孝）政策担当課長、中尾根企画部長","answer":"こういうような形でできておりますので、そこのところはそのとおりになるというふうなことではなくて、やはり全体の議論というのはされる。そういう点もございまして、品川区も… 図々しい考え方なんですけれども、むしろ、そう広がったものの帰属という意味ではなかなか議論として事態も広がらないだろうなと考えています。５区の中での帰属で、東京都なんかはどう考えるのかなということで、そういうことです。","id":"exchange-013"},{"speaker":"土井委員","kind":"意見","question":"東京都、都レベルだけの発想として今後どうするかという流れができてくることが望ましいように思えてならないというのが一つありますね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-014"},{"speaker":"藤田委員","kind":"質問","question":"品川区民はほんとうに陸続きでないわけですから、区内のスポーツ施設を使ったほうがよっぽど区民の利用に資するというふうに思っております。何か考えがあるのかどうか、２点お伺いしたいと思います。","respondent":"小野（孝）政策担当課長、中尾根企画部長","answer":"大田区が最後まで残って、江東区と調停で争った場合ですが、５区の区長の申し合わせの中で、調停に付すために、議会の日程調整に入る。２区で残ったんですけれども、議会に議案が提出された時点で… さすがにその密かに東京都のほうとの折衝では、したがって、その前提の上で物を考えていかなくちゃいけないということになります。","id":"exchange-015"},{"speaker":"藤田委員","kind":"質問・要望","question":"これは交渉事なんで、いい機会だと思うんですね、東京都との折衝は。ですから、十分区民の幅広い要望に応えて、担当の人は大変だと思いますけども、交渉を待ちたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"桜井委員","kind":"質問・要望","question":"職員給与のほうは平均年齢があるんですけど、民間給与、こういうのはどういうふうに考えたらいいんでしょうか。その辺というのは、何かこの意見の中には全くなかったんですけれども、そういう議論というのはされているんでしょうか、説明を求めました。","respondent":"桑村人事課長","answer":"特別区の例えばこの平均４３.２歳の金額に、４３.２歳になったときに、較差が出てくるというふうに考えております。その者たちのいわゆる４月分の給与がどういう実態かというものを調べてみたという意味で、その点についてはここで述べられていないということです。","id":"exchange-017"},{"speaker":"桜井委員","kind":"質問","question":"私は人事委員会勧告のこういう制度そのものはもちろん一つの給与をどうすべきかという、それ限りの勧告かもしれないけども、私たちから見ると。どういうふうに影響というんでしょうか、(3)の人材活用、そうした計画的な新規採用も必要だというような意見もありますよね。","respondent":"桑村人事課長","answer":"全体の給与を計算したものですので、若干違うかもしれませんけど、全体の統計ですが、５億１,０００万円ぐらいです。現状の中では、退職分をそのまま採れるような状況ではないというふうに認識しています。","id":"exchange-018"},{"speaker":"桜井委員","kind":"質問・要望","question":"要望です。今日は一応勧告の内容ということで、当然ながら、職員団体関係者との合意形成というか、それはぜひお願いします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"意見","question":"１月、２月、３月しかないんだ、これは。そういう計算になりませんかとの意見を述べました。","respondent":"桑村人事課長","answer":"実施時期の中で遡及はしないと申し上げたんですけれども、ここで言う７,３９６円相当、何カ月間ですね。例えば４月から実施すれば１２月まで、４月から１２月分までの間差分ですね、それを３月でまとめて減額しますです。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"質問","question":"期末が３回もあるというのは知らないけど、平均七千何がしかの９カ月分を掛けたのを一緒に調整して、そういうことになるんですよね。そうすると、実質的には遡及するという理解でいいんか尋ねました。","respondent":"桑村人事課長","answer":"いわゆる先ほど申し上げましたように、なかなか遡及するという言葉が使いづらいということで、調整という言葉を使っております。４月にさかのぼってされるということであれば、それができないという考え方がありますので、いわゆる３月の期末手当をいじりたい。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"質問","question":"そうすると、品川区としては、人事委員会の勧告というものに対して、原則は２３区の一緒にやっていく仲間の話だからやります。そういうところに手をつけていくというか、検討に入っていくというような、その辺のお考えはどうなんか尋ねました。","respondent":"桑村人事課長","answer":"現実にやむにやまれない事情で実施できなかった区もあります。各区が持っていない調査機能を持って検討してくれた内容というのは、それに立った上で各区の独自性みたいなものも必要だと思ってあります。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"質問","question":"そういうことについて、幸いにして人事課長の課長会というのもあるんでしょうから、いろんなさっきの清掃の問題にしてもしかりだけど。これから、そういう場所でも品川区としてはイニシアチブをとってほしいなというふうに思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-023"},{"speaker":"土井委員","kind":"提案","question":"それに向かってやっていただきたいと思うんですけれども、これをこうしたいということで提案されて、議論されるということがあるでしょう。","respondent":"桑村人事課長","answer":"やはり、ほんとうは不利益遡及しないで実施して、遡及させているんじゃないかという点です。したがって、マイナスと出たからといって、同じ方式でやっていたものについて、何らかの違う決定の仕方をするというのは考えにくいと思ってあります。","id":"exchange-024"},{"speaker":"土井委員","kind":"意見","question":"逆の意味では、逆に攻めるほうも守るほうもなかなか難しいという中身だろうと思うんですよ。これだけにとどめておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"藤田委員","kind":"質問・要望","question":"まず(1)の3)ですか、その評価をどう下すかというのは難しい、これが評価に値するのかどうかというのはですね。こういうものがどういうふうに、どういうふうにお考えになっているのか、その辺をちょっとお伺いしたいと思います。","respondent":"桑村人事課長","answer":"そんなことはだれもみんな知っている、昇給していくわけですが、そういったものを見直していくという考え方。それから３点目の超過勤務についてですけども、あるいは職場実態において、そのほかを別に休みにするという制度でやっております。","id":"exchange-026"},{"speaker":"藤田委員","kind":"質問","question":"我々も例えば仕事を８時、９時近くまで残る場合があるんですね。９時まで残らなくてもいいんだなという感じもするわけですけども、何かお考えがあれば、ちょっとお伺いしたいと思います。","respondent":"桑村人事課長","answer":"どうしても間に合わないことがありまして、そのとき、どうしても超過勤務せざるを得ない部署もあります。その点では、今日いわゆるパソコン等の配置もやってありますので、その分ほかのものの対応ができるというようなことをやってあります。","id":"exchange-027"},{"speaker":"林（宏）委員","kind":"質問","question":"いわゆるコストを下げるための入札ですから、できるだけ落札率というんですか、こういう景気の中ですから無理でしょうけれども。そうすると、何かそういうことを考えるときがきているかなと思うんですが。","respondent":"西島経理課長","answer":"Ｂの６位からＣまでということで、４１社ということで、この入札を実施した経過があります。これからもその辺については配慮して実施してまいりたいというふうに考えてあります。","id":"exchange-028"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"そういう意味で、区内業者育成ということですから、優遇じゃないわけですから、お考えほしいと求めました。お願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"桜井委員","kind":"提案","question":"予定価格はどういう時期にというんですか、業者の見積もりとか、いろいろと流れがありますよね。この場合だと、最低価格というのがありますよね、制限価格というんでしょうか、正式な名称はあれですけど、それも教えていただきたいとの意見を述べました。","respondent":"西島経理課長","answer":"区のほうでは、それを極力、先ほど出ましたように区内業者育成、中小企業育成という立場から分割できるものは発注をして実施をしています。特に電気設備等につきましては、高圧変電等ありますので、こういう発注の仕方をしています。","id":"exchange-030"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、今回はわかりますけども、今後これから契約をやるに当たって、いろいろ配慮してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"藤田委員","kind":"意見","question":"業者が決まって、地元の説明会というのは、いつごろされていくのかということ。やはり、複合施設ですので、地域住民の方は理解を示してもらえるんではないかというふうに思いますけれども、その説明会はもう終わられたのかどうかとの意見を述べました。","respondent":"片田施設担当課長","answer":"実は、１０月３１日ですけれども、西大井の福祉園におきまして、７時から一応概ね８時半の予定でございましたけれども、８時ぐらいに終わりました。１４人ぐらいの参加がございました。","id":"exchange-032"},{"speaker":"藤田委員","kind":"意見","question":"特に反対の意見もなくて、皆さん地域の人たちは５階にしてもいいですよというふうな感触を得たのかどうかとの意見を述べました。","respondent":"片田施設担当課長","answer":"参加者がいらっしゃった中で、その以前の２月に一応計画説明会を行なってありますので、建物に対する反対ということは特にございませんでした。もう一つ、土曜日の工事をできるだけ配慮していただきたいといった方が、当日いらっしゃらなかった方からございました。","id":"exchange-033"},{"speaker":"藤田委員","kind":"質問・要望","question":"当然これからそうなると思いますけども、これについては、そういうふうになっていないので、ちょっと心配だったものですから質問いたしました。要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"嶋委員","kind":"意見","question":"道路に面して、隣に原っぱ公園がありますが、公開空地的な緑のところだったかわからないんだけど、公園で大きな１本の木を残されているんですが、この地図で見ると、エントランスホールあたりにあの木を持ってくるのかなと思うんですがとの意見を述べました。","respondent":"片田施設担当課長","answer":"同じ６ページの資料の中で、１０台というところが書いてありますけれども、そのあたりに一応移植する形です。ちょうど階段の下のあたりになります。","id":"exchange-035"}]},{"id":"topic-02","title":"の西大井保育園内装工事等業務委託","agenda":"の西大井保育園内装工事等業務委託","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"これは保育課ですか、その辺、選択的なご判断をどうされたのか。保育園を改築した、その経過がもしわかったら教えていただきたいんですけど。","respondent":"本間総務部長","answer":"私どもの契約セクションに来ているですから、これの内容の配置等々につきましても、その所管課のほうで十分に検討した結果だというふうにご理解をいただきたいと思います。","id":"exchange-036"},{"speaker":"林（宏）委員","kind":"質問","question":"聞きなれない呼称だと私は思う、工事委託契約という言葉があるんだけど、工事請負契約ではない、どういうことなんでしょうか、ひとつ説明を求めました。","respondent":"西島経理課長","answer":"仮に１億８,０００万円以上でも議案案件ではないんですけれども、その委託だということでこの委員会に報告をさせていただいている、そういう意味です。","id":"exchange-037"},{"speaker":"林（宏）委員","kind":"質問","question":"じゃあ、前の２件説明したのは、設備工事は入札で、これは入札じゃないということだけど、工事委託契約、要するに工事を発注するんじゃなくて、こういう手法をとったというのはなぜなんですかと聞いている。","respondent":"西島経理課長","answer":"工事等の業務委託をした理由ですけれども、ここは西大井駅前南地区市街地再開発組合が施行主で工事を実施しています。過去の例で申し上げますと、大崎駅東西自由通路、あそこはＪＲのほうに工事等も業務委託の契約を結びまして、実施をしています。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"質問","question":"まさしく新築の保育所、建物の１階につくる、そういう工事じゃないですか。そうしたら、なぜ間にこういうのが入らなきゃいけないんですかという説明をしなきゃおかしい。","respondent":"本間総務部長","answer":"その再開発組合のほうに工事委託等をする内容というふうに、ひとつご理解のほど、お願いいたします。","id":"exchange-039"},{"speaker":"林（宏）委員","kind":"質問","question":"だったら、今言ったような入札をとればよかったんじゃないですかという話をしているわけ。それはやっぱり私は入札、そっちはそんなに込み入ったつくりじゃないから、金額はそんなにならないんだろうけど、１億円を超える工事ですからね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"桜井委員","kind":"質問","question":"それについて、どういうふうになっているんでしょうか。今回の随意契約は。","respondent":"市岡企画財政課長","answer":"今委員おっしゃられたような権利床の位置、それから面積、それから基本的な仕様、それは権利変換計画の中で定めて、都知事の認可を受けて、という仕組みになっております。","id":"exchange-041"},{"speaker":"桜井委員","kind":"質問","question":"そうすると、その仕様の中に、工事に当たっての、今ちょっと話題になっている、問題提起されているというのが入っているという理解でいいんか尋ねました。","respondent":"市岡企画財政課長","answer":"位置とか面積とか、こういうものを決めて、あと具体的な内装で運営にかかわる部分についてはこのような形で区が再開発組合に別途発注をするという形をとっているものです。","id":"exchange-042"},{"speaker":"桜井委員","kind":"意見","question":"この計画ができたときから、そういう今日の契約の仕方あるいは工事の仕方という工事の仕様については、こういうふうに考えられているんですよね。だから、それで権利変換を含めて、当初のときに、既にこういう話し合いがあったのかどうかと、そこを聞いたんですとの意見を述べました。","respondent":"市岡企画財政課長","answer":"それで、あと内装については、自分の使い勝手に従って、ご自分で一定程度内装を決められるです。個々の運営に係るこういう具体的な設備ですとか、仕様ですとか、部屋の内装等については別途決めさせていただいたということです。","id":"exchange-043"},{"speaker":"桜井委員","kind":"確認","question":"そうすると、再確認したいんですけど、権利変換計画の中に、今の、いわば外枠だけであって、この内容は入っていないと、そういう理解でいいんか尋ねました。","respondent":"市岡企画財政課長","answer":"基本的なものは入っていますけど、このような具体的な部屋の割り振りですとか、先ほど来出ているホールの位置ですとか、こういうものについては、自分の専用部分をどう使うかということですので、別途決めたです。","id":"exchange-044"},{"speaker":"林（宏）委員","kind":"意見","question":"法的にも２３区共通とは言いながらも、２３区で申し合わせているから共通でいこうよと言っている部分と、法律でこうなっているよというのはわかりますかとの意見を述べました。","respondent":"桑村人事課長","answer":"ちょっと整理がなかなか難しいんですけれども、いわゆる国が決めた準則ですとか、そういったものはあろうかと思います。ただ、それは法律で細かくこうしなければいけないという項目の判断はちょっと難しいと思います。","id":"exchange-045"},{"speaker":"林（宏）委員","kind":"質問","question":"今現在、２３区じゃなくてもいいんじゃないの、共通じゃなくてもいいんじゃない。そういうルートがあるのかと思うんだけど、そういうことはどうですか、やりませんか。","respondent":"本間総務部長","answer":"それから、そのオール・オア・ナッシング的な今後の特別区の人事行政のあり方の大きな話につきましては、これは助役会で今後検討していきましょう。","id":"exchange-046"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"それぞれ２３区でその情報をいただいてという方向に向かっていくのが、そういう流れを品川区がつくっていってほしい。ボーナスというのかな、そういうことを考えていってやる、結果的に税金が区民に喜ばれる使われ方をするというふうにいくわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"桜井委員","kind":"質問","question":"給与のところだけに、ちょっと引っ張ってというか、ピックアップして議論していくということの持つ意味というんでしょうか。公務員としてどうあってほしいかというのは、今言った区独自にすべてやるべきだという、もうちょっと基本的な考え方を聞きたいと思います。","respondent":"本間総務部長","answer":"基本的な考え方ということでございましたが、今一番言われているのは、組織が一般に停滞化しているということがよく言われているわけですね。都道府県、市町村を挙げて、こういう新しい時代の要請に応えていこうとしているというふうにひとつご理解をいただきたいと思います。","id":"exchange-048"},{"speaker":"桜井委員","kind":"質問","question":"だから、ここの部分はそういう意味で言ったわけであって、今すべて品川区が権限を持っているとは言えないじゃないですか。具体的にはどういうふうに考えていくのかということと、そういうのをどういうふうに踏み込んで考えているのか、そのあたりについて説明を求めました。","respondent":"桑村人事課長","answer":"ただ、あるいは２３区一緒になって、例えば二十何区が合意しなければできないというような考え方はおかしいんじゃないだろうか。その意味で、先ほどの財政の問題とはちょっと切り離れた考え方で、これからの行政サービスの向上につながるんだろうという主張をしているものです。","id":"exchange-049"},{"speaker":"土井委員","kind":"質問","question":"ほんとうはこちらに今人が欲しくて、どう出していけるようになるのかというのがやっぱり必要なんじゃないかなというふうなことを感じますね。その辺はいかが、対処の仕方、あるいはお思いがありますか尋ねました。","respondent":"桑村人事課長、本間総務部長","answer":"これはずっと大きな流れですから、いまだにこれだけまだ数も職種も抱えていることですので、その一つの流れであることは間違いありません。正直言って研究課題です。区長からご答弁させていただいたとおり、非常にストップがかかったということで、大変な思いをして転職を区独自で実施をしたという経過があります。","id":"exchange-050"},{"speaker":"土井委員","kind":"意見","question":"そのためには、制度的な問題と、それぞれやっている職員の皆さんの気持ちの問題と、両方かかわるわけで、研修の部分もそこにかかってくるんじゃないかなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-051"},{"speaker":"藤田委員","kind":"質問・要望","question":"ですから、３２歳でも、非常に正直言って負けませんという人がいるわけですよ。ですから、もうけなければ自分は生きていけない、会社が成り立たないんだという緊張感があるわけですね。","respondent":"桑村人事課長","answer":"これは民間経験歴が５年以上なければ逆にいけないという採用の仕方、一つのこういうものに風穴をあけようということなんだと思います。考え方とすれば、当然必要な人材を採るというのは当然の考え方ですので、十分検討していきたいと思います。","id":"exchange-052"},{"speaker":"桜井委員","kind":"意見","question":"１点だけ。前回、まず例の天王洲の土地の交換の関係ですけど、その後進展があったかどうかなというふうに思っているんですがとの意見を述べました。","respondent":"本間総務部長","answer":"何かその後、その動きがありますれば、委員会にきちんと報告をします。","id":"exchange-053"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1600#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":52614,"voices":128}},{"id":"h14-20021106-13","meetingId":"h14-cm11","date":"2002年11月6日","dateIso":"2002-11-06","committee":"清掃・リサイクル特別委員会","time":"午後１時０８分～午後４時２１分","status":"正式会議録","sourceType":"formal","overview":"清掃・リサイクル特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を0件整理しています。","topics":[],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/930117?Template=document&Id=5676#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=13&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":3546,"voices":4}},{"id":"h14-20021106-16","meetingId":"h14-cm11","date":"2002年11月6日","dateIso":"2002-11-06","committee":"街づくり特別委員会","time":"午後１時１０分～午後４時１３分","status":"正式会議録","sourceType":"formal","overview":"街づくり特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を13件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"意見","question":"土地利用の現況調査というのは、どういう調査で行われているのかお尋ねしたい。屋上緑化などの努力が始まってはいますけれども、その辺は視野に入っているのかどうなのか、２点お尋ねしたいんですとの意見を述べました。","respondent":"伊佐都市計画課長","answer":"その土地の権利に影響してまいりますので、環境問題を視野に入れた用途地域の見直しの方針を出すというのは、非常に厳しいかと思います。ただ、今後のまちづくりの中で十分そういったものについては対応していくように努力していきたいと考えております。","id":"exchange-001"},{"speaker":"沢田委員","kind":"質問・要望","question":"ですから、市街地整備基本構想の見直しのときになるのかもしれないですけれども、ぜひそこは頭の中に置いてやっていただきたいなと思います。意見を言って終わります。","respondent":"伊佐都市計画課長","answer":"土地利用現況調査の方法ですが、業者に委託しています。それから、これは東京都から区が委託を受けた調査でございまして、予算については都からおおむね１,０００万円いただいてです。","id":"exchange-002"},{"speaker":"塚本委員","kind":"意見","question":"それがどういうことなのか、例えば住環境の保全をするんだと言っても、できることは非常に限られているわけです。これをするとかと言っているから、抽象的になっていってしまうんですけれども、言っていることはわかりますかとの意見を述べました。","respondent":"伊佐都市計画課長","answer":"いろんな事業も組み合わせながらの方針ということで、市街地整備基本方針の方向の中で具体策というのはその後に出てくるものでございまして。ただ、やはり地区計画等を地域の中で活用しながら、将来合ったような形のまちづくりをしていきたいということを目的にしています。","id":"exchange-003"},{"speaker":"塚本委員","kind":"提案","question":"どういう政策密度をするのかということを、具体的に提案する時期に来ているのではないかということを一番言いたいわけです。いかがでしょうか、我々が密集市街地に対して一生懸命検討を加えてきたという経過も踏まえて、お答えいただきたいんですけれどもとの意見を述べました。","respondent":"伊佐都市計画課長","answer":"これをどうするかということは、検討課題というふうに認識しております。これについても、どういう形でできるかについて、十分検討してまいりたいと考えております。","id":"exchange-004"},{"speaker":"塚本委員","kind":"質問","question":"これもまた別の問題が起きているわけですから、大きく言えばそういうことだろうと思っているんですけれども、それが見えてこないんです。何をすべきかということを、一番基礎的なところに見えてこないからあえて言っているわけですけれども、どうか尋ねました。","respondent":"伊佐都市計画課長、中谷まちづくり事業部長","answer":"市街地整備基本方針の中で記述が抽象的であるということ、まさしく具体で説明申し上げればよかったんですが、申し訳ございません。用途地域の指定方針を策定する中で、方針を打ちますので… 今回は土地利用の方向性ということで、現況の土地の利用状況を踏まえた形でのご説明という形なので、漠然とした形です。","id":"exchange-005"},{"speaker":"塚本委員","kind":"質問","question":"我々の持っている課題というのは、そういうものがあるわけです。そういうことを踏まえてどうするんだということをわかるように、そういう時期ですから、そういうことを言っているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"桜井委員","kind":"質問","question":"この前も質問したんですけれども、大崎・五反田の６０haのところで、７７万m2という答弁をいたしましたね。今考えられているイメージというのでしょうか、どういう角度で検討されているのか、参考までに聞いておきたいと思います。","respondent":"伊佐都市計画課長","answer":"ご指摘の都市活性化拠点形成ゾーンということで位置づけてあります。戸越だけ、そういった地域については都市再生特別措置法あるいはその他の法改正を踏まえて進めるという方向性を考えております。","id":"exchange-007"},{"speaker":"桜井委員","kind":"質問","question":"そうすると、８つのゾーンという考え方以外に、政策的にこれを打ち出していくという理解になるのでしょうか。そうなると五反田地区の６０haが東京都の方針に沿ってやろうとしている限りは、そこはどうなんか尋ねました。","respondent":"南雲都市開発課長、岩野まちづくり事業部次長","answer":"今回、市街地整備基本方針でいきますと大崎・五反田地区の都市活性化拠点形成ゾーンということで、この区域の中におさまっております。これは都なり国なりの指定を受けたから、それに基づいてどうこうするということではなくて… 特別措置法は言ってみれば、それがより進めやすくなるための道具立てですので、あくまでも私どもとしては活性化ゾーンについての考え方は変わらない。それをより整備しやすくするための道具立てだと考えています。","id":"exchange-008"},{"speaker":"桜井委員","kind":"質問・要望","question":"だから、土地の利用問題がどうあるべきかというところからいかないと、生活や暮らしの部分が後景に追いやられていくというふうに感じるんです。だから、今度の方針のときに、そういうことも踏まえて、ぜひ報告していただきたいなと、これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"須藤副委員長","kind":"質問","question":"道路等も事務事業概要に出された数字と春にもらったのが３万幾らという品川区が出してきた数字とここに出てきた数字が大きく違っているんです。大まかは変わってこないだろうけれども、うちでつくっていったものをベースにしたほうがいいのではないかと思うんだけれども、その辺はどうか尋ねました。","respondent":"伊佐都市計画課長","answer":"有効数字の５桁の下３桁ぐらいは誤差の範囲ということで、面積の絶対値というのは統計上の数字としては信用できない。図面だけで道路とみなせる部分はみんな道路としてカウントしてくるという状況でございまして、統計データとはちょっと数字が違ってまいります。","id":"exchange-010"},{"speaker":"須藤副委員長","kind":"質問","question":"それを加えていって、そうすると品川区で今まで一生懸命やってきた数字のあり方は何に使うんだという話になってきてしまう。その辺の整合性を持たれたらいいのではないかなと思うんですけれども、いかがか尋ねました。","respondent":"伊佐都市計画課長","answer":"調査自身は品川区が委託を受けてやっていますので、それを東京都に上げたという形でございまして、このデータとしては品川区のものです。行政面積といった、その点について詳しい中身に立ち入って申し訳ないですけれども、データに誤差が生じるのは事実です。","id":"exchange-011"},{"speaker":"須藤副委員長","kind":"意見","question":"せっかく品川区は品川区でいろいろ数字をつくっているので、そうするとここに出ている数字と、今まで我々が教えられた数字と随分差異があるというと、どっちがどっちなんだと、これは調査の仕方によって違うと言われてしまうと。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"三上委員","kind":"質問・要望","question":"一番問題になっている９棟の部分ということが一番肝心だということは、９棟の人たちの協力がない限り平成１６年ということはあり得ないわけです。９棟の人たちの今の大体の雰囲気というのはどういう状況にあるのか、課長がつかんでいる状況を皆さんにご説明してほしいと求めました。","respondent":"中島街路事業担当課長","answer":"あまり詳細にはご説明できないんですけれども、３枚目の図面の赤い部分につきまして、非常に協力していただいている状況があります。","id":"exchange-013"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/690912?Template=document&Id=6244#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=16&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":18388,"voices":41}},{"id":"h14-20021107-8","meetingId":"h14-cm11","date":"2002年11月7日","dateIso":"2002-11-07","committee":"建設委員会","time":"午前１０時１１分～午後３時２１分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を27件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問・要望","question":"１点聞かせていただきたいんですが、その辺の、区に自転車駐輪場を管理するという形になった経過を若干教えてほしいと求めました。","respondent":"南雲都市開発課長","answer":"駅を利用する方と、買い物なり、施設に来る方の駐輪場と２種類あります。こういう役割分担で進めておりますので、駅利用者の部分については、区が管理についても行っていくです。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"当然駐輪場の代金を取るわけですから、りんかい線の鉄道事業者のほうの請け負う範囲というのはあるんですか。区と、鉄道事業者との関係の中では申し合わせ事項みたいなものというのはあるんか尋ねました。","respondent":"南雲都市開発課長、中谷まちづくり事業部長","answer":"公共の都市側で駅利用者の駐輪場をどういうふうに対応を分担していくのかというのが、品川区も含めて、まだそこまではっきりしていない。開発事業者の負担による整備、国の予算でということで、現在は行っているです。堀り山の中に設置をするという形で、そういう点では設置をする際、鉄道事業者の堀り山を利用するという形で協力をしたということが１点。","id":"exchange-002"},{"speaker":"田中委員","kind":"質問・要望","question":"その点を確認させていただきたいんですが、天王洲アイル駅と同様の防犯体制で臨むんだろうと思いますが、その辺のお考えをお伺いいたします。カメラから見ているけれども、すぐ対応できる状況にあるのかどうかというところも含めまして、管理体制という部分でお聞かせほしいと求めました。","respondent":"奈良交通安全担当課長","answer":"防犯カメラの関係ですけれども、これも管理人室と直結して、何かあったらすぐそれに対応できるような体制をとっております。〔「図面で説明してください」と呼ぶ者あり〕 ２枚目の一番上の地下の平面図ですけれども、真ん中付近が管理人室になっております。","id":"exchange-003"},{"speaker":"田中委員","kind":"質問・要望","question":"天王洲アイル駅と同様ですが、地下ということで、防犯上、防火上の対応というのは、より的確に力を入れてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問","question":"放置対策のところをお伺いしたいんですが、放置防止指導員という方はどういう方なのか。「地元と連携し」とあるので、具体的にどのようなことを考えていらっしゃるのか、お伺いいたします。","respondent":"奈良交通安全担当課長","answer":"午前中は８時から１１時の間、午後は２時から４時の間に、あるいは駐輪場に入れてくださいという形でやっております。地元と連携ですけれども、それぞれ入っているビルの管理者と連携しまして、それぞれ連携活動をしています。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"放置防止指導員というのは、今シルバー人材センターがやっている仕事か尋ねました。","respondent":"奈良交通安全担当課長","answer":"そうです。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問","question":"ということは、管轄は区になるんですか、委託業者になるんか尋ねました。","respondent":"奈良交通安全担当課長","answer":"区でやっております。","id":"exchange-007"},{"speaker":"飯沼委員","kind":"質問","question":"防止指導員の方の待遇というのは、今と変わらない状況でお仕事をされるんか尋ねました。","respondent":"奈良交通安全担当課長","answer":"品川シーサイド駅における放置防止指導員につきましては、変わりはございません。","id":"exchange-008"},{"speaker":"飯沼委員","kind":"質問","question":"なぜ質問をしたかというと、シルバー人材センターをなるべく雇用するようにというご指導があるんでしょうか、教えていただけたらと思うんです。","respondent":"奈良交通安全担当課長、岩田管理工事課長","answer":"努めてシルバー人材センターを活用しなさいというふうにうたってありますので、そういった面でシルバー人材センターの方にお願いしております。料金については、１時間単位が、活動の割合から見ればちょっと高いのかなという感じで… そういったことに対しては、できるだけシルバー人材センターの職員を使ってくださいと、こういうふうに依頼を仕様書の中で書いております。","id":"exchange-009"},{"speaker":"飯沼委員","kind":"質問・要望","question":"今、人材シルバーセンターの方も本当に働き盛りで、お仕事を求めていらっしゃる。その辺は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"林（和）副委員長","kind":"質問","question":"１１月１日から定期利用申し込みの受け付けを開始されておりますけれども、申込状況と、今後の見通しをどういうふうに見ているのか、説明を求めました。","respondent":"奈良交通安全担当課長","answer":"申込状況ですが、どれぐらい申し込まれたか、まだこちらのほうで把握しておりません。見通しですけれども、事前の調査では、私どもでは大体７００名前後の方は利用をなさるのではないのかなというふうな見込みをしております。","id":"exchange-011"},{"speaker":"林（和）副委員長","kind":"質問","question":"受け付けはどういうふうな形になっていますか。どこで受け付けているんか尋ねました。","respondent":"奈良交通安全担当課長、岩田管理工事課長","answer":"受け付けにつきましては、現在、品川シーサイド駅がまだ開設しておりませんので、天王洲アイル駅、あるいは大井町駅周辺で受け付けをしております。品川シーサイド駅の出入口部分にポストを設置をしておりますので… 所管のほうで台数を確認していないそうですので、至急確認をいたしまして、できれば、今日の建設委員会中にご報告をさせていただきたいと思います。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"調整池をつくるにあたって、公園利用上制約を受けるということになってしまうのかどうか、その点をお聞かせほしいと求めました。","respondent":"矢部下水道河川課長","answer":"これに関しましては、下水道局のほうで、１１月２日、土曜日に地元説明会を開いてあります。下水道局が代表者と直接会いまして、状況を説明いたしまして、ご了解を得ているというふうに聞いております。","id":"exchange-013"},{"speaker":"田中委員","kind":"確認","question":"もう一度確認ですが、工事の期間中だけ使えないということなのか、今後永久的に使えなくなるということなのか、その点だけお伺いいたします。","respondent":"矢部下水道河川課長","answer":"先ほど申しましたように、来年の６月頃までには上部のほうも公園復旧工事が終わりますので、そのあとは皆さんが使えるようになります。","id":"exchange-014"},{"speaker":"田中委員","kind":"質問・要望","question":"品川区側から要望してこういう形になったのか、下流ですから、その辺の区の立場としての対応はどういうことができるのかどうかという部分をお聞かせほしいと求めました。","respondent":"矢部下水道河川課長","answer":"平成１２年度ぐらいに工事を終わっているんですが、雨水整備クイックプランの名称には入っておりませんけれども、ずっと折衝をしておりました。きのう、今日初めてポッと出てきたということではなく、今までずっとやってきた経過の中で実現したです。","id":"exchange-015"},{"speaker":"田中委員","kind":"質問","question":"将来的なことなので、推測の域でしか言えないんですけれども、西品川のときには区長が東京都に行かれて何とか実現できた。対応するというのは、区側からも強く要求できるような内容といいますか、事項というふうに捉えていいんか尋ねました。","respondent":"矢部下水道河川課長","answer":"今年の８月４日の４００ｔの浸水被害を含めまして、下水道局にはあらゆる面で下水道についての整備をやってくださいというお願いをしております。その中で、品川区のほうの公園についても、こちらのところについては積極的に対応をしますよというお話はしています。","id":"exchange-016"},{"speaker":"田中委員","kind":"意見","question":"長期のプランにはなるかと思いますが、その中でもいろいろな手段をとっていただいて、クイックな対応をよろしくお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"本間委員","kind":"確認","question":"地図で確認しておきたいのは、資料２に、排気施設が２カ所あるというふうに書いてあります。排気施設は１カ所といいますか、どこで２カ所というような形で表現されているのか、それを確認しておきたいと思います。","respondent":"矢部下水道河川課長","answer":"１カ所は大森駅側の、下側の排気施設ということで、ここについては排気施設単独で整地する予定になっております。ということで、合わせて２カ所です。","id":"exchange-018"},{"speaker":"本間委員","kind":"確認","question":"この排気施設２カ所の仕掛けによってどの程度、排気施設を設けることによって、どの程度の効果が考えられるのか。蓋が上がることはないのか、多量に降ればどうなのかというようなことで、ちょっと確認をしていきたいんですけれども、教えていただけますか。","respondent":"矢部下水道河川課長","answer":"浮上防止型のマンホール蓋にしているんですが、ガッチリ止めたんですが、その周りの舗装もちょっと持ち上がったというところがあるんです。それぐらいの力がありますので、それを空気を抜くことによりまして軽減させるというような効果は大分あろうかと思います。","id":"exchange-019"},{"speaker":"菊地委員","kind":"質問・要望","question":"私、聞き漏らしたかもしれないんですけれども、区内でほかに排気施設を設置されているような箇所というのはあるんでしょうか。その辺のことというのは、構造上心配はないのかどうか、そこだけ教えてほしいと求めました。","respondent":"矢部下水道河川課長","answer":"臭気の話ですけれども、下水道の管渠内の空気が抜けますので、多少の臭気はあろうかと思います。一つは、そういう状況にはないのかなということもありまして、今あるような場所でも臭気に関しての苦情は私どものほうには入ってきておりません。","id":"exchange-020"},{"speaker":"船波委員","kind":"意見","question":"「品９１」という路線で、ぐるっと矢印が書いてあるんですけれども、これは品川駅東口にまた戻ってしまうわけですね。大井町から八潮パークタウン、品川駅に行くというのは、そのままなのかとの意見を述べました。","respondent":"伊佐都市計画課長","answer":"昨年３月のダイヤ改正の路線変更で、これまで品川駅東口から八潮を経由して大井町をぐるっと回っていた路線を切りわけたという経緯があります。その中で、八潮と大井町の間は往復の便が出てございまして、その部分については変更はございません。","id":"exchange-021"},{"speaker":"船波委員","kind":"質問","question":"点線のところは、これは行きと帰りで違うところを通っていくんですか。「品９１」というところで、これは品川駅から八潮パークタウンに行くまでは実線で、点線のところは帰り道なんか尋ねました。","respondent":"伊佐都市計画課長","answer":"戻ってきて、品川シーサイドに寄って、そこから品川駅東口に行く。品川シーサイドの駅前広場に必ず入るです。","id":"exchange-022"},{"speaker":"船波委員","kind":"意見","question":"品川駅東口、都立八潮高校前、八潮パークタウンが実線で、都立八潮高校前、品川シーサイド、都立高等専門学校が点線なんですけれども、運行する区間と、経路の変更というのがよくわからないのですけれどもとの意見を述べました。","respondent":"伊佐都市計画課長","answer":"左の表が非常に分かりにくいものです。都立八潮高校と都立工業高等専門学校の間の部分に「品川シーサイド駅前」というバスの停留所を１個設けるという説明でございました。","id":"exchange-023"},{"speaker":"林（和）副委員長","kind":"意見","question":"１１月６日現在で１９台ということで、申し込みの状況が非常に悪いわけですね。それ以上になる可能性だってあるわけだから、とにかく今月中にできるだけＰＲをしていただいて、この状況を一日も早く把握してもらいたいと思いますとの意見を述べました。","respondent":"矢部下水道河川課長","answer":"そういうことも含めまして、この地区の緊急対応として、雨水枡を増やすというところで対応をしていきたいと考えています。説明会の中でも、地元の方もおっしゃっておりまして、ある程度軽減すると考えております。","id":"exchange-024"},{"speaker":"田中委員","kind":"提案","question":"私の個人的な提案なんですが、個人的にはぜひこれを前例にしていただきたいという思いがあるんですが、委員長に提案をさせてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-025"},{"speaker":"北野委員長","kind":"質問・要望","question":"最初私もそう思ったんですけれども、前例がないということで、今回この場には出させていただいておりませんけれども、田中委員からのお申し出で、皆さんのご意見を伺わせてほしいと求めました。","respondent":"林（宏）議長","answer":"ちょっと変な言い方なんだけれども、３,０００人からの人がいると、年間亡くなる職員の方の数は結構な数です。いろいろご苦労さまでした、お世話になりましたという気持ちで、僕はいいと思います。","id":"exchange-026"},{"speaker":"北野委員長","kind":"質問・要望","question":"なお、午後から道路大会の出発につきましては、１２時１０分頃に放送を入れますので、第三庁舎前のマイクロバスにお集まり願います。○午前１１時２５分休憩 〔第１３回東京都道路整備事業推進大会へ参加〕 ○午後３時２０分再開。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3738#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":20677,"voices":87}},{"id":"h14-20021112-14","meetingId":"h14-cm11","date":"2002年11月12日","dateIso":"2002-11-12","committee":"行財政改革特別委員会","time":"午後１時０５分～午後３時１７分","status":"正式会議録","sourceType":"formal","overview":"行財政改革特別委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を38件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"菊地委員","kind":"質問","question":"当時の委員長が、本会議で、人口が３０万人を切ったときにまた改めてこの問題を論議するという報告をされています。ちょっと当時の行財政改革特別委員会での定数問題についての審議を、かいつまんでご説明を願えればと思います。","respondent":"福田区議会事務局長","answer":"その報告速記を読み上げながら、若干のご説明等を加えてお答えにさせていただきたいと考えています。具体的な検討事項として、これはいずれも法律上の問題だろうと思います、「他区の状況等の諸資料に基づき調査してきたところであります。","id":"exchange-001"},{"speaker":"菊地委員","kind":"質問","question":"３０万人を切ったときに改めて論議の俎上に乗せていくということを、９回にわたって論議をされて、人口との対比という論議もされたんだと思うんです。その辺を、ちょっと教えていただけますか尋ねました。","respondent":"福田区議会事務局長","answer":"実は、私は手元に速記録を持っているんですけれども、その概要というのをなかなかかいつまんで申し上げることは難しいと考えています。人口３０万人以上の市、４８人とありますが、３０万人の上下がどうなんだろうかというご議論が根底にあったんだろうと考えています。","id":"exchange-002"},{"speaker":"菊地委員","kind":"質問","question":"９回にもわたって論議をされて、そういう結論を導いたということなんでしょうから、なかなか答えが出てこない部分があるのかもしれません。とりあえず当時の状況をお聞きしましたので、この後、また何かありましたら、論議に参加させてもらいます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-003"},{"speaker":"佐藤委員","kind":"質問・要望","question":"これからどういう手順で、これを取り扱っていかれるのか。先ほど、全員協議会なんていうことも、理事者のほうから説明がありましたが、そこをちょっとお聞かせほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-004"},{"speaker":"佐藤委員","kind":"質問","question":"委員長の指名ですから。ただ、今日、結論を出すわけではないわけですよね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"鶴委員","kind":"質問","question":"今、お話がありましたが、私の知るところでは、議会運営委員会で協議した結果、行財政改革特別委員会に付託すべきであると議長が判断して、行財政改革特別委員会で審議を尽くしてくださいよと、そういう意味で付託されたのではないかと思うんですが、いかがか尋ねました。","respondent":"松澤委員長","answer":"委員長に聞かれているんでしたら、そのとおりです。","id":"exchange-006"},{"speaker":"鶴委員","kind":"確認","question":"これは議会の議員の身分にかかわる問題ですから、この陳情が出たときに、私としては厳粛に受けとめました。他区の状況等についてもいろいろ論議をしたいんですけれども、その前にちょっと確認しておきたいことがあります。","respondent":"福田区議会事務局長","answer":"ただし、その必要がないと認めるものについては、所管委員会に写しを参考送付する」です。それから、委員のご質問にございましたものにつきましても、ちょっと文言は今と異なりますけれども、うちの区議会では、基本的な差異はございません。","id":"exchange-007"},{"speaker":"鶴委員","kind":"質問","question":"そうしますと、品川区が会議規則の第３９条で、陳情書の処理についてうたっていることは、請願と同じ扱いをする、同類であると。ということは、請願・陳情権はどこに基づいて、品川区では第１３９条で陳情の取り扱いを尊重しているのか尋ねました。","respondent":"福田区議会事務局長","answer":"私ども品川区議会が定めました会議規則の第１３７条、あるいは不採択、こういう根拠が設けられております。第１３９条、陳情書の処理、このように法的な流れが続いていくという構成です。","id":"exchange-008"},{"speaker":"鶴委員","kind":"質問・要望","question":"議員定数４名削減を求める陳情書が提出されたので、どうお考えですかということなんですが、次のような驚くべきことが記されている。行革（改正）、行革を言うなら、みずからがその姿勢を正すべきではないでしょうか」と。","respondent":"福田区議会事務局長","answer":"直接的な事例については、私、記憶にございませんし、何かで目にした、あるいは文章を読んだということはございません。","id":"exchange-009"},{"speaker":"鶴委員","kind":"意見","question":"こういうことは、脱線した言論だと思わざるを得ないですね。ところで、聞きたいんですけれども、定数削減の陳情者によりますと、１０月９日現在となっておりますが、２３区のその後の状況はわかりますかとの意見を述べました。","respondent":"福田区議会事務局長","answer":"そのデータの中で、現在、来年の１月１日の新法施行に向けて検討を行っているとされている区が四つあります。検討中の区は除きますが、平均値を取ってみますと９３％でございまして、品川区は９１％。","id":"exchange-010"},{"speaker":"鶴委員","kind":"質問","question":"その後のところも、それぞれの理由がわかれば、ぜひ、調べてご報告いただければと思うんですが、この点はいかがでしょうか。必要ないということであれば。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-011"},{"speaker":"鶴委員","kind":"提案","question":"その中で、ちゃんと委員会としても定数の削減について改めて要望しなきゃいけないなということを踏まえて、私は理解をしているわけです。だから、その資料については、早めに各委員に、わかった段階で提示をしていただくということはできないか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"},{"speaker":"鶴委員","kind":"質問","question":"やれという結論なのか、やるなという結論なのか、ということは、現状のままでいいということかということになっちゃうじゃないですか。そんな委員会なんてないんじゃないか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"鶴委員","kind":"質問","question":"ほかの委員も質問したいことがある。ちょっとそんなに急がないで。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"伊藤委員","kind":"確認","question":"ですから、ひと月に２回委員会をやっていくとか、私たちは思っております。ですから、議論に入っていく前に、具体的な回数とか、こういうふうな仕組みをどうつくっていくのかということに、委員長に再度確認をしたいんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"伊藤委員","kind":"質問・要望","question":"そうすると、実際的な行財政改革特別委員会での議論が２回程度ということになりますでしょうか。ですから、これは要望になっていきますけれども、もっと回数を増やしていただきたいという要望をお願いしておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-016"},{"speaker":"原委員","kind":"質問・要望","question":"本来的に、これを論議してほしいという趣旨であるならば、もっと早い時期に出されるか何かするのが当然のことだろうと思う。今の日程そのものでいったら、その辺のところも含めて、今後の中でしっかりした日程調整をしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"本多委員","kind":"質問・要望","question":"２０年間、行財政改革をされてきて１,１６３人ということで、ちょっとお聞かせいただきたいと思うんです。この１６年間の現状把握という点で、その辺のわかる範囲で教えていただきたいと思うんです。","respondent":"福田区議会事務局長","answer":"その答えを得るためには、１年間の議員にどのぐらいの歳費等が投入されているかというところから始まるわけであります。繰り返しでありますが、これはこの十数年間の累積という性格のものです。","id":"exchange-018"},{"speaker":"本多委員","kind":"質問","question":"その辺を教えていただきまして、こういった視点を持って、我々は取り組んでいきたいと考えています。ただ、先ほどから出ていますように、委員会運営ですとか、手順について、しっかりと深く考えていく必要があるのかな思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"堺委員","kind":"質問・要望","question":"この辺については、こういう考え方といいましょうか、こういう数字をそのまま理解していいんでしょうか。その辺をちょっと教えていただけますか。","respondent":"福田区議会事務局長","answer":"若干異なってまいりますが、毎月の報酬に１２カ月分を掛けますと、ざっと７４０万円程度。トータルすると若干異なるかもしれませんが、おおむね陳情書のとおりです。","id":"exchange-020"},{"speaker":"堺委員","kind":"質問","question":"そうすると、おおむねそういうことなので、仮に定数を４人削減すると、単純に４を掛けてこういうことになるということなんか尋ねました。","respondent":"福田区議会事務局長","answer":"５,７２０万円前後の数字が、やはり出てくるだろうと考えています。","id":"exchange-021"},{"speaker":"堺委員","kind":"質問","question":"ですから、出されてから論議していくのに日数がないからいいとか、悪いとかという、それ以前の問題ではないかなと、私は思うんです。１２月５日が定例会ですから、あるいは１２月５日の中で結論を出さなければならない、私はそのように受けとめております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鶴委員","kind":"意見","question":"現状維持かどうか、平成６年１１月の論議の中でも、そうじゃないんだという両者の論議が展開されています。ところで、議会事務局長は選挙管理委員会事務局長をされていたことがありましたかとの意見を述べました。","respondent":"福田区議会事務局長","answer":"ないです。","id":"exchange-023"},{"speaker":"鶴委員","kind":"意見","question":"第４回定例会で間に合わないんだったら、第１回定例会で結論を出すためには、真剣に論議をして結論を出すべきだろうと。今日じゃないですよとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"菊地委員","kind":"質問","question":"議会の財政上の問題も含めて話がいろいろ出されましたけれども、１,２４０億円という区の総予算があって、議会費が約８億円弱でしょうか。ですから、そういう課題として、問題として出てくるような中身なんではないのかなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"金高委員","kind":"質問","question":"法律に基づく状況を、上限を定めているわけですから、その内容がちょっとよくわからないというところが一つあります。その中に議会費があるわけですから、資質ということで、既得権益にあぐらをかきというような厳しい指摘もあります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっと委員長にお伺いをさせていただきたいんですけれども、いろいろなご意見を伺ってきますと、回数を増やすなり何なり。別な考え方をしなきゃいけないのかというところになると思うので、ちょっと、その辺をお伺いしたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"原委員","kind":"質問","question":"議員定数と連動しているわけですから、じゃあ、どうなりますかという形になると思うんです。やるならば、増やさなければいけない、これは当然の話だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"高木委員","kind":"質問・要望","question":"朝７時から夜１１時まで、いろいろな住民の多様な要望だとか、ちょっと頭にあるわけであります。これを答弁でなくていいですから、資料で出していただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"堺委員","kind":"意見","question":"引用させていただきました平成６年の、効率性のよい活性化された議会を望んでいるわけであります」と、こういう表現をされております。私も、議員定数削減ということについては、全く同じ意見を持っておりますので、あえてこのことについても触れさせていただきましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"伊藤委員","kind":"提案","question":"その年の２月２８日に提案して、１１月３０日に、そのことを本会議で賛成討論している。ですから、最終的には、このときには自民党は賛成しましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-031"},{"speaker":"菊地委員","kind":"質問","question":"意見というか、資料２は資料１に基づいてまとめた意見だということなんですけれども、ちょっとここの取り扱いがよくわからないんです。それぞれの特別委員会で、最終的にいつも提言というか、まとめていきますけれども、それに準ずるものという意味なんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"菊地委員","kind":"質問","question":"ということであれば、土木現業職員について、この間、論議をしてきた範囲にとどまらずに、論議をされた他の分野について肉づけをしていくととらえてよろしいんか尋ねました。","respondent":"松澤委員長","answer":"先ほどもご案内申し上げましたとおり、資料１は、各委員から出た質疑、それと理事者の説明、答弁等を大まかにまとめてみました。やっぱり行財政改革特別委員会としては、１年間行った現業職員の配置についての意見をまとめていきたいと考えております。","id":"exchange-033"},{"speaker":"菊地委員","kind":"質問","question":"私の認識で、各党の意見ですとか、表明があったりして、年が明けてから取りまとめをしていくという認識があるものですから、この間の委員会での議論でのこういう取りまとめの仕方というのが、いいのかどうか、そこがちょっとよくわからない。","respondent":"松澤委員長","answer":"ただ、今後の予定を考えてみますと、１１月はもう一度２８日にありますけれども、例年ですと、１月に１度あります。足したりしながら、結論的には１月ぐらいになるかなということもありますけれども、できれば今年中にまとめていただければと思っているところです。","id":"exchange-034"},{"speaker":"菊地委員","kind":"意見","question":"ということでしたら、私どものほうも、まだ会派の中でこの取りまとめについて論議をし切れてないということがありまして、できれば、そういう論議を経て、また意見を述べる機会を取っていただければなと思うんですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"原委員","kind":"意見","question":"非常によくおまとめになって、ご努力をされているわけです。その中で精査したものをこの次に出してもらうとか、そういうことができるかどうか、その辺をひとつ委員長としてお話ししてくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-036"},{"speaker":"伊藤委員","kind":"確認","question":"実はそういうところまでさかのぼっていきたいという議論も、我が会派の中で多少ありますので、そういう新しい議論を出してよろしいんでしょうか。確認をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-037"},{"speaker":"伊藤委員","kind":"質問・要望","question":"ですから、例えば土木の現業職員の配置についてということは、同じ職場、同じ土木の現業の分野でしか配置できないわけです。すぐにどうこうなるということではありませんけれども、最終的には、正副委員長でおまとめくださいということを要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/373656?Template=document&Id=5720#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=14&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":28701,"voices":79}},{"id":"h14-20021125-6","meetingId":"h14-cm11","date":"2002年11月25日","dateIso":"2002-11-25","committee":"区民委員会","time":"午前１０時０８分～午後４時０４分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を83件整理しています。","topics":[{"id":"topic-01","title":"平成１４年請願第２４号、日本育英会奨学金制度の充実を求める請願","agenda":"平成１４年請願第２４号、日本育英会奨学金制度の充実を求める請願","exchanges":[{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"うちも１人大学生の子がいるんですけど、また、そういうちょっと区民の大変な実態がつかめるところがありましたら教えてほしいと求めました。そういう実態が、品川の中でどういう状況になっているかというところがつかめるところがありましたら教えてほしいと求めました。","respondent":"宮地区民課長","answer":"それから、東京都の育英資金を受けている人は全都で３４３名ということですので、その中の品川区だけ抜き出しては数字を把握できないです。学校に合わなかったとか、一時的な都合で退学、あるいは転校しているケースが多いというふうに伺っております。","id":"exchange-001"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"ヨーロッパとかなんかの教育費、それから奨学金の実態というのがどうなっているのかということについても、ちょっとお知らせいただけたらと思いますとの意見を述べました。","respondent":"宮地区民課長","answer":"今のところ、無利子と有利子の方の人数の割合等というのはちょっと把握できませんので、これはちょっとご容赦願いたいと思います。ヨーロッパの奨学金制度ですが、私どものほうでは、今のところ、そこまでちょっと把握してございませんので、よろしくお願いいたします。","id":"exchange-002"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"はい、わかりました。やっぱり今こういう時代だからこそ、こういう教育の奨学制度を充実させてほしいということをみんなが思ったんじゃないかなというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"三上委員","kind":"質問・要望","question":"ちょっと確認したいのは、日本育英会というのが廃止されるということは、これは昨年の１２月に閣議決定された。新たな事業を展開するということで、充実拡大をするという方向性として発表しているのか、そこのところをちょっとお知らせいただきたい。","respondent":"宮地区民課長","answer":"この新たな部分につきましては、一たん廃止して、次に留学生を支援するさまざまな法人もあります。新しくできました新たな学生支援機関のあり方については、あくまでも中間的なまとめとしては、そういう方向が出ております。","id":"exchange-004"},{"speaker":"三上委員","kind":"質問","question":"そうしますと、今日までの日本育英会の制度そのものというのは、相当古い、長期間やっている制度です。今の時代に、やはり見直しをしなければならないということが前提となっているというふうに考えてよろしいんか尋ねました。","respondent":"宮地区民課長","answer":"似たような機関につきましては、一たんそれぞれ廃止して、統合することでさらに効果的な資金の活用方法ができるのではないか。それから教育的指導の充実とか、そういったところも再度見直しが必要であるという、時代に即した方向での見直しをしていくです。","id":"exchange-005"},{"speaker":"三上委員","kind":"質問","question":"この請願書によると、「これは、経済的に困難な人々に教師や研究者への道を閉ざすことになります」と。この教職についた人についての、教育職についた場合の返還免除というものですね、何年度にこれが適用されたんか尋ねました。","respondent":"宮地区民課長","answer":"これから細かく検討する部分ですので、その方向性としては、「大学院生返還免除制度は廃止し」といったことになってあります。やはりこれから研究に従事し、これがまだ中身がちょっと出てこない中で、それの大々的な政策的手段は対応するということが書かれております。","id":"exchange-006"},{"speaker":"三上委員","kind":"意見","question":"毎年自宅外通学者は３２１万円もかかるんだと、これは大変じゃないかと、そういう印象しか与えないとしか思えない。そこらあたりはどういうふうに受けとめていますかとの意見を述べました。","respondent":"宮地区民課長","answer":"これに掛ける４という形になってきますので、初年度という表現に改めませんと、ちょっと誤解を与えかねないというふうに私自身も思っております。","id":"exchange-007"},{"speaker":"三上委員","kind":"意見","question":"どういったところを借りるかといったら、家賃１０万円とか、やっぱり感じてならない部分があるわけです。どうでしたか、そこはとの意見を述べました。","respondent":"宮地区民課長","answer":"それから、無利子貸与、今おっしゃられた中には、返還の免除、免除期間、猶予期間というのも設けておりまして、それはそれぞれの事情により相談に乗っていただけるというふうに伺っております。","id":"exchange-008"},{"speaker":"三上委員","kind":"質問","question":"あわよくば免除してくれというような言い方をしたいのかどうかわかりませんけれども、だけれども、国はきちっとやると言っているんでしょう。どうか尋ねました。","respondent":"宮地区民課長","answer":"都道府県等に権限をおろして都道府県とまた区市町村が連携して考えていっていただきたいと、やめるとか何だとかということではございません。新たな学生の支援機関ということですから、何だかの形の機関、支援は引き続きしていくと、そういう内容です。","id":"exchange-009"},{"speaker":"三上委員","kind":"質問","question":"最後に、じゃあここのところで出てきている「長引く不況のなか、今こそ日本育英会奨学金制度の充実、学生の勉学条件の保障を守るため」ということについて、そういった目的に向かって今政府は見直しをしようと、進んできたよというふうに解釈してよろしいんか尋ねました。","respondent":"宮地区民課長","answer":"見直すべきものは見直し、さらに時代にマッチした支援のあり方を考えていくという方向で受けとめてあります。","id":"exchange-010"},{"speaker":"松澤委員","kind":"質問","question":"新たな入試制度、日本育英会そのものは廃止されますけれども、新たな手法で奨学金を行なうという方向性は正しいものかなというふうに思います。ところで、この奨学金制度ですけど、品川区にもありますけれども、この滞納者はどれぐらいのパーセンテージいるものなんか尋ねました。","respondent":"宮地区民課長","answer":"平成１３年度末で１２.８％の滞納率です。","id":"exchange-011"},{"speaker":"松澤委員","kind":"意見","question":"この滞納者の１２.８％のもうちょっと詳しい、どういう意味で滞納されているのか。そういうものも含めて、あるいはそれ以外の方は返せるのに返せないというふうな解釈をしていいのか、その数字等をお願いしますとの意見を述べました。","respondent":"宮地区民課長","answer":"区外の割合がほぼ５対５なんですけれども、高齢者の方を使いまして、債権回収に努めているところです。着々と上がってきているんですけれども、それでもなかなか難しい例がございまして、引き続き回収に努めていきたいというふうには考えております。","id":"exchange-012"},{"speaker":"松澤委員","kind":"質問","question":"そういうものに対する借りる方の意識というのは結構強いものなんでしょうか。これは返していただいたのを次の方に回すんですよという話をされているんですか、その辺の貸すときの心構えみたいなものはどうなんか尋ねました。","respondent":"宮地区民課長","answer":"これは卒業のとき、そのときにはもう一回借用証書をつくっていただいた段階で再度そのお金は自分で返していくものだというふうにまた言っております。","id":"exchange-013"},{"speaker":"松澤委員","kind":"質問","question":"平凡な頭で考えてみると、教師になった方はそこで収入があるわけですから、私は返せるものだと思うんですね。研究者というのは大学に残るわけですから、確かにこれはそういう研究者にはまた別途な奨学みたいなものがあるんですけど、説明してもらえますか。","respondent":"宮地区民課長","answer":"ちょっと今全部お答えできませんが、今後も競争的支援方法というのをやはり考えていくというふうに先ほどの中間の取りまとめで書いてあります。競争的資金の拡充等を別途の政策的手段により対応するです。","id":"exchange-014"},{"speaker":"松澤委員","kind":"質問・要望","question":"やはりこのまま日本育英会奨学金制度の充実を求める意見書を出してくださいというまでは私たちとしてはいかないというふうに考えております。どうしても意見書を出さなくちゃいけないなという質疑はありませんので、そういう意味ではどうかなというふうに思っているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-015"},{"speaker":"鈴木（真）委員","kind":"質問","question":"育英会自体の中で、全体というのはある程度数字がわかるのかどうか。その点を説明するよう求めました。","respondent":"宮地区民課長","answer":"それから、東京都の育英資金は３４３名、それから日本育英会の奨学金で都内にある高等学校に通っている奨学生の数が４,１００名ということです。それで、滞納者数というのは、ちょっと数は出ていませんので、もしまたちょっと調査しましてわかりましたらお答えします。","id":"exchange-016"},{"speaker":"鈴木（真）委員","kind":"意見","question":"実際の数字、右側の返還例のところに利率は年３％で貸与されたということが出ていますけど、現実の数字を見ているともっとかなり低いんですね。","respondent":"宮地区民課長","answer":"日本育英会のほうの個々の金利はちょっとつかんでいないんですけれども、ホームページで見ましても、ちょっと出てこなかったんですが、電話してもあまり細かいことをちょっと教えていただけないものですから。","id":"exchange-017"},{"speaker":"鈴木（真）委員","kind":"質問","question":"充実はされてきているんじゃないかなという思いがあるんですけど、その全体像としての充実度ということに関してはどのようにお考えでしょうか。私は充実しているんじゃないかなと思うんですけど、その辺、いかがか尋ねました。","respondent":"宮地区民課長","answer":"さまざまなメニューをつくってまいります、この間。そういう意味では、利用しやすいような形に組みかえ、再編されつつ、充実の方向で来ているというふうに理解しています。","id":"exchange-018"},{"speaker":"本田委員","kind":"意見","question":"科学の進歩においても、こういう奨学金制度が大きな役割を、ある側面では果たしてきたというふうに私は一般的に思っているんですよね。改善改革をしながら制度としては残していくべきものだろうというふうに考えているんですが、一般論ですけれども、その辺の中身といいますかとの意見を述べました。","respondent":"宮地区民課長","answer":"国もその方向で考えておりまして、年金制度を活用した奨学生への支援など、さまざまな方法を検討しているというふうに伺っております。それを新たな形で立ち上げて支援をするという、そういう方向性でこの奨学制度を充実するということですので、理解といたしましては。","id":"exchange-019"},{"speaker":"本田委員","kind":"質問・要望","question":"ですから、教育にはいろんな意味で今の時代に合った、また先を見通した改革推進をしなければならないと私などは思っているんですよね。国のレベルの制度改革ですから、奨学金制度の充実を求めるということにおいては、私はそういう考え方は必要だろうというふうに思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"大学生活に対して不安に思っていることは何ですかというふうな、奨学金を返していくことそのものも大変な状況というふうなのがあると思うんですね。そういう中で、さらにもっと育英会の奨学金というのは充実が求められているところに財政的なことを理由にそうやって削っていくということに対しては。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-021"},{"speaker":"三上委員","kind":"確認","question":"私どもの国会議員が文部科学大臣に確認したことの内容においても、確かに日本育英会は廃止するけれども、その内容については後退はさせないと。既に国はそういう考え方でありますので、改めてこの請願を文書として出す必要はない、こういうふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"今回奨学金に対しても無利子の奨学金を１６,０００人も削減というところでは、やはりこれは今の奨学金を充実させていくというふうなところからも、この請願に対しては採択をお願いしたいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-023"},{"speaker":"本田委員","kind":"意見","question":"だから、制度充実の意見書を出す。日本育英会という名前がどうかということにはこだわらない、そういう意味で趣旨に賛成ということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"高木委員","kind":"質問・要望","question":"せっかくのあれも返さないというんですか、お伺いしていれば、やっぱり刻苦勉励ということも乗り越えていってもらわなければならない。そういう国家制度をいじくるというんでしょうか、ちょっと全然よくとらえていないことがありますので、ちょっと保留にさせていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"高木委員","kind":"質問・要望","question":"議事進行については委員長の采配で結構ですから。委員長の権限で議事は進めていただきたい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"三上委員","kind":"意見","question":"意見陳述については、今理事者の答弁がありました。それについて具体的に質疑もしないうちからそれを論議するというのは、やり方としてはちょっと違うんじゃないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-027"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここにもほんとうに文章の中には大変だというふうな思いがかなり書かれていますけれども、そういうふうな実態をお聞きして、そしてそれをわからないところも含めて深めるというふうな形でできるといいなというのが私の思いなんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"松澤委員","kind":"意見","question":"終わった段階で陳述人から聞いたほうがいいのか、理解を深めて聞かなくてもいいですよという話になるかという話で、最初から聞きましょうという議会の進め方を今までしていなかったような気がしましたけどとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"鈴木（真）委員","kind":"質問","question":"終わってからするというのは、そこで陳述を受けるか受けないかを決めるということですか。今するというのは、するというと、質疑が終わった後に陳述を受けますよと聞こえるけど、そうじゃないわけですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"松澤委員","kind":"質問","question":"書記がいらっしゃるので、どういうふうな形で今まで意見陳述を受けているのか教えていただけますか。","respondent":"事務局","answer":"私が聞いている範囲では、過去両方あったというふうな形では聞いております。去年の場合ですと、先に質疑をやって、最後に意見陳述の申し出を受けるかどうかを諮るというような形であったかというふうに記憶はしております。","id":"exchange-031"},{"speaker":"本田委員","kind":"意見","question":"検討して、一応意見を聞くか、どうするか。私は別にそうこだわってはいませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-032"},{"speaker":"高木委員","kind":"質問","question":"どういうふうにやっているかということを全然知らないと、これもまた問題ですから、どこに設定するかは委員長の判断でしょう。これは受けるかどうか、どこでやるかは委員長が少し検討されてから取りかかってほしかったなと思いますけどね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-033"},{"speaker":"三上委員","kind":"意見","question":"理事者からの説明しかまだ受けていないのに、そのままで意見陳述が必要なのか、必要じゃないのかという判断はできないでしょう。そういうただ今度意見陳述を先にやるべきなのか、やらないべきかと、そういうことを論議すること自体が違うんじゃありませんかと言っているんですよとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-034"},{"speaker":"本田委員","kind":"質問","question":"こういう意見陳述の申し出がありますということでいいんじゃないですか。私の意見はさっき言ったように、意見は聞いてもいいんじゃないかなというふうには受けとめていますよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-035"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"私は事前に聞いて、それから進めていただきたいというふうな思いなので、そのことについてぜひとっていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"南委員長","kind":"質問・要望","question":"この業者婦人の地位向上に関する請願についてのご質疑、ありましたら、お願いいたします。ちょっと私のほうから伺いたいんですけれども、この１５０人というのは、この二つをちょっと教えてほしいと求めました。","respondent":"市川産業振興課長","answer":"要は先ほど説明を申し上げましたが、例えば従業者数の数について、要するに内訳の男女内訳というものは把握ができないです。これは男女合計の数が２万２,０００人です。","id":"exchange-037"},{"speaker":"鈴木（真）委員","kind":"質問","question":"データ的なことで小売業２万２,０００人というお話がありましたけれども、こういう女性、零細工場の方の事業所数というのはどのぐらいあるんですか。それはわかりますか、工場。","respondent":"市川産業振興課長","answer":"それと、さらに４人から１９人という従業者規模のところが約４０％です。９２％の事業所が１９人以下の事業所ということになりますので、いわゆる町工場での家族従業者としては、その数字から推測できるものと思います。","id":"exchange-038"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今製造業のところは数字を教えていただいたんですが、そういう中小業者の内訳がどういうふうになっているのか教えていただきたいのと、ちょっと教えてほしいと求めました。","respondent":"市川産業振興課長","answer":"それから廃業の関係は、これは５年置きの事業所統計の差をもってよくとらえるんですが、廃業の傾向はちょっとこの場ではお答えすることができません。数字の傾向としては、昨年の同時期の数字とそれほど大きな状況の違いはございません。","id":"exchange-039"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"じゃあ朝はどうなのかといったら、そういう中で、区がどういうふうな認識を持たれているかということについてお聞かせいただけたならと思うんですが。そういう健康が損なっているんじゃないかというふうな実態なんかも把握されているところがありましたら、ちょっとお聞かせほしいと求めました。","respondent":"市川産業振興課長","answer":"なかなかそういう客観的な把握は難しいということが一つあります。２番目の健康の問題については、先ほど申し上げたように、直接私ども行政としてこれについて事情を把握しているということはございません。","id":"exchange-040"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"ここも５７.１％の人がぐあいが悪かったり、実態をいろいろと調査をして見えてくれば、そういう点ではいかがでしょうか。実態をつかめば、つかむということの必要性というふうな感じ。","respondent":"市川産業振興課長","answer":"現状では調査をする必要がないと判断をしているということで説明をさせていただきましたけれども、それなりの行政のニーズと申しましょうか、先ほど申し上げた現状でそういった調査をする必要はないという判断をしているということでご理解いただければと思います。","id":"exchange-041"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"６,０００人が対象で、一つの商工会に対して１０人の調査にしかならなかったということで、それはちょっとそういうふうに思いました。それともう一つお聞きしたいのは、ここら辺のところで、区として把握している実態というのがあったら説明を求めました。","respondent":"市川産業振興課長","answer":"産業ニュースの関係につきましては、先ほどちょっと説明が走っちゃったせいなんですが、それについては積極的に協力してきましたという説明です。今の厳しい経済状況の中で、少なくとも私ども窓口では、そういった声はあまり寄せられていないというふうに私自身は認識しています。","id":"exchange-042"},{"speaker":"松澤委員","kind":"質問","question":"品川区の事業者というんですかね、いろんな話を伺いましたけど、自分たちの組織内で調べた中で１５０人というようなとらえ方でいいんでしょうね。理事者、いかがか尋ねました。","respondent":"市川産業振興課長","answer":"私自身、この調査を行なったということも、この請願書を見て初めて知りました。今のご質問、ちょっと答える材料を持ち合わせておりませんので、ご理解をお願いいたします。","id":"exchange-043"},{"speaker":"松澤委員","kind":"意見","question":"１００％の回答。態度そのものは固まってきましたので、後で述べてくださいということは述べますけれども、そんなことを述べさせていただきまして終わりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-044"},{"speaker":"本田委員","kind":"質問・要望","question":"その前に、区内でいろんな商業、工業、団体のあれからは、いろんな要望を受けていますが、民主商工会は受けていない。貴重なデータであるならば、特に行政に要望を出せば、少しでも問題が解決するというようなことで、私などは考えるんですけれども、どうか尋ねました。","respondent":"市川産業振興課長","answer":"先ほどと同じような繰り返しの答弁になろうかと思いますが、こういった調査なりあるいは調査結果、これまで知らなかったということがあります。そういったことで、経過を承知していないということで、これ以上なかなか説明できないという私自身の置かれた立場です。","id":"exchange-045"},{"speaker":"本田委員","kind":"質問・要望","question":"全都というふうに書いてありますから、東京都にはやったのかもしれませんが、区でこういう団体が調査活動をやった結果についてぜひ聞いてくださいと、また、行政にも取り入れられるものは取り入れてくださいというような要望があった場合は、それは話には応じるんか尋ねました。","respondent":"市川産業振興課長","answer":"こういう結果が出たということを申し添えられて、こういうことを実施してほしいというような、そういったことをお受けすることはあります。","id":"exchange-046"},{"speaker":"本田委員","kind":"質問","question":"ですから、また品川区の比較した部分とあるんでしょうから、話を聞いて。だけど、今日ここでそのまま１、２番で出すというのはどうなのかなと思うんですが。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-047"},{"speaker":"鈴木（真）委員","kind":"確認","question":"不利益というのはあまり納得いかないなというところでもう一回ちょっと確認したいのと、今女性起業家向けのフォーラムをやっていらっしゃいますね。１番の業者婦人の実態、質問が漠然としているんですけど、担当部局としてはどういうふうに考えられるのかなと思うんですが。","respondent":"市川産業振興課長","answer":"先ほど説明させていただいた折にも触れられましたけども、女性であるがゆえに融資なり、私どもの相談窓口に来る件数は数が極めて少ないものです。そういう趣旨に私どもも賛同して、この区商連の女性部の活動に対しては区商連に対する助成の一環として支援をしています。","id":"exchange-048"},{"speaker":"鈴木（真）委員","kind":"意見","question":"そこの部分を抜きで話が出てしまうんじゃないかなというのを私は逆に今までの経験からすると感じるんですけれど、そこら辺はどうお考えになるのか。何か余りにも漠然としちゃっているんですけど、この２点、もう一度お尋ねしますとの意見を述べました。","respondent":"市川産業振興課長","answer":"１点目の問題ですけれども、先ほどのちょっと説明で言葉が足りなかった部分の補足を含めて申し上げますと、持ち込んだ方の主観でもって持ち込みます。それと２点目の部分ですけども、この自家労賃、社会保障の枠云々というのはちょっと把握しづらい部分であると考えています。","id":"exchange-049"},{"speaker":"鈴木（真）委員","kind":"意見","question":"それを事業として生かせるかどうかの、そこの部分になってくると、ちょっとニュアンスが違うかなという考え方を持ちました。これは意見で終わりますとの意見を述べました。","respondent":"松崎税務課長","answer":"特に男女の差別はない、いわゆる必要経費で落ちるか落ちないかの問題ですので、家庭従業員として必要経費で落とすとすれば認めております。","id":"exchange-050"},{"speaker":"三上委員","kind":"質問・要望","question":"ですから、ここのところで本来だったら、区民委員会として議長に差し戻しということもあり得るかなというふうに思うわけですけども。いろんな幅広く皆さんに知っていただきたいということであれば、働く女性というんでしょうか、独身女性だっているわけですしね。","respondent":"太川区民生活事業部長","answer":"あくまでもここでは産業振興のスタンスの中でご答弁していますので、そこのところは一応ご了解いただきたいと思います。現在のところ、そこまではまだ言及をしていないという状況ですので、一応ご報告します。","id":"exchange-051"},{"speaker":"本田委員","kind":"質問","question":"２番を、議会に来た請願ですから、行政には出していないというんでしょう。いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"高木委員","kind":"質問","question":"こうしたらどうかとか、いろんなことについての判断権を持っているわけですから、こう思うわけですね。ですから、もう少し例えば２番目の女性事業主が不利益を受けることのないように各分野に指導してください、行き渡ってきつつあると思うんですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"だけど、ここに書かれているように、大変だという実態というのも実際すごく大変な実態というのがあるんじゃないかと思うんですね。そしてどういう思いで出されたのか、どうしてほしいのかということも含めて、ぜひ意見陳述を受けてみたいというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-054"},{"speaker":"高木委員","kind":"質問","question":"お見せするという場面の展開になるわけですから、その必要性があるかどうかとか、これはいろいろ意見がありましたよね。だけれども、これは文章によって出ているわけですから、概ね私は真意は伝わっているんではないかなとも感じさせていただいておるわけなんですがね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-055"},{"speaker":"松澤委員","kind":"質問","question":"この陳情書、今の審査、各委員の質問と理事者のお話を承りまして、私どもは結論をどうするかまでわかりました。ですから、疑問点がございませんので陳述は必要ございません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"三上委員","kind":"質問・要望","question":"そして、国民本意の税制、税務行政の民主的改革を求め、申告納税制度と納税者の権利を守る運動を進めてきました。こういう取り組みを行なっているということですから、これはこれでやっていただければいい。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"松澤委員","kind":"質問","question":"聞かれていないからしゃべっていないだけの話で、意見陳述についてというから意見陳述について述べたわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-058"},{"speaker":"松澤委員","kind":"意見","question":"区民委員会の中で一生懸命審査するには分割ではなくて、区民委員会全部総合という形でできればいいなと思いますね。特に、紹介議員がいらっしゃいますので、これを出されたのが１１月１５日、本会議……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"松澤委員","kind":"質問・要望","question":"できれば紹介議員になっていただきたい方と前もって打ち合わせていただいて、私たちとしてもしっかり審査できるのかなというような気がいたします。請願者に対する態度としては、残念ながら願意に沿いがたいということです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-060"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"今回２２年ぶりにされたということも、改めて私は実態調査は区としてやっていただきたいというふうに思いますし、採択をお願いしたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"本田委員","kind":"質問・要望","question":"今日は継続扱いにしたらいかがですかということです。そういうふうに思っておりますので、今日のところは継続扱いにしたらいかがですかというのが意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"松澤委員","kind":"質問","question":"そこにいろんな中で付託されてきたことですから、総務委員会のすり合わせの道具ですから、これはここで。３会派ですか、それはやっぱり多数決の中では申しわけないですけど、委員長がしっかりと決をとっていただくよう求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-063"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"すみません。今、ぜひそれに対しては聞いて答えていただきたいという要望がありましたけれども、ぜひ要望を聞いていただきたいということに対しての。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"本田委員","kind":"質問・要望","question":"そこまで区の答弁を求めていないのは、また、この面でもぜひそのような対応をしていただきたいという要望だけにとどめて私はいるわけなんで。改めて、答弁を求めるみたいになってしまったのでそれを強調しておきますので。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"}]},{"id":"topic-02","title":"平成１４年請願第３０号、都市計画道路補助第１６３号線拡幅と大井一本橋商店街振興組合に関する請願（請願項目２）","agenda":"平成１４年請願第３０号、都市計画道路補助第１６３号線拡幅と大井一本橋商店街振興組合に関する請願（請願項目２）","exchanges":[{"speaker":"三上委員","kind":"質問","question":"それからこの情報公開ということが制度としてあるわけですから、前記、そこでどういうふうな意見が出されたのかということが出てこない限り。ですから、そこのところで、本日のところは今説明を受けましたけれども、私はこれ以上質疑はできないだろう。","respondent":"市川産業振興課長","answer":"そういったことを商店街の皆さん自身も当然承知しているわけで、今の商店街の組織の中だけの検討だけではままならない。","id":"exchange-066"},{"speaker":"三上委員","kind":"質問","question":"各議員が定数で４２人いるわけですから、審議会なり何だかをつくらざるを得ないということになったときに、そういう部分がほんとうにそういうふうな形で今までの事例の街づくりの中でそういったことがあるのかないのか。","respondent":"市川産業振興課長","answer":"先ほどの説明をもう少し補足しますと、公的な検討機関、あくまで地域の中での私的な検討組織として。地元の議員の皆さん方にも協力してもらいながら、いろいろ意見を仰ぎながら事を進めていきたいという趣旨ということで受けとめてあります。","id":"exchange-067"},{"speaker":"三上委員","kind":"意見","question":"今課長が受けとめている趣旨ということがわかれば、私もそう受けとめたいと思いますけども、そういうような形で様子を見たほうがいいんじゃないかなというふうに思っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"高木委員","kind":"質問","question":"これは行政のやることに議会が一切どうやってくれというのが請願ですから、判断してくれというのが請願ですから、こういうことは初めてですし。これをだから、言いっ放しでは何かあれでしょうから、これを採択したらどういう官民一体、みんなで協力してくれという気持ちの意味が濃いんですね。","respondent":"市川産業振興課長","answer":"この２番目の私の受けとめ方は、商店街自身が取り組まないことには前に進んでいかないわけでございまして、百も承知しています。地元の商店街、私ども行政と区議会の役割を承知した上で気持ちのほとばしりとしてこういう形で自分たちは進めたいので、私自身は受けとめてあります。","id":"exchange-069"},{"speaker":"高木委員","kind":"質問","question":"これは仕事をするのはお役所ですから、どういうふうにするつもりだと聞くのはしようがないですね、そういう意味で今回。伺えば、これはどうして、どうしてもう少し多い数でないのかなと感じるものですからね。","respondent":"市川産業振興課長","answer":"今回請願をいただいている皆さん方は、一本橋商店街振興組合の役員の皆さんで、要するに組合員の総意としてこの請願を提出するという趣旨です。","id":"exchange-070"},{"speaker":"本田委員","kind":"質問","question":"決定するわけですから、あくまでも勉強という枠内だろうと思いますので、２番の解釈はね。今日は継続を。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-071"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"基本的なことをちょっと教えていただきたいんですけど、その中でその後も継続して商店をやっていきたいというふうなところが何店舗あるのかというふうなあたりを一つ教えていただきたいのと、ちょっとお聞かせいただきたい。","respondent":"中島街路事業担当課長","answer":"本年４月１２日に事業認可を取りまして、その後補償説明会や測量説明会等ございまして、実際の権利者１件１件の方に個別に交渉に入ってあります。これにつきましては、協力していただいているということが、今回のこういった事業進捗になっているというふうに考えてあります。","id":"exchange-072"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"それをどうするかというようなことに対して１件１件個別に交渉しているというふうなことなんですけれども、それ以前には多分商店街の方たちがどういう要望だとか、そういうものはいつごろどういう形で聞かれているのか。","respondent":"中島街路事業担当課長","answer":"その前も若干接触はありましたけれども、昨年の８月３０日にこの事業の事業説明会というのを開催させていただきました。引き続きまして事業化を進めていきますという説明会をさせていただきました。","id":"exchange-073"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"数えきれないくらいの説明会や理事会、それから商店街の役員の方たち、また説明会というふうな形でされてきたということなんですけど、１件１件の権利者というふうなところには今回の交渉以外ではどういうふうな意見や要望の調査というものはされているんか尋ねました。","respondent":"中島街路事業担当課長","answer":"そういった形で１件１件、比較的早く交渉をしたいという方が結構多くいらっしゃいまして、その方たちを中心に今折衝しています。その個々の店舗の今後の生活再建という形でさまざまな意見交換なり、こちらが相談をお受けするなりという形で折衝を進めているです。","id":"exchange-074"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今言われた個別の交渉ということで現在４０件というふうな、そこのところは個別の交渉というふうなところの今の進捗状況だというところですね。それ以外のところで、そういうふうなところでも一定意見を聞くというふうなところで個別に当たっているということは特別ないんか尋ねました。","respondent":"中島街路事業担当課長","answer":"別に、窓口はやっぱり私ども商店街振興組合の話をする際には、組合の役員の方等を中心に話してもらうというふうに考えております。","id":"exchange-075"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"どういうふうな可能性というか、どういうふうな形で商店としてやっていく道というのがあるのかなというのが、ちょっとよくわからない部分があるんですがとの意見を述べました。","respondent":"市川産業振興課長","answer":"まさにその点を検討しようというのが、この今回の請願の２番目で出されている項目、趣旨です。","id":"exchange-076"},{"speaker":"松澤委員","kind":"質問","question":"今のところ、商店が１軒ぐらいしかないというようなことで、そういう意味で寂しいなと思います。それについて、容積率の緩和等ができているんでしょうか、その辺をちょっと聞きたいと思います。","respondent":"中島街路事業担当課長","answer":"この１６３号線の都市計画決定は、昭和３９年にされてあります。一定の建築制限がされてまいりますので、計画線まで低くして、建ぺい率なりをもとにして建て替えをされているというふうになってあります。","id":"exchange-077"},{"speaker":"松澤委員","kind":"確認","question":"大きな商店は途中から３階か４階になっていまして、全部土地もとられてしまう、なくなってしまうと。その確認をしておきたいんですけど。","respondent":"中島街路事業担当課長","answer":"例えば残りが極端に１０平米ぐらい残ったとしても、その土地の中で再建するというのは実質的には不可能に近いのかなということになります。もう一枚裏側の方とお話をして、そこの土地について、広く残れば単独でもってそこで再建というのは可能かなというふうに思います。","id":"exchange-078"},{"speaker":"松澤委員","kind":"質問・要望","question":"あれが適当な広さがなかった場合、それは会館が建てられなくなったことを仮定した場合、それは振興組合の組合員に分配して返すものなんでしょうか。その辺のことまでおそらく商店街を考えているんだろうと思うんですが、その辺はどういうものなんですかね。","respondent":"中島街路事業担当課長","answer":"それと２階の一部、塾に貸しているというようなこともありますので、そういった部分では営業的な補償もあります。どういう形でそれを活用、あるいは使っていくのかというようなことについて、振興組合さんのほうで決めるものというふうに考えてあります。","id":"exchange-079"},{"speaker":"松澤委員","kind":"質問","question":"こういう分割でポンと見なくても、建物の審査とか、いろんな質問をこれから継続して次の委員会でしてよろしいんですかね。それはよろしいということですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-080"},{"speaker":"高木委員","kind":"質問","question":"とにかく１番ですか、情報公開してほしいと言っているんですから、これは全く無関係とは私は言い切れないと思いますね。ですから、これはやっぱりそれを受けとめた私どもが意見を申し上げたいと思いますので、ひとつ所見を承りたいと思います。","respondent":"中島街路事業担当課長","answer":"あるいは商店街以外の方も含めて、いろんな研究をしていただきながら、つくり上げていくものではないのかなというふうに考えているところです。","id":"exchange-081"},{"speaker":"高木委員","kind":"意見","question":"その都市機能はどういう役割を果たしているかと、街の中で、ここは。これがまず第一の……との意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-082"},{"speaker":"高木委員","kind":"質問","question":"それが商店街であるということを忘れちゃ困りますよという言い方もあれですけども、そういう基盤なわけですから、都市基盤がそうでしょう。それを申し上げる。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/345074?Template=document&Id=2346#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":60248,"voices":210}},{"id":"h14-20021125-7","meetingId":"h14-cm11","date":"2002年11月25日","dateIso":"2002-11-25","committee":"厚生委員会","time":"午前１０時０６分～午後３時０１分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を86件整理しています。","topics":[{"id":"topic-01","title":"平成１４年請願第２６号、一人一人の子どもたちが大切にされる品川区を求める請願。このうち請願項目として、１番、２番、３番、４番、５番、６番、７番","agenda":"平成１４年請願第２６号、一人一人の子どもたちが大切にされる品川区を求める請願。このうち請願項目として、１番、２番、３番、４番、５番、６番、７番","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"待機児解消についてお伺いいたしますが、第４回定例会で、待機児解消策はどのように取り組んでいくのかという質問をさせていただきました。第３回定例会から第４回定例会にかけて、まず、変わったことは何かあるんか尋ねました。","respondent":"金子保育課長","answer":"待機児は、最近非常に急増していますが、これについては、適切な対応を考えていく。その際には、例えば分園なり、認証保育所なり、さまざまな手法によって臨んでいきたいということについて、特段、変更はございません。","id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"次に、請願項目３番の給食水準を落とさないためにとあるんですが、給食水準というのは何なんか尋ねました。","respondent":"金子保育課長、小沼福祉事業部長","answer":"水準を落としていこうという考え方は一切持っておりませんし、基本的に、園長を中心に園のほうで対応する。そういう意味では、安全衛生面についても、より徹底してきているかなと考えているところです。 細かいことをるる説明いたしましたけれども、食品構成、あと食材の購入の関係です。ないしは４点を基準に献立作成いたしますから、そういう点での水準の変更とか、基本的にはない。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"次に請願項目４番なんですけれども、親の就労を考慮してくださいということですが、親の就労は、今まで考慮してないんか尋ねました。","respondent":"金子保育課長","answer":"例えば、あるいは日曜日に実施してほしいとの要望が多数であっても、すべての方の要望にこたえることはできないのが現状だと考えているところです。","id":"exchange-003"},{"speaker":"築舘委員","kind":"質問・要望","question":"最初に質問するのは、品川区が行った顧客満足度調査結果ともほぼ同じようなものになっています」とあります。要するに、保育問題協議会のアンケートと同じだということを言っているわけですけれども、現実的に同じかどうかということを教えていただきたい。","respondent":"金子保育課長","answer":"私どもとしましては、私的なアンケートの実施に対しては関知するところではございませんので、同じかどうかということについても、認識はしてございません。","id":"exchange-004"},{"speaker":"築舘委員","kind":"質問","question":"品川区が行った顧客満足度調査というものがあるわけですから、何も、保育問題協議会がみずからアンケートを取ることはないのではないか。要するに、一括して品川区の調査に任せればいいじゃないかと思うんですが、その点に関してはどうか尋ねました。","respondent":"金子保育課長","answer":"私どもとしましては、私的な団体が私的に行っているアンケートですので、特段にやってはいけないとか、やるべきであるとかということについては、意見を申し上げる立場にはないと考えます。","id":"exchange-005"},{"speaker":"築舘委員","kind":"質問","question":"正規職員の体制不足ということですね。正規職員が実際に現在の仕事を一生懸命にしているのかどうか、正規職員が仕事をしっかりとしているかどうかということを、どうか尋ねました。","respondent":"金子保育課長、辻田児童課長","answer":"そういう意味では、職員についても、各園長が適切に配置して、問題がないと認識しているところです。事実、例えば園長会等でそのような意見が上がってきたことはございませんので、特段問題なく勤めているものと考えております。 児童センターにおきましても、一体的運営を始めましてから、非常に効率的な形での園運営がなされております。その中で、職員、館長のもと、みんな努力して適正な職務をしているということで、私どものほうは考えております。","id":"exchange-006"},{"speaker":"築舘委員","kind":"質問","question":"非常勤職員が、この場合、一生懸命仕事をしていないんじゃないかという指摘もされるかもしれないので、そこのところの、非常勤職員の今の仕事の状況はどうか尋ねました。","respondent":"辻田児童課長、金子保育課長","answer":"いろいろな形で幼児の取り組みであるとかということを実施していたわけですけれども、一体的運営の形で、だんだん是正されてきたです。非常勤職員も非常に努力して、子どもたちと一緒に頑張っているという状況です。 私ども保育園の非常勤職員につきましても、特段問題なく一生懸命働いていただいていると考えております。現在、非常勤職員についても、非常勤職員のレベルアップを目指して何らかの研修について対応していきたいと考えているところです。","id":"exchange-007"},{"speaker":"築舘委員","kind":"質問","question":"園の近くの方が意外と多いのではないか。自分の子どもも面倒見てきたわけですから、私は思っているんですが、どうか尋ねました。","respondent":"金子保育課長","answer":"委員、ご指摘のとおり、私どもとしましては、４０歳以上の方というふうに制限しているわけです。品川区の実情を考えながら、いろいろ考えながらやってきていただいているところは、ご指摘のとおりだと思います。","id":"exchange-008"},{"speaker":"築舘委員","kind":"質問","question":"この体制をとれば完璧だと思うんです。そこの正規職員の指導するという意識がどうかなというところをちょっと疑問視はしているんですが、その点はどうか尋ねました。","respondent":"金子保育課長","answer":"一般的な事柄についてご説明した後、その園の実情と配置の部分について説明を受けて、担当の常勤保育士から指導を受けるという流れになっております。今のところ、１００％というのは難しいかもしれませんけれども、一定程度指導についてできていると考えております。","id":"exchange-009"},{"speaker":"築舘委員","kind":"意見","question":"今までずっとお答えいただいたように、現状、今の体制がうまくいっているなという感じがしております。それはチーム全体で改善をしていけばいいことであって、今回の請願項目のようなことをやっていく必要は、私自身はないと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"金高委員","kind":"質問","question":"１点だけ、お伺いします。多分公的な調査ですから、その辺を掌握しているかどうか、お聞かせ願いたいんですけれども。","respondent":"金子保育課長","answer":"こちらの団体が実施したアンケートについては、私どもの調査と比較等々のコメントについてはできないということをご理解いただきたいと思います。","id":"exchange-011"},{"speaker":"金高委員","kind":"意見","question":"あるいは、それを実際に見ていく職員、あるいはそれをサポートするための非常勤職員がいるわけであります。行政の行っている公的な調査結果というものをある程度重視していきたいと思いますけれども、その辺の考え方をもう一度お聞かせ願いたいと思いますとの意見を述べました。","respondent":"金子保育課長","answer":"それから考え方というものがなかなか保護者に理解されていない部分があるということで、現在、改善活動に努めているところです。そういったお迎えの時間の中で、いかに保護者とコミュニケーションをきちっと取っていくか等々について、改善活動を実施しているところです。","id":"exchange-012"},{"speaker":"須藤委員","kind":"質問","question":"こういった、「保育園職員を対象に」というような表現をされた場合に、服務上はどういうふうに流れていくのかなと思います。あるいはそれが上司にどう伝わっているのかなというのがちょっと気になるんだけれども、その辺の流れはどういうふうになっているんか尋ねました。","respondent":"金子保育課長","answer":"例えば休憩時間であるとか、時間外であるとか、そこの部分でなされているのかなと考えているところです。これに答えることが服務に関してどうかというのは、現在のところは、直ちにそれが服務上問題になるとは考えておりません。","id":"exchange-013"},{"speaker":"須藤委員","kind":"質問","question":"そうすると、例えば、職員がこういうアンケートがありました、それにお答えしましたというのを、園長は全然知らないんでしょうか。父母からこういう要求があったんでこういうふうにしましたというのは、全然連携がないというのが、今の保育園の状況なんか尋ねました。","respondent":"金子保育課長","answer":"具体的にどこでどういうふうに、どういう職員を対象にというところについては明らかになっておりませんので、それは承知をしないというのが現状です。","id":"exchange-014"},{"speaker":"須藤委員","kind":"質問","question":"全然タッチしてなけれれば、この文章で、「保育園職員を対象に」とあるけれども、答えていませんということになる。園長なり、その中のことは承知しないまま行われている傾向があるのかなという懸念をまた持っちゃうんだけれども、その辺はいかがか尋ねました。","respondent":"金子保育課長","answer":"園長が掌握すべきことだとは考えておりますが、どのような対応でやったかということについては、私のほうとしても掌握しておりません。私どもとしても掌握すべきと考えておりますので、再度、園長のほうに確認していきたいと考えております。","id":"exchange-015"},{"speaker":"須藤委員","kind":"質問","question":"職員の方々がいろいろな活動しても、上司は何も知らないでいるという風通しの悪さと言ったらおかしいけれども、その辺はどうなんですかね。それで了とするのかな。","respondent":"小沼福祉事業部長","answer":"あるいは１割から２割ぐらいかなというような状況ですから、なかなか従来のような形で捕捉しにくかったというようなところがあろうかと思います。","id":"exchange-016"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと何点か伺いたいと思います。ここでは同内容となっておりますが、改めて、区のほうの結果はどうだったのかというところをお聞かせほしいと求めました。","respondent":"金子保育課長","answer":"「悪い」というのが２４５件なんですけれども、全体の母数が１,６４５というところから見て、４７人の方が「良い」と答えている。２４５人の方が「悪い」と答えておりますけれども、あるいは、一定の満足が得られているのではないかと考えているところです。","id":"exchange-017"},{"speaker":"宮崎委員","kind":"質問","question":"改めて、そこのところを伺いたい。問題ないと受けとめているというニュアンスに取れるんですけれども、どういうふうにお考えなのか、そこのところをあわせてお伺いしたいと思います。","respondent":"金子保育課長","answer":"きちっとこちらの考えをお伝え、改善活動の一環としてやっている園が多いということで、ご説明申し上げたとおりです。これについての委員会報告のときにもご説明申し上げたとおり、回収率は低くて、５０.２％であったということが挙げられます。","id":"exchange-018"},{"speaker":"宮崎委員","kind":"質問・要望","question":"コミュニケーションを求める意見が多かったということで、やっぱり同じような傾向だと、改めて感じました。何年かの経年的なところで、概括的に説明ほしいと求めました。","respondent":"金子保育課長","answer":"７時半まで実施する園、８時半まで実施する園、１０時まで実施する園ということで。平成８年度につきましては、定数で６０３人、平成１０年度については５３５人ですが、これについては平成１４年度まで変更は特にございません。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"質問","question":"そこのところはどうでしょうか。そこのところはどうか尋ねました。","respondent":"金子保育課長","answer":"先ほど申し上げたとおり、延長・夜間保育について実施しておりますが、決して不足している人数であるとは考えておりません。つまり、職員の数は適切に配置していると考えておりますが、現在の中で、コミュニケーションについては十分とれると、私どもは判断しております。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"意見","question":"親の参加の問題が取り上げられておりまして、親が参加できる行事を縮小しないでほしいということで、私もこれは最もだなと思うんです。全部言うのが難しかったら、例えばある園では、この行事がこうなったとか、実態としてイメージがわかるような説明をほしいと求めました。","respondent":"金子保育課長","answer":"最近の子どもの長時間保育に対する考え、あるいは保護者の勤務形態の多様化に対応して、そういうふうな考え方から実施しているものです。各園で園長が判断して実施しているところですので、そういった考えに基づいて実施していると、私どもでは考えております。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと具体的なイメージをと質問したんですけれども、簡単に言うと親の都合で見直しているともとれるんですけれども、そういうことなんですか。ちょっとそこのところをもう１回、考え方を確認したいと思います。","respondent":"金子保育課長","answer":"行事については、先ほど、ご説明のところで申し上げましたとおり、第一の目的は園児についてであります。行事を実施するに際しては、４月の時点で年間計画を示す等々、お知らせ申し上げてご理解を求めているところです。","id":"exchange-022"},{"speaker":"宮崎委員","kind":"意見","question":"親の参加ということを考えると、土曜日とか、これまでの曜日設定というわけにはいかないのかと思うんです。あえて平日に、ということはどういうことなのかとの意見を述べました。","respondent":"金子保育課長","answer":"確かに多数の意見は土曜日等だと思いますが、そういう意味では、全員が満足するような日程というのは組みようがないというのが現状であります。","id":"exchange-023"},{"speaker":"宮崎委員","kind":"意見","question":"多数は土曜日でというのが、親のアンケート結果だということがわかりました。職員の配置の考え方を、時代的背景を勘案というのはどういうことなのかよくわからないので、ご説明ほしいと求めました。","respondent":"小沼福祉事業部長","answer":"つまり、そこまでいかなくても、十分に対応できる。時代的な背景、あるいは時代的な状況に応じて的確、かつ適正に職員を配置してきたというふうにご理解いただければと思います。","id":"exchange-024"},{"speaker":"宮崎委員","kind":"質問・要望","question":"そういう親のニーズというのが、今の福祉事業部長の答弁からも、そういう方向なんだなという確認をさせていただきました。質問が変わりますけれども、やっぱり行政のほうも出そうかとなるんじゃないかと思うんですが、そこのところはどうなんか尋ねました。","respondent":"小沼福祉事業部長","answer":"機械的に保育士を増やすのがベターだと、こういうふうに、私は説明しているつもりはございません。ですから、行政も東京都の今回の問題について、全く手をこまねいているということではございません。","id":"exchange-025"},{"speaker":"宮崎委員","kind":"質問・要望","question":"私の聞き方が悪かったのかどうかわからないんですけれども、アドバイス、指導を求めていることに対応するんだというお話だったんです。１年間やれなかった理由というのが、何かあるんか尋ねました。","respondent":"金子保育課長","answer":"１食分作成するのか等々さまざまな問題について整理しないまま実施してきた経過があって、一たん、全園についてストップしているというのが現状です。","id":"exchange-026"},{"speaker":"宮崎委員","kind":"提案","question":"やっぱり親も家庭に帰ったら自分でつくるわけですから、自分でも味わってみる、そういうのが当然だと思うんですよ。８割給付になるので、所得制限を撤廃したらどうかと、そういう条例提案をしたんですとの意見を述べました。","respondent":"辻田児童課長","answer":"ただ、１０月から実施したということで、１２月にその支払い部分が出てまいります。その状況で、変化を知る時期という意味では、１２月以降という考えになってまいります。","id":"exchange-027"},{"speaker":"宮崎委員","kind":"質問","question":"ほぼ２０年間で、昭和５８年からだったと思うんですけれども、実際に何名やってきたのか。それから、財政的な効果、そこはどういうふうに見ているのか、そこのところを最後にお伺いしたいと思います。","respondent":"金子保育課長","answer":"先ほど申し上げましたとおり、今手元にありますのが平成８年度からの数ですので、とりあえず先ほどの数でご容赦いただきたいと思います。","id":"exchange-028"},{"speaker":"宮崎委員","kind":"質問・要望","question":"区のほうのアンケート調査の結果でもコミュニケーションを求める声が多いということで、私は、このかぎは職員の体制だと考えております。かなり重要なポイントを、請願では突いていると思いますし、今の区民の願いを反映した内容だと感じました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"山路委員","kind":"質問・要望","question":"どのように展開していくか、先ほどちょっと話があったんですけれども、もう少し詰めて説明をしてほしいと求めました。福祉事業部長のほうから、その辺の今後の展開について、もう一つ突っ込んだ時点で聞かせてほしいと求めました。","respondent":"金子保育課長","answer":"特に、私どもとしては、時期を見て適切に対応していきたいと考えています。そういった技術を磨きつつ、適切に対応できるように取り組んでいく必要があるかなと、私ども保育課としては考えております。","id":"exchange-030"},{"speaker":"山路委員","kind":"質問・要望","question":"全国の自治体のいろいろな実例と課題ということをお聞きまして、佐世保市で行わました内容で、私は感じてきたんです。先ほど説明した充実をどんどん進めていただきたいことと、待機児童の解消を一日も早く進めていただくように、再度お願いして終わります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、議会の意志として、これはちゃんと採択をして、区に検討していただくというのが大事だと思います。ですから、これは議会として採択すべきだと考えております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"辻副委員長","kind":"意見","question":"この請願について、１から６の諮り方ですけれども、私は、願意に沿いがたいということで決定すべきであるという意見を述べたいと思います。私たちは、そういう見解から、この請願については賛成できないという意見を申し述べたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"}]},{"id":"topic-02","title":"平成１４年請願第２８号、「遺伝子組み換えイネ」を承認しないこと、並びに、表示に関して国への意見書提出を求める請願","agenda":"平成１４年請願第２８号、「遺伝子組み換えイネ」を承認しないこと、並びに、表示に関して国への意見書提出を求める請願","exchanges":[{"speaker":"宮崎委員","kind":"質問","question":"上位３品目以内で、かつ総重量５％以上でないものは対象外ということでありまして、既にもう出回っているという状況だろうと思うんです。保育園の給食等で、遺伝子組換え食品に対しての対応といいますか、考え方というのはどういうふうになっているんか尋ねました。","respondent":"島袋品川区保健所衛生課長、金子保育課長","answer":"特に主立って、遺伝子組換え食品に対する方針等はございません。 保育園の給食に関連してのお尋ねですので、私のほうからお答えします。大豆関連の商品がありますが、現在のところは、保育園では使用してございません。","id":"exchange-034"},{"speaker":"宮崎委員","kind":"意見","question":"保育園のほうは使用しないということでやっているようですけれども、今の答弁ですと、ほかのところがかなり心配なんです。保育園のほうはそれでいいと思うんですけれども、区としても統一した対応をする必要があるんじゃないかと思うんですとの意見を述べました。","respondent":"島袋品川区保健所衛生課長","answer":"区の方針がないと申しますよりも、これは国全体の問題でございまして、厚生労働省で、食品安全衛生法上で安全だと確認されておりますので、国全体の問題として、遺伝子組換え食品の安全性が確保されていると考えています。","id":"exchange-035"},{"speaker":"宮崎委員","kind":"質問","question":"これも所管が違うのかどうなのかわからないんですけれども、政策的なところも、なぜこういうイネが開発されるのかというのがよくわからないんです。そこのところはどうなんか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"トウモロコシとか、除草剤に強い大豆などは、除草剤の農薬とか害虫の農薬を非常に減らすことができる。これが一つの大きな遺伝子組換え作物に対する研究であり、あるいは、今後の目的であるです。","id":"exchange-036"},{"speaker":"宮崎委員","kind":"質問","question":"私がちょっとここで質問するのが適当かどうかわからないんですけれども、生産が伸びていくということになろうかと思うんです。それで、一方で生産を高めていくということで、素朴なところで、なぜこんなふうになるのか、そこのところがちょっとわかれば。","respondent":"島袋品川区保健所衛生課長","answer":"こと米政策としてはやってありますけれども、地球的規模で見ますと、食糧というのはまだまだ不足するという考え方を持っています。こういうことからもこの研究を進めているというのが、農林水産省、厚生労働省の見解です。","id":"exchange-037"},{"speaker":"宮崎委員","kind":"質問","question":"そうすると、農薬を散布して、環境汚染がかなり心配されるんですけれども、環境汚染の角度というのは、国で言うとどこら辺で所管しているんですか。遺伝子組換えイネは、厚生労働省ではなくて、これはそもそも国で言うとどこら辺で所管しているか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"まず遺伝子組換え食品を栽培して、それからいわゆる一般圃場、いわゆるバイオと接触するような圃場で栽培する。厚生労働省の食品安全性審査評価指針というのがございまして、そちらの審議会のほうにかけられるというようなプロセスを経て商品化されるものです。","id":"exchange-038"},{"speaker":"山路委員","kind":"質問・要望","question":"この請願書の請願項目を見てみますと、請願趣旨の中に、「遺伝子組換えイネを承認しないように」という断定的な言葉が、まず書いてあります。その辺の判断というのはどういうふうにして、どこまで研究されているのか、お聞かせほしいと求めました。","respondent":"島袋品川区保健所衛生課長","answer":"まだ商品化してございませんけれども、一部につきましては、かなりの確率で組換えの研究が進んでおります。農薬汚染がなくなるですけれども、こういうイネにつきましては、かなりの部分で進んでいます。","id":"exchange-039"},{"speaker":"山路委員","kind":"質問・要望","question":"遺伝子組換えというのは、ここにも書いてありますけれども、野菜とか、マスコミとかでいろいろ話題になっていますよね。ここにも幾つか書いてありますけれども、目的について、ここに書いてある以外に、資料があったら詳しく教えてほしいと求めました。","respondent":"島袋品川区保健所衛生課長","answer":"環境問題がありますけれども、実は、国策でありますイネゲノムという考えを持っているんです。これによりますと、鉄分とか従来のイネには少ない栄養分があるイネを開発するとか、いわゆる人体が健康になるためのイネを研究しています。","id":"exchange-040"},{"speaker":"山路委員","kind":"質問・要望","question":"まだ経験がないと言いますか、社会でのいろいろな実例が少ないので、非常に不安というイメージが先に立っているような気がするんです。これに非常に疑問を持つんですが、その辺については、どのように考えていらっしゃるのかお聞かせほしいと求めました。","respondent":"島袋品川区保健所衛生課長","answer":"厚生労働省のほうでは、いわゆるバイオテクノロジーの専門家の委員会がございまして、そこで安全性を確認するという、かなりの手続をとってあります。安全と、確かに断定はできないかもしれませんけれども、普通の食品と同じようにきちんと審査しています。","id":"exchange-041"},{"speaker":"山路委員","kind":"質問・要望","question":"なぜ、世界的な例があったら、説明してほしいと求めました。","respondent":"島袋品川区保健所衛生課長","answer":"いわゆる交配技術です。ただ、安全性に対してはかなりの確率でなされているという厚生労働省の見解です。","id":"exchange-042"},{"speaker":"築舘委員","kind":"質問・要望","question":"ちょっとわからない点があったんで質問させていただきたいと思うんですけれども、遺伝子組換え食品ということで、除草剤はまくわけですよね。だけれども、除草剤をまかなくても大丈夫なものということで解釈していいのかどうか、ちょっとお聞きしたい。","respondent":"島袋品川区保健所衛生課長","answer":"つまり、除草剤というのは、一般的に、その作物自体も枯らしてしまうようなところもありますので、それに対して強い。特定の目的の遺伝子が入っていますので、それに対してだけ強いです。","id":"exchange-043"},{"speaker":"築舘委員","kind":"質問","question":"除草剤というか、農薬と解釈していいと思うんですけれども、それを少なくはできるという解釈でよろしいんですか。安全と表示されているならば、別に使用してもいいんじゃないかと思うんですけれども、それはどういう根拠で使用しないんか尋ねました。","respondent":"金子保育課長","answer":"国として安全性が認められたものという認識は持ってありますが、現在のところは、まだ使わないという判断に立っているところです。","id":"exchange-044"},{"speaker":"築舘委員","kind":"確認","question":"不安を持つ人がいるということで、まだ使っていないということなんで、安全だという国の表示はあるんだけれども、まあそういうことでの不安もある。安全の確認がまだされていないわけですから、今はまだ確認されていないので、安全性が確認されれば大丈夫ということで。","respondent":"島袋品川区保健所衛生課長","answer":"先ほどちょっと国の施策で説明しましたけれども、農林水産省、再度またチェックしています。現在の農林水産省の段階で、ある特定のイネについては、遺伝子組換えイネの安全性が確認されております。","id":"exchange-045"},{"speaker":"藤原委員","kind":"質問","question":"資料のほうで質問しますが、具体的に、今もう現時点で流通している品物というのはどのぐらいあるんか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"ちょっと言いますと、大豆は、国内需給率が４％、トウモロコシは２％ということで、九十七、八％は輸入品です。ただ、分別されているところもありますので、そういうふうになってあります。","id":"exchange-046"},{"speaker":"藤原委員","kind":"質問","question":"その中で、組換え食品には完全に表示はなされているんか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"先ほど、ちょっと資料で条件をつけましたけれども、いわゆるしょうゆとか油につきましては、表示の義務がないです。遺伝子組換え大豆等の品目を総重量の５％以内のもの、遺伝子組換え食品を使った場合には、表示されなければならないです。","id":"exchange-047"},{"speaker":"藤原委員","kind":"質問・要望","question":"国の意見書を出す等を含めて、ほかの自治体の流れがあれば教えていただきたいんです。","respondent":"島袋品川区保健所衛生課長","answer":"現在、北区、中野区、豊島区で、同様の請願が出されているところです。北区と中野区につきましては、採択されております。","id":"exchange-048"},{"speaker":"藤原委員","kind":"確認","question":"保育園の関係で伺いたいんですけれども、イネというかお米については、もし安全性が確認されれば、現時点でのお答えでいいんですけれども、使用していくおつもりがあるかないか。","respondent":"金子保育課長","answer":"食品としての安全性というのは、先ほど申し上げたとおり、私ども非常に重視しているところですので、その安全性が確認されれば使えるものだとは考えておりますが、その時点で判断していきたいと考えています。","id":"exchange-049"},{"speaker":"宮崎委員","kind":"質問・要望","question":"先ほど、いわゆる交配による品種改良は同じようなものだという答弁だったんですけれども、ちょっと改めてその答弁を確認させていただきたいんです。私の認識は全く違うものだと思っていたんですけれども、そこのところは、改めてちょっと見解を聞きたいと思います。","respondent":"島袋品川区保健所衛生課長","answer":"いわゆる農業試験場でできましたから、あれも人為的に交配させたものです。残すための手段ですので、方法としては同じものだということで、これが農林水産省の見解です。","id":"exchange-050"},{"speaker":"宮崎委員","kind":"質問","question":"いわゆる交配は、自然の中で起きるものなんですよね。それを人の手を使うかどうかということはあるんですけれども、遺伝子組換えというのは、そうでもないということなんか尋ねました。","respondent":"島袋品川区保健所衛生課長","answer":"特定の米をつくるための交配がありますけれども、これも人為的にやるものでございまして、決して自然に新しいものができるものではございません。","id":"exchange-051"},{"speaker":"辻副委員長","kind":"質問・要望","question":"請願が出てきているんですけれども、これは理事者に求めて結論を出す話でもないんで、我々が委員として見解を述べてやらなきゃいけない。もう１回、我々が皆さん方の委員として意見を申すわけで、ほかの人の意見がどうなのかというのを聞きたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"金高委員","kind":"意見","question":"やっと遺伝子組換えについての安全性について論議が２０００年の３月から始まったということも、実際にインターネットで発信されております。私の意見としては、ここで決めるというよりも、できることならもう少し時間を置けるような継続ができればと考えていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-053"},{"speaker":"宮崎委員","kind":"質問・要望","question":"安全性が確認された時点でまた考えるというご答弁だったと思いますけれども、ご判断いただきたいということを、まず初めに述べておきたいと思います。表示の義務化も、私は当然だと思いますので、品川区議会としては、この気持ちに沿って国に意見書を出すということは当然であると思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"辻副委員長","kind":"意見","question":"そういうのを使わなくたって、本来、根が持っている特性というものをどう伸ばすかという遺伝子組換えもあってしかるべきじゃないか。だから、理事者がどうのこうのじゃなくて、我々委員会としては、１番目については意見が分かれているなとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-055"},{"speaker":"宮崎委員","kind":"意見","question":"２項目目は一致しているようだから、そういうふうな態度でいいのかどうかというのは、ちょっとよくわからないところがあります。１番と２番の両方がセットで請願が出されていると考えますので、できたら２項目一緒で採択をしていただければなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-056"},{"speaker":"辻副委員長","kind":"質問・要望","question":"ですから、ここで問題なのは、遺伝子組換えを承認しないでくれと、そういう言い方じゃだめなんだというのが、私の意見なんです。その安全性とかということについてきちっとやる、このことを国に求めている。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"横山委員長","kind":"提案","question":"都議会生活者ネットワークが議員提案として、国に意見書を提出と、こういう経緯なものです。どういう要望で出されたのかという経緯を調べましたら、自発的に出されたということで、そういった文面は一切入っておりませんとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"宮崎委員","kind":"質問","question":"ですから、心配している。国民の主食ですから、食糧政策の根冠にかかわるわけですから、そういうことではないことでやっていかなきゃいけない。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-059"},{"speaker":"宮崎委員","kind":"意見","question":"１点目は承認しない、２点目としては表示ということになっておりますので、請願者の気持ちが２点セットだと考えます。ということで、先ほどの意見になりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"須藤委員","kind":"意見","question":"請願第２８号で来ているので、宮崎委員も１本で取っていくべきだという話なので、それなら１本で考えていいと思います。請願第２８号として考えて、委員会としての結論を出していいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"},{"speaker":"須藤委員","kind":"質問","question":"ですからこれは継続にしておいて、２項目目の国の基準をしっかりしなさいというのは、皆さん方も納得できると思うんです。分割すること自体にね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-062"},{"speaker":"藤原委員","kind":"意見","question":"この二つを請願項目としていますので、この委員会でこっちはいい、こっちはだめだという形で出すのも変だと思います。合同も継続という形でやってほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"}]},{"id":"topic-03","title":"平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願","agenda":"平成１３年請願第１２号、新たな大気汚染公害被害者の救済を求める意見書に関する請願","exchanges":[{"speaker":"須藤委員","kind":"意見","question":"裁判の結果が出るまでは、いろいろな考え方があろうかということで、その結果を待つという形でした。裁判の結果が出たので、きょう、結論を出してほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"宮崎委員","kind":"確認","question":"ちょっと伺いたいんですけれども、３番のメーカーの責任のところなんですけれども、ニュアンスがどうだったかというのを確認しておきたいんです。やっぱりいろいろ対応に問題があったんじゃないかと、そういうふうな文章になっていたかと思うんですけれども、そこら辺はどうだったか尋ねました。","respondent":"田中健康課長","answer":"車のユーザーが排ガスを出す主体であり、その移動はメーカーはコントロールできない、これが一つの考え方です。判決で、２割程度にとどまっているので、ディーゼルエンジンの製造を自粛するほどの義務はないという判断を裁判所がされたという内容です。","id":"exchange-065"},{"speaker":"宮崎委員","kind":"質問","question":"特に公害健康被害補償法が変わって、１９８８年以降、救済が打ち切られてきて、新たな認定がされないということなんですね。患者が新たにどんどん増えているわけですから、品川区議会としても、ぜひ願意に沿って意見書を出すということでいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"辻副委員長","kind":"質問・要望","question":"新たな法律を国に求めるということになるわけですが、どこに財源を求め、もう少し踏み込んだ形でやらなきゃいけないなと思います。ですから、この７人については、もう先延ばすわけにはいかないということで認めた。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"金高委員","kind":"意見","question":"裁判を継続し、結論を先送りすべきではないということで、一定の基準が出ております。当委員会で継続されているこの請願については、ここで結論ということであれば、私は、不採択でいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-068"},{"speaker":"辻副委員長","kind":"質問","question":"ですから、住民、この辺なんかも。だから、単なる汚染者負担の原則にのっとった救済制度というのは、ちょっと危ないということを明確にしておかなきゃいけないなという意見です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-069"}]},{"id":"topic-04","title":"平成１４年請願第６号、措置制度から契約制度（支援費制度）に変わることに伴っての請願","agenda":"平成１４年請願第６号、措置制度から契約制度（支援費制度）に変わることに伴っての請願","exchanges":[{"speaker":"宮崎委員","kind":"質問・要望","question":"どう聞けばいいのかというのがよくわからないところなんですけれども、わかっている範囲で、その内容を教えてください。要するに、この請願は区に対して要望している内容なんですけれども、東京都がこの要望についてはこういうふうに考えているみたいな。","respondent":"日下部障害者福祉課長","answer":"ですから、その差１５％について、東京都として具体的な緩和の措置を講じていく。そのようなことで、もう少し具体的なものについては、時間がかかるだろうと考えています。","id":"exchange-070"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっとよくわからないので教えていただきたいんですが、例えば、今までヘルパーさんに２回来てもらったのが１回になっちゃう。全体の利用できる量が少なくなってくるという仕組みになりはしないのかというのがちょっと心配なんですけれども、そこのところはどうなんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"所得税３万円以下の方については、月額２,２００円とか、ご負担をいただく。ですから、サービスの利用を幅広く進めていくために、こういう措置がとられているです。","id":"exchange-071"},{"speaker":"宮崎委員","kind":"質問","question":"実際に、この内容がかなりはっきりしてくるのが、今の説明ですと、大体３月ぐらいになると。支援費の基準は３月が最終決定だということなんですけれども、やっぱり３月ぐらいにならないと、かなりはっきりとなってこないんか尋ねました。","respondent":"日下部障害者福祉課長","answer":"確かに最終的に正式決定するのは３月ですけれども、一応、３月中にはすべて手続を完了させなくちゃいけません。できるだけ早く出るに越したことはないと思っています。","id":"exchange-072"},{"speaker":"宮崎委員","kind":"意見","question":"国のほうにも急いでいただくというのが大前提になってこようかと思うので、その中で区の対応というのがはっきり見えてくるのかなと思います。先ほど、まだはっきりしていない中では、そういうことも前提みたいにしないで検討していったほうがいいんじゃないのかなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"金高委員","kind":"質問・要望","question":"別に制定しなくても、これからまだ来年の３月まであるわけでありますし、私のほうとしては趣旨という形で採択をさせていただければと考えています。都の基準が決まり、またそれに基づいで区が実際に肉付けをするわけですから、そのような形で趣旨ということを表明させてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"須藤委員","kind":"意見","question":"現行より１２％、１６％アップするということを言っているんだけれども、ちょっときついなという思いをしております。ただ、取り扱いについては、本日、決を取っていただいて結構ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-075"},{"speaker":"宮崎委員","kind":"質問・要望","question":"採決は、できればきょうやってほしいと求めました。最後は区のほうでも大丈夫だという姿勢を見せておくというのが大事だと思いますので、私は、採択と思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-076"},{"speaker":"辻副委員長","kind":"意見","question":"先ほど、須藤委員のほうから話が出たんですが、内容をやっちゃうと、話が国基準を上回るようにとか、減免措置をやってくれとかとなっちゃうんで、どういう形で請願を扱うかとの意見を述べました。","respondent":"横山委員長","answer":"先ほどの請願じゃありませんけれども、平成１４年請願第６号をすべて一括でとなると、ほんとうにすごく無理があるんです。この内容を、どのように我々が解釈して取り上げてあげようかというのが、一番難しいところなんですね。","id":"exchange-077"},{"speaker":"宮崎委員","kind":"質問","question":"私は、採択と言ったんですけれども、皆さんの考えが出てくれば、また諮りようも出てくるのかなと思うんですけれども、いかがか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-078"},{"speaker":"須藤委員","kind":"意見","question":"前回、これが審議にかかったときに、始まったばかりなので、どういう方向性かなという話がありました。それから、六は、これを全部やるようにまた条例をつくりなさいということなので、なかなかきついなというのが、私どもの見解ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-079"},{"speaker":"山路委員","kind":"提案","question":"一般質問で提案しました疑問に思っていること、あるいは課題を、その当時からずっと着実に推進している内容はお聞きしているんです。趣旨採択か、いろいろ迷っているところではあるんですけれども、全体としてはどのように取り扱うのかとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-080"},{"speaker":"宮崎委員","kind":"意見","question":"先ほど、金高委員は趣旨でという態度を出されました。私は採択と言ったんですけれども、趣旨採択なら、私はそれでいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-081"},{"speaker":"須藤委員","kind":"質問","question":"これをちゃんと趣旨で採択したじゃないですかというふうに、後で我々が区民の方々に言われたときに、果たしてどうやって責任を取っていけるのか。しておいていただいて、理事者の方々に退席してもらうというようなこともちょっと思いますので、それも委員長にお諮り願います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-082"},{"speaker":"金高委員","kind":"質問","question":"区のほうでもそれを加味しながら行っていくことですから、先ほど、発言したわけです。やはり考え直すこともありますけれども、それをちょっと置いておけば、全体的に趣旨ということで理解できるという思いです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-083"},{"speaker":"築舘委員","kind":"意見","question":"区のほうは独自で善処しているということでもありますけれども、六に関しても、条例を制定してくださいとされてしまうと、どうかなという部分もある。具体的になってくると、非常に規制されている部分があるので、そこがちょっと問題だなと思いますけれどもねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-084"},{"speaker":"辻副委員長","kind":"意見","question":"やるというんだったら、一つ一つどうだああだというのをとっていくということになっちゃうと、（二）の十分配慮してくださいはいいでしょう。その辺が、ちょっと悩ましいところですねとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-085"},{"speaker":"横山委員長","kind":"確認","question":"去る１１月８日の議会運営委員会におきまして、「議会・委員会運営に関する申し合わせ確認事項」の一部改正が行われました。運営方法は、従来と変わりませんが、その他で取り扱うことが、１１月２２日の委員長会で確認されております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-086"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/534819?Template=document&Id=3036#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":59131,"voices":197}},{"id":"h14-20021125-8","meetingId":"h14-cm11","date":"2002年11月25日","dateIso":"2002-11-25","committee":"建設委員会","time":"午前１０時０５分～午後３時２８分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"では、２の議案審査","agenda":"では、２の議案審査","exchanges":[{"speaker":"飯沼委員","kind":"質問・要望","question":"多目的広場のところで、区内チームと区外チームおよび学校が利用料金の２倍としている根拠というか、なぜ２倍なのかということと、私の印象だと、学校だともうちょっと安くてもいいのではないかなと思うんですが、区内のほかの施設の学校の扱いがわからないので、教えてほしいと求めました。","respondent":"岩田管理工事課長","answer":"すべての有料施設につきましては区外チームは区内チームの倍という料金設定になってありますので、それと同じ考え方です。６カ月前から優先的に予約ができるという特典があるわけですので、区外チーム料金が妥当であろうということで設定をさせていただいたものです。","id":"exchange-001"},{"speaker":"飯沼委員","kind":"質問","question":"２時間という単位が細かいんですが、この辺、利用者にとって不便がないのかどうか。多目的広場を借りた方に対して、そこと同等に扱うというのはどうかなと思うんですけれども、その辺はいかがか尋ねました。","respondent":"岩田管理工事課長","answer":"それに合わせて設置する場合と、多目的広場の時間割とはラップはしておりませんけれども、２時間コマで自由に使っていただくというふうな考え方です。","id":"exchange-002"},{"speaker":"飯沼委員","kind":"意見","question":"１００円で、「お金取るの」というような反響がちょっとありましたもので、意見として申し上げしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-003"},{"speaker":"船波委員","kind":"質問","question":"午後４時から午後７時の間、学校の優先枠にしてしまうのはどうかと思いますけれども、その辺どう検討をされたのかということをお伺いしたい。利用の仕方ですけれども、多目的広場のスポーツをすることだけではなくて、そういった使い方でも貸し出すということはあるんか尋ねました。","respondent":"岩田管理工事課長","answer":"幼稚園や保育園、福祉施設などの利用が見込まれるようであれば、現在の時点では優先予約ができるのは学校に限定をしたいというふうに考えております。","id":"exchange-004"},{"speaker":"船波委員","kind":"質問","question":"利用の内容ですけれども、スポーツだけでなくて、ほかのも考えていくということですが、これは申し込むときに、そのグループがどういったことをやるのかということも聞いた上で、時には、それはだめですとお断りするようなこともあるんか尋ねました。","respondent":"岩田管理工事課長","answer":"地域のコミュニティ活動にも十分使っていただく施設にしたいというのが区長の考えですので、必ずしもスポーツだけに限定するつもりはございません。若干の制限、あるいは野球はお貸ししないということで今考えておりますけれども、今のところはそういう考えです。","id":"exchange-005"},{"speaker":"船波委員","kind":"質問・要望","question":"は優先枠のことですけれども、そうであるならば、幼稚園とか保育園の利用を優先させてあげれば利用アップにつながるのではないかなと思います。それが使えるのかどうかということを確定しておくということが、学校に優先させてあげるということであれば、検討をしてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-006"},{"speaker":"田中委員","kind":"質問・要望","question":"午後０時３０分から午後４時と、午後４時から午後７時という、その辺の考え方をお聞かせいただきたい。庭球場の１に、そういう名称になっているのかと思いますが、その辺も含めてお聞きしたいと思います。","respondent":"岩田管理工事課長","answer":"施設の性格上、運動会などが開かれれば当然丸１日お借りしていかなければということで、そういうふうな運用をしてまいりたいと考えています。２が（仮称）品川中央公園、１がその他の庭球場、こんな煩わしい表現になってしまいました。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"午前８時３０分から午後０時３０分とか、午後４時から午後７時、学校の使用を前提にこの枠組みがされているように思えてならないんです。大口利用者の要望に沿った、午後０時３０分からという区切りが、どのような経緯からこういう時間帯になったのかをお聞きしたいと思います。","respondent":"岩田管理工事課長","answer":"例えば午後０時から午後６時までが午後の時間で、６時間という枠になってしまいますので、連続させただけです。午後５時ぐらいで終わるだろうというふうに考えておりますので、住民説明会の中でも、他意は全くございません。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問・要望","question":"近隣の公立の学校の中では大間窪小学校が一番近いんでしょうか、立派な校庭もありますし、その向かいの荏原第三中学校もあります。既存のものを含めると１２７億円ぐらい、どのようなお考えを持つか、お聞かせほしいと求めました。","respondent":"岩田管理工事課長","answer":"仮のことを考えた場合、そのような施設を使うよりは、引き続きそういうところを使おうという形になってしまうことも想定はされます。","id":"exchange-009"},{"speaker":"田中委員","kind":"意見","question":"例えば最低限、休み時間を、逆に一般に完全に開放するというようにできないものかどうかということをお尋ねいたしますとの意見を述べました。","respondent":"岩田管理工事課長","answer":"御飯などは５分ぐらいで食べてしまって、そういう子どもたちに、一般区民の方と同じように使ってもらうということぐらいは言えると思います。しかも、ダブるのは昼休みの時間帯だと思いますので、委員のご趣旨に沿って調整してまいりたいと思います。","id":"exchange-010"},{"speaker":"田中委員","kind":"質問","question":"同一人または同一団体の２日以上の連続使用は認めないと書いてあると思いますが、もし２日以上の連続使用を希望した場合は、どうされるんか尋ねました。","respondent":"岩田管理工事課長","answer":"今規則で検討をしておりますのは、今までの規則ですと、連続して２日以上借りることはできません。その６カ月前の申し込みのときに、抽選という形をとる予定ですので、代替の施設を見つけなければいけません。","id":"exchange-011"},{"speaker":"田中委員","kind":"質問・要望","question":"（仮称）品川中央公園というのは、お客さんが想定されたから、つくろうという決断をされたものなんでしょうか。今のお話を伺うと、そもそも論になってしまいますが、最初からそういう想定でこの公園というものをつくった施設なんか尋ねました。","respondent":"岩田管理工事課長","answer":"結果的にそれで収入が上がれば、血税をそこに投入しなくて済むというだけの話ですので、ちょっと私も当初の説明が不十分だったかもしれません。","id":"exchange-012"},{"speaker":"田中委員","kind":"質問・要望","question":"議会の３分の２以上の同意が必要というぐらいの、今回は結果としては広く求めますので、これぐらいの重い意味合いを持つ内容だと僕は思います。３分の２の議決を求めているぐらいの重い議案だと思いますので、それを見た上で判断をしたいと思いますので、その辺の運用をお願いいたします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-013"},{"speaker":"田中委員","kind":"質問・要望","question":"ここで出た、それぞれの委員の方々も含めて、ぜひ要望を受け止めて施行規則の改正に当たってほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-014"},{"speaker":"堺委員","kind":"質問・要望","question":"区民への周知についてはどうするんですかということをお尋ねします。特にお昼休みという時間が限定されるわけですから、１つでもできる、ちょっと教えていただけますか。","respondent":"岩田管理工事課長","answer":"スケジュール的には、広報しながわ１月１１日号でお知らせすると同時に区のホームページの中でもご紹介をさせていただこうと考えています。","id":"exchange-015"},{"speaker":"堺委員","kind":"質問・要望","question":"あるいはどういう方法になっているのか、金銭を扱うわけですから、問題が起きないようにしなければいけない。その辺のところについての考え方を教えてほしいと求めました。","respondent":"岩田管理工事課長","answer":"今のところは多目的広場のみに限定して生涯学習課のほうで受付手続等をやらざるを得ないのかなということで、今検討を進めているところです。そこら辺をどうするのかというのが今ネックで、検討、精査をしています。","id":"exchange-016"},{"speaker":"堺委員","kind":"質問・要望","question":"あるいは区民の財産ですから、説明を聞かないと、なかなかわからない。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問・要望","question":"多目的広場だと時間で考えると２,６００円ぐらいでしょうか。もう１点は、敷地としてなくなっているわけですから、そういうときに支障が出てこないのかどうかというのをお聞かせ願えますか。","respondent":"岩田管理工事課長","answer":"天王洲の野球場を設置したときに初めてミーティングルーム、あそこしかないわけですけれども、おそらく午前中の反省会というのはまずないだろう。","id":"exchange-018"},{"speaker":"菊地委員","kind":"質問","question":"都市再生のことを説明されても、今の話の中身だけだと理解がしがたいところがあるんですけれども、今度の改正のところで気づいたところで、ちょっとお聞きしたいのは、都市再生で、大崎駅周辺の指定をされましたけれども、区内の網かけをされた敷地の規模は分かりますか。","respondent":"南雲都市開発課長","answer":"今回の都市再生の緊急整備地域に指定されておりますのは、大崎駅東口、西口を合わせまして約６０haが全体で網かけがされてあります。","id":"exchange-019"},{"speaker":"菊地委員","kind":"質問","question":"東京都２３区で考えると、６０ha以上に大きく網かけをされている区というのはあるのかどうか、そのことをお聞きしたい。４１番の、前の総合設計が認可がおりるときと、どういう違いがあるのかということを教えていただけますか。","respondent":"南雲都市開発課長、山室住宅指導担当部長","answer":"千代田区も含めて、東京都の中心部分が広い範囲でかかってあります。新宿周辺がかかっているということで、具体的な面積は今はっきりしないんですけれども、大崎の１０倍以上の面積で広い範囲でかかっているです。第８６条の認定と、それぞれやるわけですが、それを１本でできるように仕組みを整備をした。","id":"exchange-020"},{"speaker":"菊地委員","kind":"質問・要望","question":"例えば大井の住友不動産のところは、補助１６３号線の前からの拡幅と合わせてやりましたよね。これは当然総合設計ですから、その辺が薄れてしまうような、その辺をお聞かせほしいと求めました。","respondent":"山室住宅指導担当部長","answer":"例えばその間に権利者調整をやっても、それが１年経ってしまうと、その間にまたいろいろな事情が出てくる。それをやった場合の手数料がこういうふうになりますということで、今日は資料についてのご説明を申し上げているわけです。","id":"exchange-021"},{"speaker":"菊地委員","kind":"意見","question":"どうも理解ができないもので、どうしてもそっちに入ってしまうんですけれども、明日の法改正のところの説明で、またいろいろ聞かせていただきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-022"},{"speaker":"船波委員","kind":"質問","question":"所得が高額になっても出ていっていただかなくてもいいというふうにしたのは、どうしてか尋ねました。","respondent":"浜脇住環境整備課長","answer":"これまで平成７年ぐらいまでは、密集事業を進める上での一つの安全といいますか、第一種の方々を入れるという規定でございました。高額所得者という言葉をなくして、収入基準以上の方は付加ということで、ちゃんとそれに見合った家賃を払っていただくというふうになってあります。","id":"exchange-023"},{"speaker":"田中委員","kind":"意見","question":"新しい第５条で、３年を超えない範囲で必要な期間に限りということですが、３年を超えてしまったという例はあるのか。継承を認めることによって、逆に、３年を超えるケースが増えた場合の対応というのはどうなのかとの意見を述べました。","respondent":"浜脇住環境整備課長","answer":"第５条が仮入居者なんです。仮入居者の３年以上というのは、今後も３年以上かかる建て替えというのはないと考えていますので、この辺は心配ないなというふうに思っております。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3740#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":38403,"voices":81}},{"id":"h14-20021125-9","meetingId":"h14-cm11","date":"2002年11月25日","dateIso":"2002-11-25","committee":"文教委員会","time":"午前１０時０５分～午後２時３０分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を78件整理しています。","topics":[{"id":"topic-01","title":"平成１４年請願第２６－２号、一人一人の子どもたちが大切にされる品川区を求める請願","agenda":"平成１４年請願第２６－２号、一人一人の子どもたちが大切にされる品川区を求める請願","exchanges":[{"speaker":"高星委員","kind":"質問","question":"第２６号ということで受理されているわけですけれども、項目としては８ということですけれども、この請願全体に通じる部分ってあるわけですね。その意味で、審査に当たっては、この請願の前ページにかかわる部分でもいいんでしょうか、どうなのか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-001"},{"speaker":"高星委員","kind":"質問・要望","question":"１年生とかほんとうに小さい子は、学校の先生が学童保育クラブまで送っていく、そういうことも現実の問題としてあるわけじゃないですか。２年生、３年生の部分で、その辺で話し合ったことがあるのかどうなのか。","respondent":"青木指導課長","answer":"学童保育クラブと学校との関係というのは、それぞれの学校で学童保育クラブと連絡を取り合っております。行われておりますので、今後も、そうした関係の中で学童保育クラブと学校との関係は維持していきたいと考えております。","id":"exchange-002"},{"speaker":"原委員","kind":"質問・要望","question":"そこで、今、ご説明がありましたけれども、ちょっと確認をさせていただきたいと思うんです。２０人、１０人ですというような、ちょっと教えていただきたい。","respondent":"谷田部学務課長","answer":"２１人クラスが１学級、２１人から２５人が８学級、２６人から３０人が２５学級、３１人から３５人が７６学級、３６人から４０人が３９学級をです。３０人以下学級が全部で３４学級、これは２２.８％、３１人以上学級が１１５学級で７７.２％という状況です。","id":"exchange-003"},{"speaker":"原委員","kind":"意見","question":"どうしても学級の中の人数が増えることは仕方がない気がするんですけれども、小学校なんかの場合は、７割以上が３０人以下。今は４０人体制だけれども、現状の中でどう推測されているのか、お話を聞かせていただけますかとの意見を述べました。","respondent":"谷田部学務課長","answer":"これからの児童・生徒数、それに伴います学級編制の状況を推測していくのは非常に難しい部分があろうかと思います。そういう中で、この辺の傾向はしばらくは続くとは思いますけれども、そう大きな変動は見込んではいないと、私のほうでは思ってあります。","id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"それともう一つは、３０人学級と４０人学級の、学校の対応の仕方なんですけれども、教職員も含めて、ちょっともう１回、現状を教えていただけますか。","respondent":"青木指導課長","answer":"品川区独自の指導助手といった、補助的な教員の免許を持った人も導入するような形の対応をしております。したがいまして、単なる学級の数だけではなく、学習の集団として編制した集団に教員がついて指導しているという現状です。","id":"exchange-005"},{"speaker":"原委員","kind":"質問","question":"そうすると、例えば４０人学級だと、教員の加配をたくさんしなければいけないとか、あるいは３０人学級だと、加配が変わらないから、人数が少なくても先生の数は変わらないでいいんだとか、そういういろいろな論議になると思うんですけれども、その辺のところの現状はどうか尋ねました。","respondent":"青木指導課長","answer":"中学校については、９校についてあります。今後も、生活集団と学習集団の分け方を十分に検討して、適切な指導ができるように行っていきたいと考えております。","id":"exchange-006"},{"speaker":"原委員","kind":"質問","question":"今の伺った内容からしますと、結局、３０人でも、４０人でも、現状の中で、教員のほうの対応は十分にされていると。ですから、今、思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問・要望","question":"もし、現状でつかめている状況がありましたら、教えていただきたい。今のところ、どういう見通しになっているのか、ちょっとお尋ねしたいんです。","respondent":"谷田部学務課長","answer":"国と都道府県がそれぞれ２分の１ずつ負担して、その分の給与を全額負担すると、そのような状況になっていきます。都道府県の学級編制の基準を委任するという検討がされているという情報が飛びましたので、たしか、現在。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"２００４年に市区町村にも権限を広げていこう、区教育委員会としては、どうとらえているんでしょうか。困難はあるんですけれども、なぜそういう流れになったのかということを、ちょっとお尋ねしたいんです。","respondent":"若月教育長","answer":"例えば品川区の場合、３０人学級がほんとうはいいんだけれども、できないから指導助手をつけているという発想ではありません。３０人学級といったことを進めている地方自治体も、今、うちがやっているような習熟度別だとか何とかという方法で工夫をしているんです。","id":"exchange-009"},{"speaker":"沢田委員","kind":"質問","question":"私は教育の専門家でもないですから、２５人とか、一般的に当然じゃないのかなと。ちょっと、そこをもう一度、説明してほしいんです、その２点。","respondent":"若月教育長","answer":"できない子ども、それを細かく教えてあげるために必要ならば、３０人ということも考えられるんじゃないですかという程度だと思うんです。文部科学省はどう考えるかわかりませんが、私はそんなふうに理解しているです。","id":"exchange-010"},{"speaker":"沢田委員","kind":"質問","question":"ちょっとお尋ねしたいんですが、１１５学級ありますけれども、３０人以下の学級になっているクラスはどうなのか。５人がいいのかと、とりあえずせめて３０人ぐらいにやるということは、いかがか尋ねました。","respondent":"若月教育長","answer":"学力が身についていないとか、なかなかつきにくいというのは、一概に人数で限定することはなかなか難しい。必ずしもすべて人数だけで、今の学力の問題を一刀両断に意味づけるというのは、若干無理があるんじゃないだろうかと、こんなふうに思います。","id":"exchange-011"},{"speaker":"沢田委員","kind":"意見","question":"もう一度言いましょう。１１５学級が３０人以上の学級になっていて、実質３０人以下学級がどのぐらい達成されているのかということを、先ほど聞いたんですとの意見を述べました。","respondent":"青木指導課長","answer":"ですから、単に機械的に、３０人以下で何学級というような形ではお答えできません。子どもの実態によって、その３８人を使っているというような感じです。","id":"exchange-012"},{"speaker":"沢田委員","kind":"質問・要望","question":"３０人学級のレベルに達しているかというと、１１９対３８ですから、３０人学級は必要だとならざるを得ないと思います。それならば、加配なんかして、小さな教える単位にして効果を上げているということは出てこないじゃか尋ねました。","respondent":"若月教育長","answer":"品川区は、３０人学級がほんとうはいいと思っていてやりたいんだと、子どもたちの実態に合った指導をしてあげたいからつけている。その結果、いろいろな効果が出てきていると、こういうふうにご理解をいただきたい。","id":"exchange-013"},{"speaker":"沢田委員","kind":"意見","question":"別に３０人学級と加配をやるというのは同じレベルだと言うんじゃくて、先生が見る子どもの数が少ないほうがいいという点で、一つの同じベースができているんじゃないかということを言っているんですとの意見を述べました。","respondent":"若月教育長","answer":"その中で出てきた子どもたちのいろいろな学習面での違い、それに細かく合った指導をしていくというのが、子どもの実態と考えております。ある程度の集団の中で、これはまた学力とは別の意味での教育的な意味があると、こういうふうにご理解をいただければと思います。","id":"exchange-014"},{"speaker":"中島委員","kind":"質問","question":"今の小学校で３０人以下学級が２９３学級あるということで、これはやはり、かなり何年間か継続して、少ないところは少ない、多いところは多いという傾向があるんか尋ねました。","respondent":"谷田部学務課長","answer":"何年かでの傾向調べになりますが、例えば、小学校の場合、大井第一小学校のように、今年の５月１日現在で見ますと６９２人、一番少ないところでは、第二日野小学校の６７人というように、学校によって児童数の格差はあります。","id":"exchange-015"},{"speaker":"中島委員","kind":"意見","question":"私も、自分の知っている範囲の学校では、何年間も同じくこの学校はいつも生徒が少ないとか、この学校は多いというのを見てきているわけなんです。４０人学級に近いところと少ない学級での学習面、大きな差ができてきているかどうか、その辺をちょっとの意見を述べました。","respondent":"青木指導課長","answer":"お答えしたこともあるんですけれども、学級の人数で学級の状況というのは、簡単に言えるものではないと考えております。そういうことで、人数と学級の様子が相関関係があると言いきれるものではないと、考えております。","id":"exchange-016"},{"speaker":"中島委員","kind":"質問","question":"ですから、私は、今、品川区で取り入れている習熟度別というのは、非常に賛成だと思っているんです。「一人一人の子どもが大切にされる」とあるわけですから、そういった教育というものを研究していくべきじゃないかなと思っているわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"石田委員","kind":"質問","question":"１点だけお聞きします。もし、教育委員会としては、どのような形でそういう人を指導しようとか考えていらっしゃるのかというところをお聞きしたい。","respondent":"青木指導課長","answer":"一つ一つの授業の内容を踏まえた上での指導であるということで、非常に具体的であり、年間の中で位置づけた研修になっていると考えております。研修会も開いておりますし、プラン２１のそうした計画の中に、そうした研修も位置づけて進めているという現状です。","id":"exchange-018"},{"speaker":"石田委員","kind":"質問・要望","question":"あなたは４０人でも見れる体制ですよということを信じて、その方の指導力を信じてあげているわけですから、そのほうがいいと思います。それは要望でいいです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"上山副委員長","kind":"質問・要望","question":"加配教員などいろいろご説明がありましたけれども、もう一度確認させていただきたいんですけれども、加配教員をなぜつけようと思ったんでしょうか。もう一度、最初の考え方、出発点というんですか、もうちょっと教えていただきたいんです。","respondent":"青木指導課長","answer":"２学級あるところを３分解して、そこに１人教員をつけるとか、学級数を一つ増やす形で指導助手をつけるという考え方ではありません。そういうような指導の工夫の中で、ティームティーチングや指導助手をつけているという認識ですので、よろしくご理解をお願いします。","id":"exchange-020"},{"speaker":"上山副委員長","kind":"質問・要望","question":"２人は四つの目という言い方が正確かどうかわかりませんが、教育長の答弁では、説明なさったように思うんです。もし、何かお考えがあれば聞かせていただきたいんです。","respondent":"青木指導課長","answer":"学級会の内容だとかを考えますと、やはりあまり規模が小さい中では、学習を展開するのは難しいということも言われております。現在、私たちが踏み出した一歩というのは、そういう学習の状況に応じた子どもたちへの適切な指導ということで考えているところです。","id":"exchange-021"},{"speaker":"沢田委員","kind":"提案","question":"ちょっと質問なんですが、３０人学級にしてほしいというのは、指導能力というのは非常に大きなファクターだと思います。私どもが提案したときには、今、国全体で問われているんじゃないかなと思いますとの意見を述べました。","respondent":"谷田部学務課長","answer":"３１人以上の学級をすべて３０人学級にならしたら、学級数が幾ら増えて、教員が何人必要かというご趣旨の質問だと思います。その趣旨のご質問がございまして、私のほうで、あくまでも試算ということでお話し申し上げました。","id":"exchange-022"},{"speaker":"沢田委員","kind":"質問","question":"非常勤でやった計算はありますか。できないんか尋ねました。","respondent":"谷田部学務課長","answer":"区が学級編制で３０人学級をとるとなると、あくまでも正規の教員でやるのが原則だと思います。単純に増えた人間掛ける教員一人当たりに支払うべき給与の平均を掛ければ、年間１５億４,０００万円ぐらいが、区単独の負担になってくるです。","id":"exchange-023"},{"speaker":"沢田委員","kind":"質問","question":"クラスを担当していない正規の先生を回したり、いわゆるやりくりして、足りない部分を非常勤でやるということは可能じゃないんですか。私はちょっと現場のことはよくわからないので、聞いているんですけれども。","respondent":"青木指導課長","answer":"定数の教員が指導をして、なおかつ、時間数が足りない部分については、講師という制度を使っております。ですから、それかなと思うんですけれども、先ほどのシミュレーションは、その講師の数を除いた上でのシミュレーションだということです。","id":"exchange-024"},{"speaker":"原委員","kind":"質問・要望","question":"この請願なんですけれども、今、いろいろご意見が出てきて、取り扱いについてお諮りいただきたいと思っています。私としては、今日、結論を出すようにしていただければと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"},{"speaker":"高星委員","kind":"質問","question":"私どもの党の関係で言えば、国段階では、３０人学級の実現に向けてというようなことをうたってはいるんです。１クラス何人という数の問題じゃないということがよくわかっておりますので、本日、採決をしていただいても結構だと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"沢田委員","kind":"質問・要望","question":"今、原委員から出たのは、今日、結論を出すべきだと、それから高星委員から出たのも、取り扱いについてだったので、委員長はそういう宣言をしていませんけれども、質疑は一たん打ち切られて、取り扱いの問題で意見が出たから、私も取り扱いの問題で発言させていただきたいと思って、挙手しました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"沢田委員","kind":"質問・要望","question":"私は、できればそういうものをもう少し調べていただいて、その上でこれがどうなのかという結論を出したほうがいいんじゃないかなと思うんです。動いているわけですけれども、今回のこの請願のこの部分については、今日のところは継続審査としていただきたいということだけ表明しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-028"},{"speaker":"佐藤委員","kind":"意見","question":"私も、皆さんの質疑の様子をじっと聞かせていただきましたが、私からは、本日、結論を出すということをお願いしたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-029"},{"speaker":"中島委員","kind":"意見","question":"一時期２５人学級とか、また私自身の考え方にも非常に合った習熟度別という教育のあり方というのは、非常にいいものだと思っています。人数のことはまたそれぞれ検討していくべきことであるけれども、本日、決定をしていくほうがいいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-030"},{"speaker":"原委員","kind":"質問","question":"私も、当初、いろいろな質問させていただき、そしてまた、そのお答えを聞いて、それからまた皆さんのご意見を拝聴させていただきましたけれども、今回は、願意に沿いがたいと考えていますので、不採択ということにしたいと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"石田委員","kind":"質問","question":"いいですか、同じ会派で。請願項目８番については、願意に沿いがたいと考えていますので、それは会派の中では一緒の考えです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-032"},{"speaker":"中島委員","kind":"意見","question":"先ほどの意見と重なってしまう部分があるですが、ここで、「子どもたち一人ひとり発達、成長を保障していただきたく」とあります。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-033"},{"speaker":"沢田委員","kind":"質問","question":"それから、小中一貫校の問題はここに書いてありますけれども、小中一貫校は、どうみても１００億円前後かかると、私どもは思っております。やっぱり３０人学級、それをもっと早めてやるべきだという立場で、今請願は採択をすべきだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-034"},{"speaker":"佐藤委員","kind":"意見","question":"現状のクラスの定員の編制といったものが、教育に大きな支障を及ぼしているという認識は、私どもはいたしておりません。したがいまして、この請願には賛成しかねるですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-035"},{"speaker":"高星委員","kind":"質問・要望","question":"私は、先ほど言いましたように、結論というのは、今日決めるのは拙速であって、今日決めるべきではないと思います。だから、不採択することに反対です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"}]},{"id":"topic-02","title":"平成１４年請願第２７号、「遺伝子組み換えイネ」を学校給食に使用しないことを求める請願","agenda":"平成１４年請願第２７号、「遺伝子組み換えイネ」を学校給食に使用しないことを求める請願","exchanges":[{"speaker":"原委員","kind":"質問","question":"お米の話をしてもわかるかどうかわからないですけれども、その辺のところは、遺伝子組換え食品ではないんですかね。チャーハンもあるのかもしれませんけれども、そうすると、学校ではどのぐらい使っていらっしゃるのかな。","respondent":"谷田部学務課長","answer":"どのぐらい米を使っているのかということなんですが、各学校まちまちでして、週当たり平均して２.２回ほど米飯給食を提供しています。ご飯を主体とした献立を作成していますので、大体、週当たりそのぐらいになるです。","id":"exchange-037"},{"speaker":"原委員","kind":"質問","question":"ここで出てくる殺虫性コーンがどうのこうのとか、該当するような形になるのかということについては、ちゃんとしたデータが出ているんでしょうか。何かお答えがあれば。","respondent":"谷田部学務課長","answer":"どちらかというと、遺伝子組換え関係の中身につきましては、厚生委員会のほうでのお話になろうかと思います。安全面を考えて、そういったものを使わないようにという立場で指導に努めていくということしか、今の段階では言えないです。","id":"exchange-038"},{"speaker":"原委員","kind":"意見","question":"危険性がどうだとか、安全性がどうだとか言えなくなっちゃいますよね、基本的に。こういう意見だけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-039"},{"speaker":"佐藤委員","kind":"意見","question":"北野議員のグループは、こういう食品に対して大変先進的なお考えをお持ちで、こういうふうな請願が出されてきたわけです。そこの答弁だけもう一度、永久に使用しないのか、当面、使用しないのか、そこだけちょっと説明を求めました。","respondent":"谷田部学務課長","answer":"ですから、そういうふうに疑っていけば、すべての食品を疑っちゃいまして、何も口にすることはできない、そういう難しい問題もあります。これはまさしく、今現在、厚生委員会で同じ団体から出ています請願の趣旨に沿うような流れで考えていかざるを得ないだろうと思ってあります。","id":"exchange-040"},{"speaker":"中島委員","kind":"質問・要望","question":"区内の学校給食で遺伝子組換えの米を使用しないように求めます」ということで、これは当然、私も使用すべきではないと思います。給食に当たっては、そういう結論が出ていないものを、今使用するのは、これはいけないんじゃないかなと思いますが、どうか尋ねました。","respondent":"谷田部学務課長","answer":"当然、それは使いませんということで、これから指導強化をしていかざるを得ないと思ってあります。遺伝子組換え食品という表示がありますので、それはそれでそういうものは使わないということは、今後も変わっていかないです。","id":"exchange-041"},{"speaker":"石田委員","kind":"確認","question":"再度確認をしたいんですけれども、今、それはなるべく使わないようにしましょうとしているのか。将来的にも、それをずっと継続していくのか、その確認だけをしたいと思います。","respondent":"谷田部学務課長","answer":"まだいろいろな考えを持っている親御さんもいらっしゃいますし、そういう中で、どんどん使いなさいという立場ではない。今の段階では、いろいろな意見があるんで、なるべく遺伝子組換えじゃない食品を使うようにというのが、現状だと思ってあります。","id":"exchange-042"},{"speaker":"沢田委員","kind":"質問","question":"科学技術の発展は遺伝子レベルまで来ていることも事実ですから、これはまだ早いんじゃないかと、非常に迷うんです。ちょっと、どう取り扱ったらいいかというのはわかりませんけれども、意見だけ述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"中島委員","kind":"質問","question":"非常にいろいろ考えなきゃいけない部分があるかもわかりませんが、特にこの請願では、イネを守るということで出ていると思うんですね。そういった意味で、イネがいろいろ開発されて、何か弊害があるというものが出てくるんか尋ねました。","respondent":"谷田部学務課長","answer":"いろいろされているという話も、私どももいろいろ調べて、わかってきてあります。それから、実用化には至っていないという状況ですので、ひとつよろしくお願いを申し上げます。","id":"exchange-044"},{"speaker":"中島委員","kind":"確認","question":"再度確認をしておきたいんですが、はっきり解明されるまでは、今は、学校給食には用いないという方向で、品川区では取り組んでいらっしゃるのか尋ねました。","respondent":"谷田部学務課長","answer":"それは、遺伝子組換え食品全般のお話でございましょうか。","id":"exchange-045"},{"speaker":"中島委員","kind":"意見","question":"これは私の意見です。皆さんもご意見があると思いますので、意見としておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-046"},{"speaker":"高星委員","kind":"意見","question":"あるいは、どこからどこまでどういう表示をするのかというのは、まだまだ私たちは主体的に研さんを積まなきゃならないのかなという気がいたします。これは意見ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"高星委員","kind":"確認","question":"今の指導課長の話に、ちょっとだけ確認したいんです。学校の裁量というのは校長裁量なわけで、そこのところを確認したいんです。","respondent":"青木指導課長","answer":"私が学校裁量と申し上げましたのは、それぞれの学校の卒業対策委員会が、当然、学校と相談しながら決めますので、そういう広い意味での学校裁量というふうに言わせていただきます。","id":"exchange-048"},{"speaker":"沢田委員","kind":"質問","question":"別に質問というわけではないんですけれども、助成はちょっと出ているんですよね、全く保護者負担か尋ねました。","respondent":"青木指導課長","answer":"これは保護者負担になっています。","id":"exchange-049"},{"speaker":"沢田委員","kind":"意見","question":"そういうことも考えますと、こうしなければならないということを議会が決めることは、ちょっとどうなのかなという気がしますので、やっぱりそこの卒業対策委員会、あるいは学校サイドの裁量というのが一番適切なんじゃないかと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"原委員","kind":"質問","question":"わからないことが多いんですけれども、とにかく、この内容については、学校裁量で十分じゃないでしょうか。審査することもないと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"佐藤委員","kind":"質問・要望","question":"一つだけお聞きしたい。９１０の事業所を実地調査したということが書いてあるんですが、具体的にどういう調査をなされるのか教えてほしいと求めました。","respondent":"鷹倉庶務課長","answer":"特別区の人事委員会には、給与関係の部署がありますが、そこの者がそれぞれ事業所に行って聞き取り調査をしたと、このようにとらえてあります。","id":"exchange-052"},{"speaker":"佐藤委員","kind":"質問","question":"聞き取り調査をなされるんでしょうが、正直言って、企業側に給与の問題等は、企業として最も秘密にされるところなんですが、人事委員会の方が一人で出向いて、果たして企業が素直に、うちの会社はこういう実態ですということをすんなり見せてくれるものなんでしょうかね。","respondent":"鷹倉庶務課長、指田教育次長","answer":"あるいは特別区の人事委員会、あるいは全国の人事委員会も、事業所の聞き取り調査は同じ手法でやっております。確かに協力が得にくいという状況があるやに聞いてはおりますけれども… 実際に９１０事業所に行って無作為に抽出した実施調査をやったけれども、完結した事業所数というのは全体で７６３です。","id":"exchange-053"},{"speaker":"高星委員","kind":"質問・要望","question":"日本の経済社会において、どういうような影響が出るのかということを議論されていたら、答えられる程度でお聞きしたいというのがまず一つ。どっちも難しい質問だけれども、答えられるところで、お答えほしいと求めました。","respondent":"鷹倉庶務課長","answer":"いろいろな因果絡みで、国の経済に影響を与えていくのではないかと考えています。再生に向けて取り組んでおられるということをにらんだときに、同じく襟を正してやっくいく時期に来ていると、このように考えてあります。","id":"exchange-054"},{"speaker":"石田委員","kind":"質問・要望","question":"職員給与って４３.２歳ということで、４４万２,８９３円ということで、割り算をしてここに出ているわけです。４３歳なら４３歳で、もう決まり事なのかこういうふうにしているのか、そういうところがわかれば教えていただきたい。","respondent":"鷹倉庶務課長","answer":"一番最初の１の1)に書かれているところに集約されると思うんですけれども、学歴、年齢の条件が対応すると認められる者の給与を比較する」と。","id":"exchange-055"},{"speaker":"石田委員","kind":"質問","question":"同じ比較をするときに、１００人以上と比較することが。人事委員会がどういうことをしているのかわからないけれども、これが限りなく同じ度合いになるという何か決め事みたいなものがあるんですかね。","respondent":"鷹倉庶務課長","answer":"１００人以下の部分はどうするんだというお話が、その部分をどうすべきかという形で、いろいろ検討されたやに聞いております。いわゆる比較をするための資料がない、比較できないというような実情があるので、一定規模以上のものを採用していると。","id":"exchange-056"},{"speaker":"石田委員","kind":"質問・要望","question":"そこら辺のところはどうなのかなというのが、こういう質問をしたんだけれども、こういう質問をしたということです。もし何かそういう感覚があるなら、お聞かせほしいと求めました。","respondent":"鷹倉庶務課長","answer":"おっしゃっているような形の現状は、もう数年前ぐらいから進行しているんじゃないかなと感じている部分がないことはないのが状況だと思います。こういう数字が出てきたですので、ぜひ、ご理解をお願いしたいと思います。","id":"exchange-057"},{"speaker":"原委員","kind":"質問・要望","question":"一つ確認というか、教えていただきたいんですけれども、人事院勧告は毎年してきていますよね。それとも、同じような形のところで出てくるんか尋ねました。","respondent":"鷹倉庶務課長","answer":"一定の範囲の中で無作為に選んでいくということです。考え方は一定なわけですけれども、どこをやるかということは、毎年無作為に抽出した事業所を当たっていると聞いてあります。","id":"exchange-058"},{"speaker":"原委員","kind":"意見","question":"ほとんど関係ないかもしれないけれども、その辺の抽出の仕方がどうなのかなという気がするんです。なければ、結構ですとの意見を述べました。","respondent":"指田教育次長","answer":"その上で９１０事業所を取っていますから、必ずしも、一つの大きい大分類だけを取り出しているというわけではないという形じゃないかと思います。構成員５０人以上の支社長というふうなものとか、それと合わせてくるんではないかと、このようには思っております。","id":"exchange-059"},{"speaker":"沢田委員","kind":"質問","question":"民間の給与との比較でどうなのかというのがちょっとわからないんですけれども、例えば残業手当なんかは、カウントはどうなっているんでしょうか。ちょっとそこら辺が、わかったら教えてほしいんです。","respondent":"鷹倉庶務課長","answer":"給与の比較そのものについては、残業手当は入ってございません。","id":"exchange-060"},{"speaker":"沢田委員","kind":"意見","question":"残業手当を入れるのが妥当なのかどうなのかというのはわからないんですけれども、今、民間では、現実にサービス残業が相当ある。ただ、これを言ってもしようがないので、とりあえず報告を受けておくしか、私は言いようがないんですけれども、一応、意見だけ言わせてもらいましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-061"}]},{"id":"topic-03","title":"平成１５年度区立幼稚園募集結果","agenda":"平成１５年度区立幼稚園募集結果","exchanges":[{"speaker":"中島委員","kind":"質問","question":"ここで質問すべきことかどうか、ちょっと迷っているんですが、公立幼稚園で障害のあるお子さんの入園について、肢体不自由の方は受け入れているんか尋ねました。","respondent":"谷田部学務課長","answer":"いわゆるハンディをお持ちのお子さんは、９園で、たしか全部で１５人受け入れをしています。先ほどご説明した就園児の健康診断等々で、今後、措置委員会のほうで検討していくという予定になってあります。","id":"exchange-062"},{"speaker":"中島委員","kind":"質問・要望","question":"できれば普通の幼稚園で、自分自身のハンディというのを認めながら強く生きてほしいという要望をされているご両親がいらっしゃったんです。その辺のところは、そういう審査の中で、だめになる場合もあるんか尋ねました。","respondent":"谷田部学務課長","answer":"もし可能性があるとすれば、お子さんの早期療育をすることによって、そういうお話を申し上げることもあります。親御さんと十分に相談した上で、そういう施設をご紹介する場合もあるということで、ご理解いただきたいと思います。","id":"exchange-063"},{"speaker":"中島委員","kind":"質問・要望","question":"ほんとうにそのお子さんが強く生きてほしいというその願いをくみ取っていただいて、話し合いで理解がし合えるような対応をお願いしたいと思うんです。これは要望です。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-064"},{"speaker":"石田委員","kind":"質問","question":"ちょっと１点だけ、お聞きします。これっていうのは、やっぱりその年で、その近所の住民基本台帳の子どもが多いとか、少ないとか、そういうのに連動しているものなんですかね。","respondent":"谷田部学務課長","answer":"昭和４０年代、区立幼稚園を設置して、いわゆる私立幼稚園の補完的な役割を担ってきたわけです。３０名のところを３２名ということで落ち着かれたというのは、また、そういう中での数字だろうと思ってあります。","id":"exchange-065"},{"speaker":"石田委員","kind":"意見","question":"その次とか、今の台場小学校の２年生はすごく少なくて、その比率で流れていくのはしようがないのかなという形で見ておけばいいのかというところを。私はそういうふうに見ているということですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-066"}]},{"id":"topic-04","title":"３の小・中学校空調設備工事の概要","agenda":"３の小・中学校空調設備工事の概要","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"初め、冷却方式をガスと電気ということでおっしゃっていましたけれども、実態的にはどんな割合になったのかということ。航空機、新幹線騒音で既についている教室は何教室あるのか、それぞれ教えてほしいと求めました。","respondent":"谷田部学務課長","answer":"今、改築予定しているのが、第二日野小学校の６教室、台場小学校の１２教室、それから日野中学校の１３教室、第五日野中学校の１２教室。これは、今年の５月１日現在の学級数で申し上げさせていただきました。","id":"exchange-067"},{"speaker":"沢田委員","kind":"質問","question":"４６校で約４億５,０００万円ですから、これは契約ですから、ＪＶを組まないとならないのかなと。むしろ、実際のまちばの電気設備関係のほうにダイレクトに流せなかったのかなという気がするんですけれども、そこら辺は、何か聞いていますか。","respondent":"谷田部学務課長","answer":"そこまでは詳しく聞いてないんですが、経理課の契約の方針として、一定規模以上の工事についてはＪＶを組ませてさせるということは、一応、一般法則ということで聞いてあります。","id":"exchange-068"},{"speaker":"沢田委員","kind":"質問","question":"これで言いますと、入札参加業者数、頭に１０というあるのは、例えばＡブロックで言えば、正式な名前はわかりませんけれども、三菱電機冷熱プラント、その傘下に１０社が、それを含めてあるということなんか尋ねました。","respondent":"谷田部学務課長","answer":"これは、例えばＡブロックの三菱電機冷熱プラントというんでしょうか、塩谷建設共同企業体というんでしょうか、これで一つＪＶです。ですから、この組合せみたいなＪＶが１０申込みがあったという意味なんです。","id":"exchange-069"},{"speaker":"沢田委員","kind":"質問","question":"ちょっと聞きたいんですけれども、例えば三菱電機冷熱プラントだか、塩谷建設共同企業体の、実際に仕事の取れる業者数というのはわかるんですか。私の思いとしては、せっかくこういう機会だから、どの程度地元の業者に回ったのかなというのがわかれば教えてほしいんです。","respondent":"谷田部学務課長","answer":"契約する上で、ＪＶに対して、区内の中小企業、いわゆるここで言う三菱電機冷熱プラントと、塩谷建設共同企業体と契約するわけですね。そのＪＶに対して、要は、施工に当たっては、区内の中小企業を下請けに使ってくれるようにという指導はするというふうには聞いています。","id":"exchange-070"},{"speaker":"原委員","kind":"質問・要望","question":"各学校の工事ですけれども、Ａブロックがありまして工事をしていくんですけれども、問題のある学校というのはあったんでしょうか。要するに、問題のある学校あったのかどうか、それをちょっと教えていただきたい。","respondent":"谷田部学務課長","answer":"例えば教室がばらばらになっているのを大体１カ所に集めてくださいというようなお願いもしながら、今回、各ＪＶのほうに流したわけです。そういう部分での問題は、多少あったというのは事実です。","id":"exchange-071"},{"speaker":"原委員","kind":"質問","question":"そこに室外機を置いたときに、効率的に果たしてそれだけのものが使えるかどうか、ちょっと疑問が出てくるんです。専門的なことで申しわけないですけれども、どうなんか尋ねました。","respondent":"谷田部学務課長","answer":"東京ガス方式は１００ｍまで、東京電力は５０ｍまで伸ばせますと、規格上では冷やすことはできますという話は聞いてあります。そういうような対応ができなければ、ビルも冷やすことができませんから、性能的には問題がないという話は聞いています。","id":"exchange-072"},{"speaker":"高星委員","kind":"質問・要望","question":"何か積算基準が結構いい加減になっているという話は聞くんだけれども、その辺は、ほんとうのところはどうなっているのか。それは営繕のほうでやられるんですか、そのことだけちょっと参考のために教えてほしいと求めました。","respondent":"鷹倉庶務課長","answer":"平成１４年度から、従来あった施設課を、ある意味では改定するような形で、各事業部ごとに効率的運営ができるような形をとってあります。したがいまして、今、ちょっと十分でないというお話がございましたけれども、それはちょっとどうかなと考えています。","id":"exchange-073"},{"speaker":"高星委員","kind":"質問","question":"庶務課長の言われるとおりだと思うんですが、じゃあ改めて聞きます。これだけの積算があって、付帯工事ができたような場合については、そこのところの基本的な考え方だけちょっとお聞きして終わりたいと思います。","respondent":"鷹倉庶務課長","answer":"当初から予定されている付帯工事なら、追加が必要なら追加という形で工事を進めていく、これが原則だと考えております。","id":"exchange-074"},{"speaker":"高星委員","kind":"質問","question":"トータル的には、補正でいくんだろうけれども、その範囲内に収まるんですか。心配なんですけれども、設備工事だけでこんなにいっちゃって大丈夫なのか、見通しだけ聞いて終わります。","respondent":"谷田部学務課長","answer":"ですから、今補正では２億７,０００万円です。来年度予算で、残りの１億８,０００万円という予定だったんですが、その予算内に収まるということで、今回、済んでいるです。","id":"exchange-075"},{"speaker":"石田委員","kind":"意見","question":"どうしてそんなことを言うかというと、普通のまちばの電気屋や冷房屋の中のガスが問題になっているわけで、ガスを交換できなくなっているんですよ。","respondent":"谷田部学務課長","answer":"８年間お借りするわけですから、リース期間中は、所有しているリース会社のほうで一定程度の対応をとるというのが基本的なものになってあります。電気、ガス会社とも一定の性能も保証していますので、そんな問題はないと思ってあります。","id":"exchange-076"},{"speaker":"上山委員","kind":"質問・要望","question":"先ほどの説明で、かなり大きな工事だと言っていたんですけれども、例えばＡブロックだと、通常１１校になっていますけれども、どういう分け方なのか。例の学校ブロックで分けたのか、ちょっとそこ辺、わかれば、どんな感じなのか、教えてほしいと求めました。","respondent":"谷田部学務課長","answer":"１３２教室というふうに、設置する工事もある程度バランスよくいくようにということで、経理のほうで出したという状況です。","id":"exchange-077"},{"speaker":"高星委員","kind":"質問","question":"ここでは、小学校、中学校という形でできるんですが、いろいろ話をする中で、幼稚園の空調化をやるという話を聞いていたんですが、これはここに入っているんですか、どうなのか、ちょっと聞いておきます。","respondent":"谷田部学務課長","answer":"前にもお話ししたと思うんですけれども、幼稚園は、来年の予算の中で設置していきたいということで、財政当局と、今、詰めている段階です。","id":"exchange-078"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/547087?Template=document&Id=4456#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":55574,"voices":190}},{"id":"h14-20021125-5","meetingId":"h14-cm11","date":"2002年11月25日","dateIso":"2002-11-25","committee":"総務委員会","time":"午前１０時０７分～午後１２時５５分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を59件整理しています。","topics":[{"id":"topic-01","title":"１の第６７号議案、品川区議会議員および品川区長の選挙における選挙運動の公費負担に関する条例の一部を改正する条例","agenda":"１の第６７号議案、品川区議会議員および品川区長の選挙における選挙運動の公費負担に関する条例の一部を改正する条例","exchanges":[{"speaker":"桜井委員","kind":"確認","question":"根拠なんですけれども、値上げの根拠というもの。品川区だけ改正するのか、全体的な２３区の実態、その辺のところをちょっと確認したいと思います。","respondent":"野田口選挙管理委員会事務局長","answer":"考え方ですけれども、これについては同じ選挙区、地域を基盤に選挙を行ってあります。同じような車種の自動車を使って行いますので、選挙が行われる地域内で使用する自動車については公費負担額を合わせるといったものです。","id":"exchange-001"},{"speaker":"林（宏）委員","kind":"質問","question":"今の車種の説明の中で、衆議院も地方議員も同じ単価でしたっけ。例えば今回の例でいうと、運送契約というのは、運送屋と運転手つき車の借り上げとか、それで、衆議院議員の方が、多くなかったか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"選挙運動用自動車の車種の違いとか料金の違いというものは、地方公共団体と国の中でも、町村の長と議員の選挙については種類が違いますけれども、国政選挙と都議会議員とは車種と契約の単価は同じです。","id":"exchange-002"},{"speaker":"林（宏）委員","kind":"質問","question":"そのほかのところも同じですか。区によって１,６００円とか、現行よりも違うようなことが書かれているんだけれども、同じか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"１枚当たりのポスターの単価については同じです。品川区の場合には公営掲示場が３４０カ所ありますけれども、その掛ける２倍ということで、都議の場合には単価は同じです。","id":"exchange-003"},{"speaker":"林（宏）委員","kind":"意見","question":"枚数は掲示板の場所の数だとか、単価×場所の数とかというのはあれなんだけれども、区によって違うというふうに書かれているんですよ。２３区それぞれがこのポスター１枚当たりの単価については決められるというような判断が認められるのかどうかとの意見を述べました。","respondent":"野田口選挙管理委員会事務局長","answer":"ちょっと説明が不十分で申しわけございません。ポスター掲示場の数によって異なる部分のいわゆる作成単価、全体の単価については各区によって異なる、そういうものです。","id":"exchange-004"},{"speaker":"林（宏）委員","kind":"質問","question":"例えば品川区だと３０万１,０００幾ら、掲示場の数でいうと、大田区なんかは５００カ所ぐらいあるのかな。だから、この企画費という３０万１,０００幾らというのも、よその区と同じだと、広さによって変わるということはないんか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"委員がご指摘のとおり、それから５００カ所以上については、ちょっと今すぐに数値は。〔「２種類ですか」と呼ぶ者あり〕２種類です。","id":"exchange-005"},{"speaker":"林（宏）委員","kind":"確認","question":"細かく言うと５０１と５００までというように、その２種類が違う、２種類に限られるんですか。それからもう一つ、この辺も衆議院も地方議員も同じか尋ねました。","respondent":"野田口選挙管理委員会事務局長","answer":"２種類です。それから、この作成単価については全国的に同じです。","id":"exchange-006"},{"speaker":"林（宏）委員","kind":"意見","question":"全体的な話になるんだけれども、例えばこういうもののポスター作成なんていうのは、エリアによって大分違うと思うんですよね。その言い方がいいかどうかわからないけれども、物価指数の高いエリアとよそとが区別されているのかということはわかりますかとの意見を述べました。","respondent":"野田口選挙管理委員会事務局長","answer":"この公費負担の単価は、例えばポスターの場合については公費負担はここまで負担しますよという限度額なんですね。このポスター作成費も入りますので、そういった意味では、これは全国的に国が定めているところでは同じということになります。","id":"exchange-007"},{"speaker":"林（宏）委員","kind":"意見","question":"なぜそんなに違うのか。ここでそれを品川区の選管に言ってもどういうことになるという思いはありませんけれども、そういう議論は選管の局長会議とかいうところで出ませんかとの意見を述べました。","respondent":"野田口選挙管理委員会事務局長","answer":"それからあと、やはり選挙運動期間とかというのも、本当に短い間に、先ほど言ったような政権放送とかいろいろあります。そういうことも背景になろうかと思います。","id":"exchange-008"},{"speaker":"桜井委員","kind":"質問・要望","question":"ちょっと聞きたいなということがある、今インターネットの選挙の関係で、何か動きがわかったら、参考までにお聞かせほしいと求めましたんですけれども。","respondent":"野田口選挙管理委員会事務局長","answer":"まだ法案として成り立つにはそれぞれの各政党に対していろいろ関係者に説明をして、その合意を得た段階で法案として。現段階ではそういう規定がございませんので、インターネットを利用しての選挙運動はできないというふうな状況です。","id":"exchange-009"}]},{"id":"topic-02","title":"２の第６８号議案、特別区競馬組合規約の変更","agenda":"２の第６８号議案、特別区競馬組合規約の変更","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"３点目には、そういうのは何らかの対応策というのか、そういうのもあるんでしょうか。当然会計管理、公認会計士とか、そういう本格的な配置なのかわかりませんけれども、ちょっとそこを教えていただけますか尋ねました。","respondent":"古川総務課長","answer":"前２項に掲げる場合のほかということで、先ほどご説明した一定の流れの中で、そういったことからこの規定を設けた。もちろんこの通知を受けてどう対応するかということだと思うんですけれども、それぞれの運営主体の中で判断をするというふうに考えております。","id":"exchange-010"},{"speaker":"桜井委員","kind":"質問","question":"ただ、前に例えば大井競馬場なんかも、果たしてああいう形でいいのかどうかというあり方論が結構論議になったことがあるんですよね。積み立てをして、そういうのというのは全然消え去っちゃって、今の現状維持と赤字を解消していくのかというところに論議が行っているんか尋ねました。","respondent":"本間総務部長","answer":"もともと官庁会計ではやりにくいという考えを持っていて、それで、官庁会計ではやりにくい面というのはいろいろありました。そういうものを、今回のこの通知を境に解消してということで、そういう背景がありますことにをひとつご理解をいただきたいと思います。","id":"exchange-011"},{"speaker":"塚本委員","kind":"質問","question":"手続の問題と、それから、例えば収入役がいなくなると、出費が減るんか尋ねました。","respondent":"古川総務課長","answer":"収入役の廃止の分ですけれども、現在報酬等につきましては、条例の中で収入役は年額が２９万６００円ということで、ここのところについては、減ります。","id":"exchange-012"},{"speaker":"塚本委員","kind":"意見","question":"それはどういうふうに反映して、品川区議会の意見というのはどういうふうに伝わるのか、そういう順序みたいなものをわかりやすく説明していただけますかとの意見を述べました。","respondent":"古川総務課長","answer":"この協議書をそれぞれ２３区区長が合意したものを、都知事のほうへ規約変更の許可を申請をする。許可がおりましたらば、実施をする、流れとしては以上です。","id":"exchange-013"},{"speaker":"塚本委員","kind":"提案","question":"だれが発意して提案したのか、品川区議会の意思はこうなったけれども、それはそのまま全体の意思になるとは限らない。そうした場合はどうなっていくのか、それはそれで品川区議会の意思は言ったけども通らなかったというんだけれども、そういう格好か尋ねました。","respondent":"古川総務課長、濱野助役","answer":"先ほど言いました区長会において、競馬組合の２３区区長会のほうでその規約の変更を決定し、特別区競馬組合議会に報告をした。議会の議決を経て、２３区が改めて協議をし、都知事に許可の申請をするという流れです ２３区の区議会のうち、どれか一つでもこの議決をしないということであれば、この規約の変更というのは成り立たない。これは清掃一部事務組合でどうかというふうな組合等と同じ扱いです。","id":"exchange-014"},{"speaker":"土井委員","kind":"質問・要望","question":"いわゆる中の決定というんですか、こういうものをどうしていくのかということが、この公営企業法には何かないんですか。というのは、あるいはいわゆる企業的会計をやるためには企業的運営をしなきゃならんというその部分との兼ね合いがいろいろあるものですから。","respondent":"古川総務課長","answer":"これは従前と同じですけれども、２３区が提示した一連の流れで特別区競馬組合の中の組合の意思をさまざまな手続、会議等をしながらやっていく。あくまでも会計処理だけの変更です。","id":"exchange-015"},{"speaker":"土井委員","kind":"質問","question":"もっと一般企業的な運用をするようなことが書いてあったりして、その条項を適用すれば、そういうのができるとかいう可能性があるのかないのかということをお聞きしている。","respondent":"古川総務課長、濱野助役","answer":"先ほど申し上げましたように、政令、条例で定めた場合には、この公営企業法の中の一部あるいは全部を適用することができる。これにのっとって、適正に維持していく、これは法の定めです。 これを単年度会計でやりますと、その年の支出として、載るだけです。この事業はもうかっている、そういったさまざまな経営の指針となる指標等がこれで明らかになるということが一番の眼目だというふうに考えております。","id":"exchange-016"},{"speaker":"土井委員","kind":"質問","question":"公共の福祉を含めて検討されていかなきゃならん課題だなというふうにも思って、ちょっと引っかかっていたものですから、お伺いした。そっちのほうの地方公営企業法の中にそういう政策決定的な意味も含めたものも多少なりとも入っているのかなということもあってお伺いをしたわけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-017"},{"speaker":"藤田委員","kind":"質問","question":"例えば開催日以外のですね、何か競馬以外の目的でもこれから何かの収益を上げようという場合、考えられないこともないんですけれども。そういうことも含めて、この今回の改正というのはあるんか尋ねました。","respondent":"古川総務課長","answer":"２３区が経営する競馬という観点からも、公共の福祉という考え方も、その辺の兼ね合いによって事業の選択も当然出てくるというふうに思ってあります。","id":"exchange-018"},{"speaker":"藤田委員","kind":"質問・要望","question":"わかりました。競馬場が品川区内にあるわけですから、競馬以外での収益事業ということもぜひ考えてほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"林（宏）委員","kind":"提案","question":"今、各区からいろんな経営的あるいは戦略的な提案があってもいいと思うんですけれども、そういうようなことを品川区に限らず２３区がやっているのか。経営的な部分については言っていけるのか、言っているのか、その辺のことを一つ聞きたいとの意見を述べました。","respondent":"古川総務課長","answer":"先ほど申し上げました、特別区競馬組合は２３区が一部事務組合を設けるという規約の中で、各区が持っている検討の事由をそこに持ってきている。やり方はさまざまな会議体、課長会、部長会あるいは助役会、区長会などで行っております。","id":"exchange-020"},{"speaker":"林（宏）委員","kind":"意見","question":"１９か２０区、何もしないで入ってくる。あるいは、もちろん高橋区長が区長会の中で言っていらっしゃるとは思うんだけれども、どんどん言っていかなきゃいけないのかと思うんだけれどもとの意見を述べました。","respondent":"本間総務部長","answer":"これが一定金額なければ今後の検討もできないということから、これの取り崩し等も含めて非常に強く物を言ってきたというふうな経緯があります。もう１点は、そういう方向で物を言っていくという姿勢でおりますので、よろしくご理解のほどをお願いいたします。","id":"exchange-021"},{"speaker":"林（宏）委員","kind":"意見","question":"こういうところが競馬場経営、競馬経営という言葉でいいのかどうかわからないけれども、やはり健全経営になっていくのかという説明が欲しいんだよね。","respondent":"本間総務部長","answer":"競馬議会等にご説明ができるということで、今まで以上に競馬議会の議員方、それから幹事会等もどういう実際の売り上げの状況にあるかを把握できるようなよりわかりやすくなるような資料を今後提示をできるというふうにひとつご理解をいただきたいと思います。","id":"exchange-022"},{"speaker":"林（宏）委員","kind":"意見","question":"今までも監査はいらっしゃるんだけれども、例えば常勤監査が入ってくるとか、そういう必要がないのかどうか。今まで区長が１人、交代でやっていたから年間２０何万円なんだけれども、それはどういうふうにこれからしていくのかとの意見を述べました。","respondent":"古川総務課長","answer":"組織の関係でご説明申し上げますと、この監査体制そのものが今回変わるということになっておりません。先ほどご説明しましたけれども、さまざまな経費等、今後さまざまな資料というようなものを提示できると思ってあります。","id":"exchange-023"},{"speaker":"塚本委員","kind":"質問","question":"この基本的な会計方法をめぐる問題を、企業的会計方法にどういうふうに表現したらいいのか、それからこっちに変えていくということなんですか。基本的には競馬組合のことですから、その上のほうがどうにか考え方が変わったから変えれるようになったのか、その辺の説明がなかったので。","respondent":"古川総務課長、本間総務部長","answer":"お答えになっておりませんかもしれませんが、その規約の中で、根拠になります地方公営企業法の第３条の適用との説明をいたしました。改めて競馬組合の中で、条例を制定をし、具体的な企業会計方式則った運営をしていくです。 各区から出ている管理者がこの競馬組合の考え方をよしとして、先ほど来総務課長がご説明しましたように、規約を改正しようという流れになっております。","id":"exchange-024"},{"speaker":"塚本委員","kind":"意見","question":"こんな習慣でいいのかどうかというところが問題で、どれだけの権限があって、こういうふうなやりとりになったかということを知りたいわけです。皆さん方、ある意味では皆さん方のことも批判しているわけですけれども、どう思われますかというとの意見を述べました。","respondent":"濱野助役","answer":"そういう認識は持ちつつ、我々の持っている目的意識から言ってもこれは合致するものだということで、積極的に取り上げているわけであります。そもそもの物の考え方が改まっていないということについては、私たちもいささか疑義を感じているところであります。","id":"exchange-025"}]},{"id":"topic-03","title":"平成１４年請願第２３号、品川文化振興事業団のアルゼンチン国債購入問題の真相解明と損害賠償を求める請願","agenda":"平成１４年請願第２３号、品川文化振興事業団のアルゼンチン国債購入問題の真相解明と損害賠償を求める請願","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"どういう形になるかちょっとわかりませんけれども、例えばここの今この委員会で一定の決着の方向ですか、かなり不可能に近いですよね。審査の前にお諮りいただきたいなというふうに思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-026"},{"speaker":"桜井委員","kind":"質問・要望","question":"今、実際に今アルゼンチン債の関係で損害がどうなっているのかという、その後の状況をつかんでいたら教えていただきたいなというふうに思います。そうすると、これは理事会ということに考えているのか、そのあたりのところをもう一回教えてほしいと求めました。","respondent":"中尾根企画部長","answer":"それは、すぐ１カ月後の今月に入りまして、アルゼンチンの経済的な苦境がさらに一段と進んだのではないかというような新聞の解説がございました。","id":"exchange-027"},{"speaker":"桜井委員","kind":"確認","question":"そうなると、そこがいわば確定という、正式に理解していいんでしょうか。１億６,０００万円は文化振興事業団の責任というんでしょうか、そういうものすべて入るわけですけれども、その確認をしたいというふうに思います。","respondent":"中尾根企画部長、市岡企画財政課長","answer":"通常会社等での処理としましては、損金として会計の処理をすること等が税法上も認められている、こういう関係にあるわけですね。何年をかけてどう処理するのかということ、それは財団の今後の運用の判断の中に入ってくる… １億円のほうは年利が５.４％、年間で１億円のほうで５４０万円、それから６,０００万円のほうで２９１万円が予定されております。","id":"exchange-028"},{"speaker":"桜井委員","kind":"質問","question":"この前８月に伺ったときも、それがまず合法的というふうに言っているけれども、根拠が薄いというふうに思います。だから、私はこの３点からしても、区の損益だというふうに考える根拠はないんじゃないかというふうに思うんですけれども、濱野助役に聞きます。","respondent":"濱野助役","answer":"信濃鉄道ですか、要するにそういうような形でもっていくのではなくて、財団の中で独自の処理をしていくというふうに考えているところです。このことについては責任を明らかにしたです。","id":"exchange-029"},{"speaker":"桜井委員","kind":"質問・要望","question":"だから、そこの点についてもう一つ、なぜ私はそうであれば関係者を例えば理事会としても告発しないのかというのは依然として区民の声なんですよね。これについて明確にしていただきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"桜井委員","kind":"質問","question":"私は発生する損害について言っているんです。委員長はそういうふうにとるかもしれませんけれども、私はこの項目について質問しているんです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-031"},{"speaker":"桜井委員","kind":"質問","question":"実際には、理事会として８月にさかのぼってやっているじゃないですか。６億２,０００万円ですか、そこの理事長がどういう態度をとったのかは、ご存じか尋ねました。","respondent":"中尾根企画部長","answer":"物の考え方としましては、損害を賠償するということですが、こういうことは責任の中で何が求められるかということなんです。それは一定の程度わかりますけれども、法的な判断等を総合的に判断すると、これまで言ってきた主張のとおりさせていただきたいと思います。","id":"exchange-032"},{"speaker":"桜井委員","kind":"提案","question":"ですから、補助金のかかわり方で、平成１３年、１４年度で見ますと、確かに補助金を削減していますよね。私は少なくとも１億６,０００万円、例えばそういう考え方もあってしかるべきじゃないかと思うんですけれども、今の考え方との意見を述べました。","respondent":"市岡企画財政課長、濱野助役","answer":"その点では区の補助金の支出についての問題点のこういう問題とははっきり区別をして、私ども整理をしています。補助金が平成１３、１４年度で減額されているのは、そういうことで申し上げます。それで、この問題が発生した経緯だとか、それぞれ事情があろうかと、それぞれの団体でそれぞれにご判断いただいた結果だと思います。","id":"exchange-033"},{"speaker":"桜井委員","kind":"質問","question":"実際に補助金、あくまでも基本財産というんですか、基本財産のほうだから区の補助金をどうしたとは関係ありませんと言い張っていますよね。質問です。","respondent":"中尾根企画部長","answer":"そういう考え方の判断のもとですから、基本財産で運用してください、そういう考え方です。それからカルチャーのほうでは１億３,９００万円余、今回のことを考える、そのことについての基本的な考え方は変わりはございません。","id":"exchange-034"},{"speaker":"桜井委員","kind":"質問・要望","question":"最後にちょっと質問させていただきたいんですけれども、区民に明らかにしてほしいというのがありまして、これは一番最後のあれですよね。それってやっぱり区民との関係では非常にさらに疑問も深まるんではないか尋ねました。","respondent":"山田広報広聴課長、中尾根企画部長","answer":"区議会だよりでそれぞれの方が第１回定例会の中でそれぞれ各党からの質問要旨、第２回第３回定例会も質問、答弁の要旨を載せております。ある意味では区議会サイドからの情報の周知ということが図られておりますので… それと区民ギャラリーのほうが５００万円、それと文化事業積立金が３,０００万円ですね、このようにお受け取りいただきたいということです。念のためにつけ加えします。","id":"exchange-035"},{"speaker":"桜井委員","kind":"質問","question":"皆さんのやっぱりさまざまな思いということについてはやはり区民の皆さんの立場から、ぜひ私はお聞きをしたいというふうに思っています。参考人としてもぜひお呼びしたいなというふうには思いますので、この意見陳述の後、委員長にお諮りをしたいなと思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-036"},{"speaker":"塚本委員","kind":"提案","question":"せっかく委員長のご提案なんですけれども、桜井委員のほうから大変懇切丁寧に他の事例等も説明というんですか、わからなくなっている。先ほどからの質疑を聞いていると、相当詳しいように思いますので、そのところについて桜井委員にお伺いしていいか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-037"},{"speaker":"桜井委員","kind":"意見","question":"紹介議員になってほしいというお話のところで理解をするには、副理事長、それからやっぱりそこにかかわった方々がいますよね。だから、そういうふうに私の受け取り方はそうですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-038"},{"speaker":"塚本委員","kind":"質問","question":"責任をとって穴埋めしろというのは、それは損害額を補てんしろというふうに訳し直していいわけですか。どこまでのことをしてほしいと願っているのか、どういうことを望んでいるのか、桜井委員は。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-039"},{"speaker":"桜井委員","kind":"質問","question":"あるいは今回理事会としても承認をされたわけですから、そこのところ、やはりそれは関係者の良識に任せることになるんですよね。法的にどうなのかというのは、また違う次元の話なので、もう少しお聞きしたければ、直接陳述をいただいたらいいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-040"},{"speaker":"桜井委員","kind":"質問","question":"態度の前にちょっと１点だけ自民党にお聞きたいんですけれども。質問されたからお聞きしたいんですけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-041"},{"speaker":"塚本委員","kind":"提案","question":"請願にそんなこと言っていませんよ。提案したつもりないでしょうとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-042"},{"speaker":"桜井委員","kind":"質問・要望","question":"そうですか。やっぱり当事者にお聞きしないとわからないということで、そうしたお諮りをいただきたいということで、今申し上げているところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-043"},{"speaker":"桜井委員","kind":"質問","question":"ですから、ただ、当時あったとすれば、当然ながらその方の責任というのが問われてしかるべきだと思っているんです。ですから、そして実際に前事務局長がその後の事務局長だったわけですから、議会でもお話を伺いたいというふうに。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-044"},{"speaker":"塚本委員","kind":"提案","question":"今のご提案と、この請願ということの関係はどういうふうになるんですか。請願との関係で、それはごちゃごちゃに話が進んでおりますので、請願にはそんなことも書いているとなかなか読み取れないわけですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-045"},{"speaker":"桜井委員","kind":"質問","question":"それはそれとして理解できますけれども、改めて議題に載っていないわけですから、請願の審議のときにお話し申し上げたということです。改めて議題に載せているわけではないですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-046"},{"speaker":"林（宏）委員","kind":"提案","question":"今の提案はわかるんだけれども、お２人を呼ぶ必要がなぜあるのかというのが非常に疑問で、言われている。今この請願をどう取り扱うかという審査をしているときに、お２人をここに来てというのは、それだけ申し上げておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-047"},{"speaker":"林（宏）委員","kind":"質問","question":"継続か、今日結論とるかということと、それから、参考人の意見表明をして、どうだというのと、一緒にやるんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-048"},{"speaker":"林（宏）委員","kind":"質問","question":"違う、違う。この今審査している請願の採決を今日やるのか、継続にするのかというのを先にやらないと、それと一緒に参考人の賛否も表明するんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-049"},{"speaker":"塚本委員","kind":"意見","question":"そういうことからして、十分にこの請願の趣旨は我々は十分に対応しているというふうに思っています。これ以上継続して審議する必要はないというふうに思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-050"},{"speaker":"藤田委員","kind":"質問","question":"そういう人たちがてっぺんにいらっしゃるわけですから、これは見解の相違なんですから、結論を出してくださいというような気持ちです。こういうことですので、それをこうした請願にまた出してくるということについては、もうまさに見解の相違ということにふうなことでしかありません。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"桜井委員","kind":"質問・要望","question":"それで、今申し上げたように、十分な審議をしたいというふうに思っているわけで、継続していただきたい。意見は後ほどでよろしいですね。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-052"},{"speaker":"桜井委員","kind":"質問・要望","question":"すべきという、依然としてアルゼンチン債問題は区民の大きな関心事であるというふうに私はしていきたいと思います。それぞれの関係者が自分の責任で賠償責任しているというところもあるわけですから、少なくともこの問題は、損害の出た場合。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-053"},{"speaker":"桜井委員","kind":"質問","question":"船波議員の、住民参加を進めるためにの、質問が一般質問の初日にありまして、それに関して質問をしたいと思います。施策を決定する際についての住民参加の保障をどうするかということがありまして、審議会の運営、公募の住民参加の制度としてのあり方のところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-054"},{"speaker":"桜井委員","kind":"質問","question":"１０年前の中身は何だったんですか。私は松崎学園のときに記憶があるんですが、それか尋ねました。","respondent":"福田区議会事務局長","answer":"これはＮＨＫ静岡からの撮影の申し入れということから見ますと、おそらく松崎ではなかろうかと思います。","id":"exchange-055"},{"speaker":"林（宏）委員","kind":"質問","question":"どうしても委員会の中にテレビ撮影、もちろん音も含めてだろうと思うんだけれども、切り出して使われるんですよね。全部が全部放映するなんていうことはあり得ないことですから、僕は今回もなしというふうにしたほうがよろしいのではというふうに申し上げます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"藤田委員","kind":"質問","question":"ですから、そういう判断をいたしました。品川区だけではなくて全国的な報道をされるということで、委員の真意を私は第一主義にするべきではないかと、こう思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"桜井委員","kind":"意見","question":"いろいろと心配する向きもなくもないんですけれども、積極的に公開して、そのままもう姿をぱっと出すというのもいいかなと思います。それを皆さんが反対ならば、それはその意向に沿いますけれども、意見としては賛成ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-058"},{"speaker":"土井委員","kind":"質問","question":"この時代ですから、そのままそこでインターネットで送ろうと思えば送れちゃうわけですから、そのように考えます。そういう論議が巻き起こるような形でやるのが適切であるかどうかということは疑問のところもありますので、あとは委員長にお任せします。","respondent":"伊藤委員長","answer":"それから、写真撮影につきましては、もし申し出があれば、また改めて検討するということで、もし来たらということで、よろしくお願いいたします。","id":"exchange-059"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1602#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":46413,"voices":145}},{"id":"h14-20021126-6","meetingId":"h14-cm11","date":"2002年11月26日","dateIso":"2002-11-26","committee":"区民委員会","time":"午前10時05分～午後２時２６分","status":"正式会議録","sourceType":"formal","overview":"区民委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を24件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"三上委員","kind":"確認","question":"使用料の中で、等級のない平等な料金設定というお話の中で、ちょっと聞き方が私、どうだったのか確認するんですけれども、客室によって使用料が違うとおっしゃったんか尋ねました。","respondent":"宮地区民課長","answer":"利用するごとに各室ごとに使用料を定めるということで、例えば式場、会葬者控え室、それから遺族、僧侶等の控え室、利用の目的がさまざま違っていますので、それぞれについて使用料を定めるです。","id":"exchange-001"},{"speaker":"三上委員","kind":"質問","question":"そうすると、多少狭いような部屋というのもあるのかなと。その中でのこの料金設定というふうに少し考えたのかなあと思ったんだけれども、そうじゃないんか尋ねました。","respondent":"宮地区民課長","answer":"式場は４室、全く同じ広さです。単室の２倍弱というような設定になろうかと思いますが、待合室も全く同じ大きさで、多様なタイプを設けているというわけではございません。","id":"exchange-002"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"民間を圧迫しないという意味を含んでいるんじゃないなと思いますけれども、非常に気になったんで、その辺どうなのかなということ。桐ケ谷が幾らぐらいで、こっちが幾らぐらいを想定しているのか、それも教えてほしいと求めました。","respondent":"宮地区民課長","answer":"今のところ、大人で火葬料は骨壷の容器込みで２万５,０００円というふうに考えてあります。式場等を利用した場合、桐ケ谷ですと２２万５,０００円のところを１１万６,０００円強程度ということで考えているところです。","id":"exchange-003"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"無料にというふうな論議というのがどういうふうになっていたのかなというふうなことをお聞きしたいのと、これは５区が、ランニングコストに対しての補助金というものはどうなっているのかについて説明を求めました。","respondent":"宮地区民課長","answer":"今、お示ししました基本方針は５区での打ち合わせの結果まとめたものですので、最終的にはこういう形になったです。ですから補助金ではありませんが、分担金を支出しながら運営に乗せていくということで、おおむね５年から６年はどうしても赤字になってまいります。","id":"exchange-004"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"具体的にそういうふうな中身、例えば、職員ですとか、そういうふうな料金とかというふうなことも含めて１６年の１月から開業予定というふうなことでしたけれども、具体的にはいつぐらいに決まるんか尋ねました。","respondent":"宮地区民課長","answer":"その前、恐らく３カ月前ぐらいまでにはＰＲ等のチラシもつくらなければならない関係で、かなり急ピッチで詰めていくことになると思います。おおむね、来年の１月開かれる来年度予算の議会が一つの詰めの部分だというふうに考えております。","id":"exchange-005"},{"speaker":"三上委員","kind":"質問","question":"この午後１時の段階、ちょっと私聞き漏らしたんだけれども、どういうふうにお知らせするんですか。どうなんか尋ねました。","respondent":"久保田防災課長","answer":"小山２丁目東部町会のほうに協力をお願いしたんですけれども、それから支援者等を募った段階の中で、今回考えていないというところが一つです。支援者ということでそれぞれありますので、１時というのは、それぞれ集合場所に集まっていただくというような想定にしております。","id":"exchange-006"},{"speaker":"三上委員","kind":"質問・要望","question":"当然取り組むのかわかりませんけれども、こういう形での災害弱者の皆さんのシステム化ということにしっかりと取り組んでほしいと求めました。ぜひ成功させてもらいたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-007"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"これちょっと１、２年前なんですけれども、そして民生委員の方はプライバシーがあるから言えないと。そして、支援をしていただきたいというふうなところは、知らされているのかどうかをちょっとお聞かせいただきたいんですが。","respondent":"長田地域活動課長","answer":"そういったことで対応しているんですけれども、民生委員さんが１３地区下に分かれまして、ここでの協力関係というのが非常に強まりました。","id":"exchange-008"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"この１２１名というのは、品川区全体で１２１名ということなんですか。この１２１名の方に関しては、１２１名の方が自分でいいですよというふうなことで了解が得られたというのが１２１名ということでいいんか尋ねました。","respondent":"長田地域活動課長","answer":"ご本人の意思を確認した上で、名簿に載せて公表をしていただいて結構ですという確認をいただいた方の数字です。","id":"exchange-009"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"今回のこの被支援者という方は、実際にそういうふうな被支援者の方なんでしょうか。例えば、こういうところに見学に行かせていただくとかというふうなことができるかどうか、ちょっとお伺いしたいんですけれども。","respondent":"久保田防災課長","answer":"１カ所、ほかの町会なり、あるいはそういう町会長なども含めて見学を実際はしていただいたほうがいいのかなというような考えも持ってあります。全く最初ですので、まずはちょっとやってみて、その辺の状況をまず検証したいというところで始めたいという形です。","id":"exchange-010"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"ぜひ成功させていただきたいなというふうに思うんですが、自分の町会でもこういうふうなものをぜひやっていただけないかというふうな希望があれば、そんなことも含めてあるいは要望にこたえていただくというふうなことはできますか尋ねました。","respondent":"久保田防災課長","answer":"私ども、もちろん希望があるなしにかかわらず、こちらからも積極的に働きかけてやっていきたいというふうに思っています。そういうようなことから、そういうことを加味した形での各町会の取り組み方をやっぱり我々としては支援していきたいというふうな考えです。","id":"exchange-011"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"本当に、新たな取り組みということでぜひ頑張っていただきたいなというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"関係職員の周知、研修ということで４日間の日程でやられたということなんですけれども、これは何人ぐらいの方が受けられたんですか。苦情問い合わせが、最終はいつぐらいまで受け付けていて何件ぐらいかというのがわかったら教えてほしいと求めました。","respondent":"冨田戸籍住民課長","answer":"１１月６日、その所長会の席上で、私それから担当のほうから同様の内容の説明をしたものです。地域センターのほうに事務検討会がございまして、各地域センター１名ですけれども、あわせて地域センター全体に周知方をお願いしたところです。","id":"exchange-013"},{"speaker":"鈴木（ひ）委員","kind":"確認","question":"２次サービスが来年の８月からまた新たに開始になると思うんですけれども、そこら辺のところの確認と、その点についてちょっと説明を求めました。","respondent":"冨田戸籍住民課長","answer":"住民基本台帳カードにつきましては有料で交付の予定です。それから、交付手数料ですけれども、現在検討中です。","id":"exchange-014"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"懇談会というのはどういう種類のものだったのかを教えていただきたいのが一つと、やはりこういうものを出していくということが求められていると思うんですけれども、そこら辺のところも考え方について説明を求めました。","respondent":"金井環境課長","answer":"当委員会にご説明したときに、２名ぐらいを予定しているということで、もっと多くをというお話がございまして。余り難しいことは結構ですので、ふだん感じたことをそのまま言ってくださいとおっしゃっても、なかなか。","id":"exchange-015"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"区民参加の懇談会というものが立ち上がっているということについてちょっと存じていなくて質問をさせてもらって済みませんでした。そういう点では、ここら辺のところの区民参加の方向というふうなところがどうなっているかについて、ちょっと教えてほしいと求めました。","respondent":"金井環境課長","answer":"みんなが取り組んでいかなきゃいけないということで、できる限り区民参加を図りたいという趣旨で、立ち上げようという考え方を示しております。","id":"exchange-016"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"都内の条例制定の状況がわかったら教えていただきたいのと、この計画というふうなことでやるということでお聞きしているんですけれども、改めてちょっとお聞かせいただけたらと思うんです。","respondent":"金井環境課長","answer":"区は前々からご説明しておりますが、どうしてもこういった条例について聞きますと、精神条例といいますか、理念とか考え方がほとんどになると。","id":"exchange-017"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"そういう点では、その点では、条例があるといいのかなというふうに思ったところです。こういうふうなところでは、品川区は計画というふうなことについての進行管理ですか、そこら辺のところはどういうふうになるんか尋ねました。","respondent":"金井環境課長","answer":"まだ具体的な施策については、ここではお示ししておりませんけれども、今現在検討中です。こういった議論はいろいろありますけれども、何らかの形でそういった方向性としては、考えております。","id":"exchange-018"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"最後にちょっともう１点だけお聞かせいただきたいんですが、これはすごく抽象的なあれですよね。目標値の設定とか、そしてそれに向けてどうしていくかみたいな、その後の行動編というところに出てくるということになるんか尋ねました。","respondent":"金井環境課長","answer":"本当に区民の方たちに取り組んでいただけるのかとか、いろいろそういったことも考えながら、その辺もこれからいろいろ検討していきたい。可能な限り設定をしていきたいという考え方です。","id":"exchange-019"},{"speaker":"鈴木（ひ）委員","kind":"質問・要望","question":"やはりぜひ、実効あるものというふうなところで、目標を決めて、それに具体的にじゃあどうして、それがどうなったかというふうな検証も含めてやっていけるようにぜひ取り組んでほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-020"},{"speaker":"鈴木（真）委員","kind":"質問","question":"どうしても、ぜひ有効に今後使っていってもらいたいなという思いがあります。何か考えていることがあったら。","respondent":"金井環境課長","answer":"これからいろいろ考えていきたいなと思っていまして、そうすると、やはり環境商店街みたいに広がりが出てくるのかなと。産業振興課等も含めまして、いろいろ協議して、鋭意エコクリーンを整備していきたいなというふうに考えております。","id":"exchange-021"},{"speaker":"鈴木（真）委員","kind":"質問・要望","question":"要望ですけれども、無回答５.８と、すごい数字になっています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"鈴木（ひ）委員","kind":"質問","question":"工場のところが３５.５％ということで低いなというふうに思ったんですけれども、この辺のところが商店と同じようにすればもうちょっとふえたのかなというふうに思ったんですが、そこはどうしてこういうふうな状況になっているんか尋ねました。","respondent":"金井環境課長","answer":"３５％もあれば悪いほうじゃないですよという話です。内容としては以上です。","id":"exchange-023"},{"speaker":"鈴木（ひ）委員","kind":"意見","question":"こういうふうなアンケート調査することそのものも、やっぱり意識を上げていく一つのあれにもなるんじゃないかなというふうに思いましたので、できるだけそういうふうな回収の率も高くすればいいかなというふうに思って聞きましたとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/345074?Template=document&Id=2348#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=6&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":35639,"voices":91}},{"id":"h14-20021126-7","meetingId":"h14-cm11","date":"2002年11月26日","dateIso":"2002-11-26","committee":"厚生委員会","time":"午前１０時０５分～午前１１時５４分","status":"正式会議録","sourceType":"formal","overview":"厚生委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を32件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"藤原委員","kind":"質問","question":"平成１３年度は土日ということでしたが、それで申し込み人数が減ったということでしたが、それ以外の理由は何か考えられますでしょうか。申し込み手続きはしやすかったのか尋ねました。","respondent":"金子保育課長","answer":"私どももできるだけ利用申し込みしやすいようにということで考えておりますが、それが最低要件としてありますが、今後とも受け付けの手続きについてはなるたけ利用しやすい方向で考えていきたいと考えています。","id":"exchange-001"},{"speaker":"藤原委員","kind":"質問","question":"この年末保育で、延長保育のニーズは希望の方からないのか尋ねました。","respondent":"金子保育課長","answer":"先ほども申し上げましたとおり、実施する時間は基本保育ということで、７時半から１８時３０分までとしております。実施の効率等々から考えまして、私どもとしましては現在のところは１８時３０分という基本保育の時間で対応したいと考えております。","id":"exchange-002"},{"speaker":"藤原委員","kind":"質問","question":"来年はまた曜日が変わると思うんですけれども、その辺の流れはどうか尋ねました。","respondent":"金子保育課長","answer":"来年度は２９、３０日がたしか月曜、火曜日に当たってくるかと思います。平日になりますので、また２９日、その辺に関しましては実施園等々についてまたあらためて検討したいと考えております。","id":"exchange-003"},{"speaker":"須藤委員","kind":"質問","question":"これの費用はどういうふうになるのでしょうか。保育をお願いする場合に費用はかかるんか尋ねました。","respondent":"金子保育課長","answer":"利用につきましては、１日当たり２０００円をいただいているところです。","id":"exchange-004"},{"speaker":"築舘委員","kind":"意見","question":"４カ月児から５歳児までということで、実質としてはどのぐらい何歳児が多いのかということ。この場合はどういうふうに、何も言わないでキャンセルの場合は料金を取るのかとか、その辺のことを聞かせてくださいとの意見を述べました。","respondent":"金子保育課長","answer":"４、５歳で１３０人ですので、大体そういう意味では各年齢にわたって満遍なくご利用されているということです。食材等々、私どもではすべて準備をするということからも、一たんお払いいただいた利用料についてはお戻ししないというふうな手続きとしております。","id":"exchange-005"},{"speaker":"宮崎委員","kind":"質問","question":"ちょっとわからないので伺いたいんですけれども、定員というのは何か考え方というのはあるのでしょうか。そちらのほうの体制を厚くするとか、そういう受け入れ態勢のほうはどういうふうになっているのか、そこのところを。","respondent":"金子保育課長","answer":"ご希望の方については、それを超えることはないと見込んでおりますので、特段定員については設定しておりません。先ほどちょっと申し上げましたとおり、その辺のところは特に問題ないということでご理解いただきたいと思います。","id":"exchange-006"},{"speaker":"金高委員","kind":"質問・要望","question":"２点だけお伺いします。実際に通園している方、新規にそのときだけ申し込まれる方の割合をちょっと教えていただきたいということと、その辺のところをお尋ねします。","respondent":"金子保育課長","answer":"一部、例えば従来認可外保育施設に預けている方等々の方をお預かりするというふうな格好になっております。私どもとしてはいろいろ要望をとる場合には当然回収率を上げたほうがいいわけですので、それについては努力したいと思っているところです。","id":"exchange-007"},{"speaker":"金高委員","kind":"質問・要望","question":"アンケートのほうはやはり今後のいろんな形での利用者の方々の意見ということですから。もしわかるところであれば、その辺のところを大ざっぱで結構ですけれども、大体の比率がわかりましたところで教えてほしいと求めました。","respondent":"金子保育課長","answer":"申しわけありませんが、詳細がちょっとないものですから、後ほどお知らせさせていただければと思います。","id":"exchange-008"},{"speaker":"辻副委員長","kind":"質問・要望","question":"策定するまでの間に何らかの形で注意したり意識してというのはあるのかどうかというのをちょっと聞かせていただきたい。我々なんかも水泳なんて子供のころだってキャップしていたけど、これはプールだからだと言われたら終わりだけど、いかがでしょう。","respondent":"田中健康課長","answer":"さっきの基本的な方針、高齢介護という問題が中心になってきたかと思うんですが、そこの整合性をという中身で考えてあります。それを一歩二歩突破できるようにということで今回は取り組ませていただいておるところです。","id":"exchange-009"},{"speaker":"辻副委員長","kind":"意見","question":"ただ、それがどう実践されるか。我々もさまざま研究し、先行事例というのも勉強した中でまた取り上げていきたいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-010"},{"speaker":"宮崎委員","kind":"質問・要望","question":"ちょっと伺いたいんですけど、きょう説明を受けたので、これはこれで今後いろいろ勉強させてほしいと求めました。ちょっと１点確認しておきたいんですけれども、それからこれが出てきて、相関がちょっとよくわからないんですけど。","respondent":"新美保健高齢事業部長","answer":"今年度末には介護保険事業計画を含めて、第二次の次ですから第三次ということになりますが、これを策定する予定です。お互い重なる部分はきちんと重なっているということをそれぞれの所管が自覚して連携をしていくという形で進めていきたいと考えています。","id":"exchange-011"},{"speaker":"宮崎委員","kind":"質問","question":"わかりました。そうすると４ページのところでは高齢者の健康づくりとなっていまして、このところが介護保険事業計画なんだというふうに理解すればいいんか尋ねました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-012"},{"speaker":"須藤委員","kind":"質問・要望","question":"実際的に区がある程度指導、区というか、その辺のところはどういうふうにお考えになっているのかなと。じゃあほんとうにこれ区としてはどういう絵をつくっていって、その辺のところをどういうふうにお考えか教えてほしいと求めました。","respondent":"田中健康課長","answer":"皆さんでいろいろ考えながら、考えていただきながら、こういうふうにしたらいいということを含めて立ち上げていきたいというふうに思ってあります。","id":"exchange-013"},{"speaker":"須藤委員","kind":"質問","question":"全体的な理想的な絵というのはいわゆる「健康プラン２１」とか、それはある程度行政の方々なり専門家の方々が全体を見て、こういう方針だよと。そしてむしろそれを地域の中で生かすためにはどういう手順があるんだろうかというような考え方もあろうかと思うんですけども、いかがか尋ねました。","respondent":"田中健康課長、新美保健高齢事業部長","answer":"そういうような考えの取り組みをお願いできれば、その部分について主体的、あるいは意見の一致を見て行動できるのかなというふうに思ってあります。いい悪いというか… ２つ目の課題の個人の特性に応じた生活習慣病予防のための支援で、システムをやっぱり充実していくというのがもう一つの方向性になろうかと思います。","id":"exchange-014"},{"speaker":"須藤委員","kind":"意見","question":"じゃあ何をやったらいいんだというのが町の人の声になっちゃうと思うんで、その辺のところをひとつこの次にも声として入れてほしいと求めました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-015"},{"speaker":"築舘委員","kind":"質問・要望","question":"「等」というとところにもちろん入っているんだとは思いますけれども、あらためて明示をしておいていただきたいというのが私の希望なんです。それからあと、それはちょっと除外をしておいたほうがいいのではないかという感じがちょっとしたものですから、その２点ちょっと説明を求めました。","respondent":"田中健康課長","answer":"皆さんのほうからここに参加しようと、いろいろ区のほうも先ほどのプランの乱立じゃありませんけども、そういう感じで入れさせていただいたものです。そういう意味では最終的な整理のところでご意見をまた整理をさせていただければというふうに考えてあります。","id":"exchange-016"},{"speaker":"築舘委員","kind":"意見","question":"それからプロジェクト２のところに、実際に保健婦が今までは地域に分かれていて、そしてそれぞれが張りつくと。それから母子、役割的には今後どういった役割を保健婦さんがしてくるかということを説明するよう求めました。","respondent":"田中健康課長","answer":"こういう表現にしていますが、非常に大きな役割を果たすということで、私どもの部内でも考えてあります。この辺のいわゆる動き方の体制も含めて今後いろいろモデル地区等のいわゆる立ち上げを含めて検討していきたいというふうに考えてあります。","id":"exchange-017"},{"speaker":"築舘委員","kind":"意見","question":"６５歳前、そのあたりが健康に関心を持ってくる年齢ではないかと思うんですよね。そしてむしろ前面に押し出していくということも必要かなと思うんですが、その点に関して説明を求めました。","respondent":"田中健康課長","answer":"４０歳以上の方ということでいいかなと思います。ただ、いろんな場面もありますので、今回あくまで一応老人保健法等にもあります４０歳以上の方を第１ターゲットにというのが今回の一番の眼目です。","id":"exchange-018"},{"speaker":"築舘委員","kind":"質問","question":"それなら成人というのは４０歳以上ということで規定していいわけですか。それならわかるんですけど、成人というと２０歳以上という感覚を持っていたものですから、それならいいことだと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-019"},{"speaker":"宮崎委員","kind":"確認","question":"今、藤原委員のほうで聞いたので私ちょっとメモしきれなかったんですけど、昨年が申し込み２１５件で、入居された方が１４人と。同じような件数だったかなと思うんですけれども、ちょっと件数を確認したいんですけれども。","respondent":"蓼沼高齢事業課長","answer":"今のところ１４人が入居済み、あるいは近々入居という予定です。年度末につきましては、大体１５人から２０人の間の入居見込みです。","id":"exchange-020"},{"speaker":"宮崎委員","kind":"意見","question":"４０番ぐらいだったんですよね。そういうふうに私思うんですけど、ここら辺のところを区のほうはどんなふうにお考えなのか、お聞かせほしいと求めました。","respondent":"蓼沼高齢事業課長","answer":"大体の年間の入居者数１５から２０人の中では一定程度困窮度の高い方については対応ができているというふうに考えてあります。その間に住宅の斡旋制度等も活用しながら困窮度の高い方については対応を図っているというような状況です。","id":"exchange-021"},{"speaker":"宮崎委員","kind":"質問・要望","question":"住宅マスタープランのところにも計画はありませんけれども、ぜひ私は増設というところで考えていただきたいということを要望しておきたいと思います。ですから応募資格のところももうちょっといろいろ考えて、なるべく品川に住めるというところで再度増設のほうをお願いしておきたいと思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-022"},{"speaker":"山路委員","kind":"質問・要望","question":"応募資格の中での、表面には書いてありませんけど、大家さんの発言といいますか、これ調査の中で大家さんがいろいろああだこうだということで入居している方の説明を書いてくれますけど、それはどこまで非常に影響力があるのか、その辺についてちょっとお知らせしてほしいと求めました。","respondent":"蓼沼高齢事業課長","answer":"そのあたりにつきましては、客観的な事情についてご記入をしていただいておりますので、公正に取り扱いをしています。","id":"exchange-023"},{"speaker":"山路委員","kind":"質問","question":"電気を消して買い物にも行けないぐらい真っ暗だという苦情、相談を受けているんですけど、その辺は情報は入っていますか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"具体的に何かそういうことがあれば、家主さんを通じてご報告いただければ、こちらのほうでしかるべき対応をしていきたいというふうに思います。","id":"exchange-024"},{"speaker":"須藤委員","kind":"質問","question":"先ほど言った年間入居するのが１５人から２０人ですよというお話をいただいたんだけども、こういう２番目の条件で立ち退き要求というのはだんだん少なくなってきているんだろうと思うんだけども、この辺の傾向はいかがか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"平成１０年度につきましては、１１.５％ということで、少しまた若干高くなりました。平成１２年度６.２％というように、１０年度一時高くなりましたけれども、その後はまた低く推移しているという状況です。","id":"exchange-025"},{"speaker":"須藤委員","kind":"質問","question":"その辺のところで緊急にというようないろんなお考えがあると思うんだけども、そういう考え方は全然持たないですか。高齢者住宅というところでそういう人たちに対しての対応というのは考えていきますか。","respondent":"蓼沼高齢事業課長","answer":"一定程度また年間を通じての登録で空き室待ちですので、一定程度例えば随時な対応ということでいえば住宅の斡旋制度というものがあります。そういった斡旋制度等の活用によってそういうケースにおいてもなるべく対応していきたいというふうに考えてあります。","id":"exchange-026"},{"speaker":"須藤委員","kind":"質問","question":"ですから逆に今言ったように、なかなかそういうところは見つかってこないよというのが現状だろうと思うんですよ。これがパーセンテージが２％ぐらいあるとなかなか数的にも大変だと思うんだけども、そういう質問をしていますけど、いかがか尋ねました。","respondent":"新美保健高齢事業部長","answer":"そういう意味ではとりあえず今の２０戸程度、年間２０人程度の新規入居で、その緊急性の高い方については対応ができているというのが現状です。現状では緊急ケースにはとりあえず住宅で対応ができているです。","id":"exchange-027"},{"speaker":"金高委員","kind":"質問","question":"１点だけお伺いいたします。それから実際に入っている方の年金を受け取る月額というんですか、生活が非常に厳しくなってくるような面もあるんじゃないかと思うんですが。","respondent":"蓼沼高齢事業課長","answer":"３万５,０００円というのが一番低い層なわけですけれども、３万５,０００円という家賃の方がほとんどということです。ですから所得状況を詳しくは今把握しておりませんけれども、ほとんど非課税、あるいはそれに近い方かなというふうに考えております。","id":"exchange-028"},{"speaker":"辻副委員長","kind":"質問","question":"そういうケースというのはないんですか。立ち退き要求だけを受けているということをここまで明確にしてしまうとちょっとおかしくなるのかなと思うんですが、いかがか尋ねました。","respondent":"新美保健高齢事業部長","answer":"先ほどもちょっとお話しさせていただいたんですが、立ち退き要求にも取り壊し立ち退きと、単なる立ち退きの理由に二分できます。６カ月以内なのか、個別にご相談しながら入居対応をしておりますので、私が承知している範囲では大きな問題になったケースはないところです。","id":"exchange-029"},{"speaker":"辻副委員長","kind":"質問・要望","question":"きょうは入居者の募集なんですから、その辺のことを何とか検討してというか、大きい課題として研究していただければなと考えています。要望だけです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-030"},{"speaker":"築舘委員","kind":"質問・要望","question":"応募が２１５人あって、それで登録が４２人ということで、主なものを挙げてほしいと求めました。","respondent":"蓼沼高齢事業課長","answer":"それと途中で辞退されたり、あるいは転出したりということで、数の減少もありますので、そういった意味も含めて４０人ということで抑えております。","id":"exchange-031"},{"speaker":"築舘委員","kind":"質問","question":"ある程度順番をつけて、そして４２人なら４２人、要するに入れる可能性があるという部分で予備も含めて取っているということでよろしいですか。緊急度が高いということになれば、そこで次にはまた登録される可能性がずっと続いているということで解釈してよろしいか尋ねました。","respondent":"蓼沼高齢事業課長","answer":"この登録の期間は１年間でございまして、またその１年が経過した時点であらためてまた応募をしていただいて、やはり審査の上緊急度の高い方から登録をしていくということになります。","id":"exchange-032"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/534819?Template=document&Id=3038#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=7&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":33383,"voices":94}},{"id":"h14-20021126-8","meetingId":"h14-cm11","date":"2002年11月26日","dateIso":"2002-11-26","committee":"建設委員会","time":"午前１０時１１分～午後２時３６分","status":"正式会議録","sourceType":"formal","overview":"建設委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を37件整理しています。","topics":[{"id":"topic-01","title":"１の報告事項","agenda":"１の報告事項","exchanges":[{"speaker":"船波委員","kind":"質問","question":"そもそもこの汚染されているということが発見されるきっかけになった香料瓶が発見されたというのは、どうしてなんでしょうか。その後詳細調査して発見されたのか、あるいは工事のしている最中にたまたま発見されたということなんか尋ねました。","respondent":"岩田管理工事課長","answer":"ところが９月の半ばごろ、それの移設工事を行っていたときに、木の周りの土を掘ったときに瓶が大量に発見された。強い香りが周りに漂ったということで、これは何だろうということで騒ぎになったといいますか、問題が発見されたです。","id":"exchange-001"},{"speaker":"船波委員","kind":"質問","question":"疑問が生じてきてしまうので、不安が残ってしまうんですけれども、そういった懸念を持っていないのかどうかということをちょっとお伺いしたいと思います。","respondent":"岩田管理工事課長","answer":"３,０００平米以上の土地の区画形質の変更、建築行為とか、その土地の履歴調査をして東京都に届け出るということになってあります。いわゆる土地区画形質の変更が今後伴う直前に、民間であろうが官庁であろうが、一応ルールになってあります。","id":"exchange-002"},{"speaker":"船波委員","kind":"質問","question":"ですから、今後はそれは搬出してしまうからいいのかもしれませんけれども、今までには何らかの影響を及ぼしてしまってはいないのかどうか。そういったことは何か調査されたものはあるんか尋ねました。","respondent":"岩田管理工事課長","answer":"この経過から見る限り、表層部分にあったと、公園時代からあったということは言わざるを得ないというふうに思います。専門の職員に聞きますと、この程度の含有値であれば、大量に食べない限り人体に影響があるようなものではないというような言い方はされておりました。","id":"exchange-003"},{"speaker":"飯沼委員","kind":"質問","question":"業者は専門の業者が行うのでしょうか。その辺をちょっとお伺いしたいのと、主に総水銀と鉛ということですけれども、この辺の基準値を教えていただけたらと思いますけれども。","respondent":"岩田管理工事課長","answer":"この昭和５２年ごろといえども、そういったものも地中に放置するということは、まず考えられない。３ページ、４ページのこの結果の左側のところ、これを上回った場合に何らかの対策をとりなさいということになってあります。","id":"exchange-004"},{"speaker":"飯沼委員","kind":"質問・要望","question":"それが原因で土壌汚染をしていたかどうかというのは明らかではないということも含めて伺った、やはり何が原因か、問題が多いと思うんですね。私有地ですからどうなのかと思うんですが、そこが１点心配なのと、その点２点お伺いします。","respondent":"岩田管理工事課長","answer":"特に北側の方は今改築工事をやっておられますので、こういうことがありましたと、こういうふうに処理をしますということは説明をする予定です。それも地上から非常に浅い部分だけに幸いなことにとどまっているということで、非常に簡易な処置で、この場合は済むです。","id":"exchange-005"},{"speaker":"飯沼委員","kind":"質問","question":"その辺が１点と、きちんとしてほしいのと、やはりその中身自体をどういうふうに広報されるのかというところをお話しいただけますか尋ねました。","respondent":"岩田管理工事課長","answer":"近隣の方々への説明も、町会長と、直近の土地の面している方ぐらいにはちゃんと説明をする必要があるかなというふうには考えております。","id":"exchange-006"},{"speaker":"飯沼委員","kind":"質問・要望","question":"一つは区の区有地、区の財産の場所をきちんと責任を持って処理をしたということを、ぜひ私は広報して安心させてほしいなと思うのが１点です。最終処分場に送られて、これはどういうふうな状況になるのか、処分場がどういうようなところを最後に教えてほしいと求めました。","respondent":"岩田管理工事課長","answer":"物によっては密閉保存、コンクリート等にドラム缶にそういう汚染土をコンクリートで固めて処分をするという方法もあるようです。いわゆる将来溶け出さない、それからほかの物質に結合しない、これはそれぞれの専門の化学者に任せてやっていきたいと考えています。","id":"exchange-007"},{"speaker":"田中委員","kind":"質問・要望","question":"専門ではない方にお伺いするのもちょっと失礼かもしれないんですけれども、自然界においての状態がどういう状態なのか、この数字と比べてどうなのかというところをまずお聞かせをほしいと求めました。","respondent":"岩田管理工事課長","answer":"ですから、ほとんどの部分は通常の残土として処分をしていい土ということになります。一般的にこういった土壌調査の基準値というのはかなり厳しく見て、安全側にとっている値だろうというふうに思われます。","id":"exchange-008"},{"speaker":"田中委員","kind":"質問","question":"お伺いしたい点というのは、その一番土壌汚染があったこの赤い部分に２,６００本余りの香料瓶が発見されたというんですが、これを埋めた時期というのはいつだったのかというのをお尋ねします。","respondent":"岩田管理工事課長","answer":"ただ、なぜ重金属が出ているのかというのは、日本たばこ産業の学者のほうでもよくわからないと。あくまで推測はできるし、品川区には迷惑をかけられないので処理をさせていただきたいという、こういうふうに今のところはなっております。","id":"exchange-009"},{"speaker":"田中委員","kind":"質問・要望","question":"当時専売公社というんですか、たまたま偶然で香料瓶が２,６００本、おそらく１００％つながりがあるだろうと。行政側としては強く申し入れるべきだと考えていますので、これは要望になりますが、そういう強い申し入れをしていただきたいと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-010"},{"speaker":"菊地委員","kind":"質問","question":"相当履歴をさかのぼって調べないと、その辺の考え方として、これから切りかえていくようなところというのはあるんでしょうか。そこをお聞きしたいのと、逆に言うと、空地になっている部分での調査というのは考えていないんか尋ねました。","respondent":"岩田管理工事課長","answer":"その中では、いわゆる３,０００平米以上の区画形質の変更をする場合に、まず土地の履歴調査をします。一般的に第三者から土地を購入した場合に今後どう対応するのかということですけれども、調査が必要と考えればきちっと調査をする。","id":"exchange-011"},{"speaker":"菊地委員","kind":"質問","question":"当然。要するに日本たばこ産業から買い受けた土地全体を現状ででき得るすべての調査を行うべきだと思いますけれども、その辺はどうか尋ねました。","respondent":"岩田管理工事課長","answer":"要するに、もうあらかたどこかへ行っちゃっている可能性が残念ながらあるということですね。ただ、条例上は、将来建てかえるときにはもう一度調査ということはあり得る可能性はあります。","id":"exchange-012"},{"speaker":"堺委員","kind":"質問・要望","question":"２点だけちょっと確認で教えていただきたい。最低町会長とここに書いてある人ぐらいには説明する必要はあるのかなというふうな気はしますけれども、その辺はどうなんか尋ねました。","respondent":"岩田管理工事課長","answer":"近隣への説明ですけれども、そういったことはまず考えられませんので、ご心配なさる必要がないと思います。私ども説明を上手にするんですけれども、技術屋もいますので、一般の方にわかりやすいような表現できちっと説明をしていきたいと考えています。","id":"exchange-013"},{"speaker":"堺委員","kind":"質問","question":"だから、きちっとしかるべき人がしかるべきところについては、きちっと説明しておかなきゃいけないというふうに思うんですね。せめてここに出ている人あたりぐらいには、やっぱりきちっと説明をしておいたほうがいいというふうに思いますけれども、これはいかがか尋ねました。","respondent":"岩田管理工事課長","answer":"まずは町会長に一刻も早くご説明して、どの程度の方にご説明すればいいか、一応お諮りをして対応したいと思います。","id":"exchange-014"},{"speaker":"菊地委員","kind":"質問","question":"今年の夏ですか、どういう形でどのくらいの時間帯で排水させていくことができるのかというのを、ちょっとそこだけお聞かせ願えますか。","respondent":"矢部下水道河川課長","answer":"それで、大体排水時間が２４時間程度、満管になった状態で排水しますと２４時間程度かかるかなと。逆に言いますと、あまり下流に影響を及ぼさないように徐々に排水していくという形になると思います。","id":"exchange-015"},{"speaker":"菊地委員","kind":"意見","question":"たまたま土日で弁を開かなかったという話がありましたが、今回の場合は２４時間かかるんですけれども、その辺の対策というのはどういう形になるか。ちょっとそこだけとの意見を述べました。","respondent":"矢部下水道河川課長","answer":"本来でしたら西品川、今は自動排水システムになってございませんが、今年度末までに自動排水システムにする予定にしております。西品川に関しましては今後ずっと継続して使っていくということで、そこまでシステム的につけなくても対応できるんではないかというふうに考えて。","id":"exchange-016"},{"speaker":"菊地委員","kind":"意見","question":"暫定的な２年間という、ただ現実の問題として、自動的にしないということであれば、同様の事態が起こる可能性というのは残るわけですよね。土日に入ったときの体制というのは考慮できるような体制づくりというのか、その辺をちょっともう一度考えていただければなと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-017"},{"speaker":"菊地委員","kind":"質問","question":"目黒川の河口で放水できるような、要はどうして目黒川の河口で放出ができるような体制にしないのかというのがちょっとよくわからないんですけれども。あそことのちょっと関係もできましたら教えていただければ。","respondent":"矢部下水道河川課長","answer":"それをまた流域を変更して別の流域にというのは一つ難しい問題があるのと、河川にしても運河にしても、放流量というのは決まっております。","id":"exchange-018"},{"speaker":"田中委員","kind":"意見","question":"旧ルートにして２本にしたというルートだったというふうに、要は最初から１本の管にして、環境の変化があったのかどうか。当初なぜ旧ルートだったのか、その辺をお聞かせいただけますかとの意見を述べました。","respondent":"矢部下水道河川課長","answer":"地上部分のところを左側に曲がって、鮫洲ポンプ所のほうに行く、こういうルートを当初考えていたです。建設局、縦断占用につきましてもある程度柔軟な対応が可能になってきた、そういう背景の中で工期短縮という話が出てきたというふうに聞いております。","id":"exchange-019"},{"speaker":"林（和）副委員長","kind":"質問","question":"１点だけ。今の田中委員と大体同じことをお聞きしたかったんですけれども、この変更することによって、どういうふうに変わってくるのか。","respondent":"矢部下水道河川課長","answer":"そういうことで、別々の管にしますと、大体勝島ポンプ所の本体工事にかかれるのが平成１８年度ぐらいになってしまうという話です。それが平成１６年度、２年ぐらい短縮されて工事に着手できる見込みがあるということで、工期短縮が図れるという内容です。","id":"exchange-020"},{"speaker":"林（和）副委員長","kind":"質問","question":"ちょっと教えてもらいたいんだけれども、この小田急線の立体交差化に伴って、品川区の東大井四丁目が対象だということですかね。ちょっともう少しよく。","respondent":"伊佐都市計画課長","answer":"同様の案件が放射１９号で大鳥居のところの立体交差が１年ほど前にございまして、第一京浜国道の車線数を６車線に定める都市計画変更をしています。こういったことで、今後の都市計画変更に合わせて車線変更を決めていくということになっております。","id":"exchange-021"},{"speaker":"船波委員","kind":"意見","question":"今回こういう２車線に決めるということですけれども、この起点から終点の何キロかの間、２車線に既になっているのか。この決まりで２車線にすると決まったことによって、２車線以外の車線数だったけれども２車線に人為的に直さなきゃいけないとか、そういうことはとの意見を述べました。","respondent":"伊佐都市計画課長","answer":"多少その部分だけは歩道を、少しの間狭くするとか、そういう対応であれば、部分的には４車線とかとれるのも可能です。一応標準的な車線数としては２車線、都市計画上の標準としては２車線ということでやっていく方針です。","id":"exchange-022"},{"speaker":"船波委員","kind":"質問","question":"計画をしているということですけれども、もう既に多少なりともできている部分ではどうなんでしょうか。決まったから物理的にそういった現状を変えなくてはいけないというようなところはあるんか尋ねました。","respondent":"伊佐都市計画課長","answer":"今現状例えばそういった車線等を運用しているところを２車線に戻さないといけないというものではなくて、この部分は２車線で流すような計画を道路ネットワークの配置をするという理論上の車線数ですので、現場現場で柔軟な運用というのがなされるという現状です。","id":"exchange-023"},{"speaker":"船波委員","kind":"質問","question":"もう１回お伺いしたいことが何点かあるので、あと、区としては１.２倍までの中でやるというお考えだということだったんでしょうか。それから、この赤で囲んだ地域が適用対象外になるというのは、もう決定されてしまったということか尋ねました。","respondent":"山室住宅指導担当部長","answer":"それから、もう少しちょっと具体的にご説明すればよかったんですが、その１.０から１.５倍の中で任意に定めることができるわけですね。ちょっとこれは説明を先ほどしなくて申しわけなかったんですが、１.２の指定を受けたとしても、それ以下になる。","id":"exchange-024"},{"speaker":"船波委員","kind":"質問・要望","question":"今は、区としてこういうふうに決めてほしいということを決めるプロセスはどのようになっているんでしょうか。議会だとか委員会とか、今ご説明いただいた区の決定してほしいという方針を決まるまでのプロセスをちょっと教えてほしいと求めました。","respondent":"山室住宅指導担当部長","answer":"明日また街づくり特別委員会でも同様にご説明していきたいというふうに考えております。そういった一連の手続を踏まえた上で、通常の区長決定をして、都のほうに知事あてに回答していきたいというふうに考えております。","id":"exchange-025"},{"speaker":"船波委員","kind":"質問","question":"どういうことを議題にするかとか、そういったプロセスを経て決めていく、そういうことはできないんか尋ねました。","respondent":"山室住宅指導担当部長","answer":"各委員会等のご意見も踏まえて整理していく必要があるというふうに考えておりまして、今回建築基準法の改正の中でのご説明になったわけですけれども、その上で区としての決定をとっていけないかなというふうに考えております。","id":"exchange-026"},{"speaker":"船波委員","kind":"質問","question":"もちろん地区計画を定めればできるわけですから、やはりこの５４条７項を適用するというのは大きな問題ですから。地域計画、つまり地域の方を含めた場を経て、この街の中にどんな建物ができるかということを決めていくというプロセスになっていくわけですから。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-027"},{"speaker":"菊地委員","kind":"質問・要望","question":"昨日の続きの質問みたいになっちゃいますけれども、今そういう許可申請を出している建築物はどの程度あるのかというのを教えていただきたいのと。要はどういう形でこれがはかられるのかというご説明を願えればと思います。","respondent":"山室住宅指導担当部長","answer":"ちょっと説明しにくいんですが、具体的に言うと、建築面積を少し細めるようなものですね。ちょっと説明が十分じゃないかもしれませんが、天空率の導入というのは、そういう仕組みです。","id":"exchange-028"},{"speaker":"菊地委員","kind":"質問・要望","question":"それが今の数なんでしょうか。全体の数を教えていただきたいんですけれども。","respondent":"山室住宅指導担当部長","answer":"後ほどお答えしたいと思いますが、くどいですけれども、区がまず持っている総合設計制度で許可したものは１件です。先ほどちょっと今調べていますと申し上げました、都に係る総合設計制度は平成１３年度で３件、それから平成１４年度で４件だということです。","id":"exchange-029"},{"speaker":"菊地委員","kind":"質問","question":"空地ができて、そこなんかは周りが２階建てから３階建てぐらいの家が多いところにぽこっとあれだけ巨大な建築物ができていくわけですよね。その辺の経過というのが除外されてしまうような部分というのが生まれてこないのかどうかというところをちょっとお聞かせ願えますか。","respondent":"山室住宅指導担当部長","answer":"先ほどご説明したとおり、総合設計に出せませんので、認定をやって終わらせてから総合設計をやる。だから、この中では１の中で並行してやっていこうということですから、総合設計制度そのものの手続を簡略化しようとするものではありません。","id":"exchange-030"},{"speaker":"飯沼委員","kind":"質問","question":"線路に近い三角の小さいところで１軒残ったほかは、何か図面ではよくわからなかったんですけれども、どういうふうになるんでしょうか。何かいろいろ階段みたいに白く塗ってあるのは何か尋ねました。","respondent":"浜脇住環境整備課長","answer":"これが４ｍ道路でございまして、ちょうど途中までは車で来れるんですが、そこから先は自転車。青いところは、とりあえず貫通通路を使っていただくということで話し合いが進んでいるということで、あの青い道路が貫通通路となっております。","id":"exchange-031"},{"speaker":"飯沼委員","kind":"質問","question":"今までに品川区内でこういう事業がどれくらいあったのかということと、あとこれをコーディネーターしている人はどこなのか。区内の事例も今までのそういうコーディネーターがわかったら教えていただけますか。","respondent":"浜脇住環境整備課長","answer":"今回のこの西五反田１－７につきましての地元の方々のお世話をしたのはマツオ設計(株)という方と、私ども地元というふうに伺ってあります。品川区に会社はあるというふうに伺ってあります。","id":"exchange-032"},{"speaker":"飯沼委員","kind":"質問・要望","question":"さっき一緒に聞けばよかったんですけれども、あと１ページ目の下に近隣説明会開催とありますが、これはもう済んでいるんでしょうか。済んでいたらば、この中でのご意見を幾つかお聞かせほしいと求めました。","respondent":"浜脇住環境整備課長","answer":"それから、近隣説明会ですけれども、もう終わってあります。この施設に関する変更といいますか、運行について、今後とも協議してくれという声が多かったというふうに伺っております。","id":"exchange-033"},{"speaker":"飯沼委員","kind":"質問","question":"３ページ目に構想図があるんですけれども、住宅がほとんどですよね。地権者の方がどれくらいを占めているのか、あと保留床がどのくらいあるのか、あと分譲と賃貸の割合もちょっと教えてほしいんですが。","respondent":"浜脇住環境整備課長","answer":"そのうちの１６が住宅。店舗が２０戸、それから６階から上がいわば分譲するというもので、床面積はちょっと載ってございません。","id":"exchange-034"},{"speaker":"飯沼委員","kind":"質問","question":"最後に。分譲のところのめどというのは、方向性としては立っているんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"２ページ目の４番で建築工事というのがありますが、平成１６年１１月に完成するというので、販売の委託を受けている会社が決まってあります。それは、ですから、その前後にきちっとチラシなり何なり配る、あるいは新聞広告に入れてやっていただくというふうに思ってあります。","id":"exchange-035"},{"speaker":"田中委員","kind":"質問","question":"ちょっと言葉を選んで質問したいと思うんですが、あの１軒がもしあれば、さらにどれぐらいの住宅が供給できたと思われるんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"少しそういうのが残るという程度で、あの方が入ってもそれほど、若干はないわけではないです。私どもも最初は１１月に来たころは、何年かたちますと、今回年末年始の営業が終わったところで事業を開始したいというのがこの方々の総意です。","id":"exchange-036"},{"speaker":"田中委員","kind":"質問・要望","question":"地元の説明会の地域の方のご要望は、そういう声があったかどうかちょっとあれなんですが、いかがなんか尋ねました。","respondent":"浜脇住環境整備課長","answer":"お話といいますか、指導といいますか、してみます。","id":"exchange-037"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/807981?Template=document&Id=3742#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=8&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":54685,"voices":103}},{"id":"h14-20021126-9","meetingId":"h14-cm11","date":"2002年11月26日","dateIso":"2002-11-26","committee":"文教委員会","time":"午前１０時０５分～午後１時２５分","status":"正式会議録","sourceType":"formal","overview":"文教委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を12件整理しています。","topics":[{"id":"topic-01","title":"委員会での質疑","agenda":"委員会での質疑","exchanges":[{"speaker":"沢田委員","kind":"質問","question":"どう見たらいいか、これだけでは容易にわからない面があると思うのですけれども、住民基本台帳上による予定数から増減を引いたものを引くということが、今予定されている来年の学級数という考えでよろしいのか尋ねました。","respondent":"谷田部学務課長","answer":"それから希望申請のほかに指定校を変更されて、教育的な配慮というようなことで、今後は指定校変更という制度が出てまいります。減で、それが４月の入学者になるかといった場合には、それまでの間にいろいろな変更の手続等がありますので動きます。","id":"exchange-001"},{"speaker":"沢田委員","kind":"意見","question":"ここらの数字はどう見ているのかということと、最終的にはどれぐらいになる見込みになるのかということはとても出せないような状況なのかどうか、ちょっと感触でもご答弁いただくとありがたいのですがとの意見を述べました。","respondent":"谷田部学務課長","answer":"増が８ということで、他の学区域のほうから来ているというのは、多少の小中一貫校に対する影響がここに出ているのかなというふうに感じております。","id":"exchange-002"},{"speaker":"原委員","kind":"質問・要望","question":"ちょっと１点だけ確認をさせていただきたいのですけれども、各ブロック内の小学校の中での行き来についてはデータがとられていますよね。各年度はどうなのでしょう。","respondent":"谷田部学務課長","answer":"ブロックの中の動きですから、私ども事務作業をする上ではそういったもの、データとしてはあるのですが、これはあくまでも事務作業をする上でのデータですので、公開はしていない部分です。","id":"exchange-003"},{"speaker":"原委員","kind":"意見","question":"そういう傾向はつかんでいらっしゃるのかどうなのかということです。各ブロック内でのそういう部分を扱うという中で、集中的なところが起きているのかどうかということをちょっと知りたいのですけれどもとの意見を述べました。","respondent":"谷田部学務課長","answer":"要は６０人、７０人近い方が希望されていますけれども、同じブロックの他の学校へ行かれる方も何人かはいらっしゃる。同じブロックで、原小学校が減の数が２０人、増が出てきているというようなことも１つの傾向と言えるかなというように思ってあります。","id":"exchange-004"},{"speaker":"原委員","kind":"質問","question":"そうすると同じグループの中で、そういう集中化というのがどういう形で行われてきているのかなというのは非常に興味があるところなのです。各ブロックでそういう集中化というのはどうなのかなと、その辺つかんでいただけているのかなどうなのかなというところの質問なのですけれども。","respondent":"指田教育次長","answer":"これは学校が努力しても努力してもなかなか、打消しがなかなかできない部分であろうかなという気持ちは、正直言って持っています。","id":"exchange-005"},{"speaker":"原委員","kind":"意見","question":"それのところの持っていき方ではないかなと思うので、今後の中でひとつご努力ほしいと求めました。以上ですとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-006"},{"speaker":"沢田委員","kind":"質問","question":"指定校を自由に受け入れたら、ある意味ではガチャガチャになっちゃうということがあるのではないかと思います。ちょっと指定校変更とはどういうものなのかというのを教えてもらえるとありがたいのですが。","respondent":"谷田部学務課長","answer":"指定校変更でブロックを越えての指定がどの程度変更届が出てくるか、ことし新１年生になりましたお子さんの指定校変更、トータルで１８１件あります。","id":"exchange-007"},{"speaker":"沢田委員","kind":"質問","question":"原則的にはそれが出されれば全部受け入れるという方針なのかどうなのかということと、去年１８１件の指定校変更がされたのだけれども、ちょっとそこらを教えてほしいのですけれども。","respondent":"谷田部学務課長","answer":"指定校変更、今後ブロックを越えての指定校変更手続が出てまいりますけれども、大きな要因になろうかと思います。転居予定が見込まれるですとか、家庭環境、なるべく希望に沿うような形では指定校変更はしていきたいというふうには思ってあります。","id":"exchange-008"},{"speaker":"沢田委員","kind":"質問","question":"大体希望は、１００％今年度まではいったということか尋ねました。","respondent":"谷田部学務課長","answer":"１００％といえば、書類上すべて見て１００％にしているのか、単純にＡ小学校がいいんだということでＡ小学校がだめになったというのではない。ですから、そういう意味では、いろいろご相談をしながら、保護者も納得した上で指定校変更しているという意味では１００％だです。","id":"exchange-009"},{"speaker":"石田委員","kind":"質問","question":"１点だけお聞きをしたいのですが、先ほども指定校変更１８１人あるというのは、これもやはり風評というか、元来ある学校の伝統というか、そこへ集中する傾向が強いのか尋ねました。","respondent":"谷田部学務課長","answer":"要は、先ほども言いました指定校変更の制度、指定校を変えるというのはいろいろな事情があります。指定校変更というのはさまざまな理由・原因によって学校を変えるという手続ですから、どこに集中しているというのは特段ございません。","id":"exchange-010"},{"speaker":"石田委員","kind":"質問・要望","question":"指定校変更で１２６人が１４０人になっているのだけれども、これも５６人が７３人で、多分私立行く人がいれば相当指定校変更があったのかなという。大間窪小学校が伝統なのかどうかわからないけれども、どういうふうに判断されているのかなというようなところがあれば、教えていただきたい。","respondent":"谷田部学務課長","answer":"大間窪小学校を経て、いわゆる小学校、中学校の連携教育をやっている大間窪小学校から入れればいいなというような声は聞いたことがあります。","id":"exchange-011"},{"speaker":"石田委員","kind":"意見","question":"ここら辺のところも委員会でもし対応できれば、ぜひそこへも行ってみたいなというところもありますので、お願いしますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-012"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/547087?Template=document&Id=4458#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=9&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":13288,"voices":49}},{"id":"h14-20021126-5","meetingId":"h14-cm11","date":"2002年11月26日","dateIso":"2002-11-26","committee":"総務委員会","time":"午前10時07分～午後２時５７分","status":"正式会議録","sourceType":"formal","overview":"総務委員会の会議録から、実質的な質問・確認・意見・要望と答弁・対応を79件整理しています。","topics":[{"id":"topic-01","title":"平成１４年請願第２９号「業者婦人の地位向上に関する請願」","agenda":"平成１４年請願第２９号「業者婦人の地位向上に関する請願」","exchanges":[{"speaker":"桜井委員","kind":"質問・要望","question":"どういうふうな改善すべき点があるのか、どういうふうにこの問題を、女性という視点からとらえているのか。以上、ちょっと主な点だけの品川区の女性の実態というものを教えてほしいと求めました。","respondent":"阿部人権啓発課長","answer":"今年につきましては３２％ということで、若干ではありますけれども、４０％を目指して進んでいるというふうになっております。これは委員ご存じのとおり、雇用機会均等法とか、そういうもので徐々に改正されつつあるのではないかというふうに思っています。","id":"exchange-001"},{"speaker":"桜井委員","kind":"質問・要望","question":"自家労賃のこともありますけれども、どういうふうに自治体はとらえているのかというのをお聞きしたいと思うんですけれども、もう少し明確にしっかり。改めて、もう少していねいにご紹介ほしいと求めました。","respondent":"阿部人権啓発課長","answer":"１点目の賃金ですけれども、拡大しているという認識ではなくて、拡大しているというのは特に認識していないということだと思います。この行動計画を進める上で、取り組んでいきます。","id":"exchange-002"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、それは誤解をしないように。私は見続けるべきではないかというふうに思うんですけれども、課題の中についてもう少し、お尋ねしたいと思うんです。","respondent":"阿部人権啓発課長","answer":"この行動計画ですけれども、確かに委員の言われる業者婦人の方の具体的な取り組みではございません。目黒区でつくっている条例を具体的に進めていく上で、その第三者機関であるオンブーズというのを設置して、あるいは処理に当たっているです。","id":"exchange-003"},{"speaker":"桜井委員","kind":"質問・要望","question":"２３区の中で、ほかに制定されているところがあればご紹介いただきたいのと、それがどういうふうにつかんでいるかをお聞きしたいと思います。","respondent":"本間総務部長","answer":"２３区でも他にない、先ほど来課長が説明しています第３次行動計画、品川プランをつくってあります。その辺の進捗状況等を考え、早期に条例を制定という考えは、品川区では持っていないです。","id":"exchange-004"},{"speaker":"桜井委員","kind":"質問・要望","question":"私は質問したことがあるんですけれども、また一方で事実ですから、私は今後の目標としては十分に検討すべき課題だというふうに認識しているわけです。皆さんたちがさらに論議を深めて、そういう方向を打ち出すべきだというふうに、これは要望しておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-005"},{"speaker":"嶋委員","kind":"質問・要望","question":"そういう起業家のアンケートをやったときに、参加した方たちの意見の中に、こういう問題はどのようにあらわれているのか。もし出ていましたら教えてほしいと求めました。","respondent":"阿部人権啓発課長","answer":"躊躇されることはあるというのは、起業家入門講座、あるいは起業家フォーラムの中で聞いてあります。ですから、そういう情報も聞いて、それに対してアドバイスを受けるという意味で、起業家フォーラムを開催しています。","id":"exchange-006"},{"speaker":"嶋委員","kind":"質問・要望","question":"ですから、私自身も、もっと幅広く伝えてもらいたいというのがあるんですね。そういう方たちの意見を、もし商店街とかおかみさんの会とかいうのがあれば、ぜひお聞かせほしいと求めました。","respondent":"本間総務部長","answer":"確かに、経済状況、社会状況、厳しいものがあります。私も実際にそういう場面に出まして、そういう意味で、非常に心強く思っているです。","id":"exchange-007"},{"speaker":"嶋委員","kind":"質問・要望","question":"品川区の状況をお聞きしますと、今のところお聞きしていないので、品川区はそんなに冷たいのではないなと考えています。品川区もますます、品川区としては第三次長期基本計画の中にしっかりと盛り込んでおりますので、これを機に確実に推進してほしいと求めました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-008"},{"speaker":"土井委員","kind":"質問・要望","question":"このことは大変重要なことだと思うし、これを推進していくことに力を注ぐべきだろうと、このように思っています。こういう体制でやっていっていただきたいという思いをしながら、意見としてですけれども、申し上げておきたいというふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-009"},{"speaker":"林（宏）委員","kind":"意見","question":"セクハラとか、そういう差別を議論するときに、必ず出てくるのが言葉だと思うんです。活字にするのを控えているとか、そういうようなところの動きの部分で、この婦人という言葉をちょっと解説してくれますかとの意見を述べました。","respondent":"本間総務部長","answer":"最初に、第１次行動計画のときには、婦人という言葉を使っておりました。働いている女性の方というような意味で取っておりましたが、この固有名詞そのものは、私どももこの請願で初めて聞いたという状況です。","id":"exchange-010"},{"speaker":"林（宏）委員","kind":"質問","question":"この婦人の婦というのは、今ご説明があったように、女偏に帚と書く。もう使わないほうがいいですよという流れになっているんですか、この字というか、婦人という言葉は。","respondent":"本間総務部長","answer":"第１次では使っておりまして、要するに、端的に言えば婦人という言葉は使わせていただいておりません。","id":"exchange-011"},{"speaker":"林（宏）委員","kind":"意見","question":"やっていたら聞かせてほしいと思うし、少子化対策のほうで、結婚を望むような社会になっていってほしいと思うんです。必要なのかどうか、男性のことも必要なんじゃないのかなという気がしているんだけど、もし何かあったら聞かせてくださいとの意見を述べました。","respondent":"本間総務部長","answer":"やはり、長い歴史的な経緯の中で、女性がある時代、弱い立場に置かれていたことが、日本の制度上もございました。よく男女共同参画社会を考えると、男性の参加もできるだけしていただくような、そういう配慮をしながら講座運営等をやっているというのが実態です。","id":"exchange-012"},{"speaker":"林（宏）委員","kind":"確認","question":"男性が女性をいじめるという事実も今でもあるけれども、男のつらさというのもあるというのは、僕は知っておいてほしいと思う。確認をしておきます。","respondent":"本間総務部長","answer":"意識を持っているのかというご質問ですが、そういう意識をしっかり持ちまして、全庁的に、それぞれのセクションの長を、これの推進の実践部隊ということで、また会議体を持っておりまして、そういう意識を持って、これからも推進をしてまいります。","id":"exchange-013"},{"speaker":"林（宏）委員","kind":"確認","question":"一つだけ確認しておきたいのは、セクハラの庁内の委員会をつくられましたよね。区役所内のセクシャル・ハラスメントの実態を。","respondent":"本間総務部長","answer":"セクハラに関しまして、セクハラ調査委員会というものを庁内に設けてございまして、私が委員長ということになってありますが、今まで一度も、幸いなことに、そういう事例は起きておりませんで、会議は開催されておりません。","id":"exchange-014"},{"speaker":"塚本委員","kind":"質問","question":"今セクハラということで、セクハラ談義というものは、男性はセクハラの対象にならないんですか。男性が性的な嫌な思いをするということは、セクハラとはいわないのか。","respondent":"阿部人権啓発課長","answer":"男性はならないということではございません。自分が嫌な気持ちを受けるということですから、男性であっても女性であっても、それはあります。","id":"exchange-015"},{"speaker":"塚本委員","kind":"質問・要望","question":"結婚とか家庭とか、ある意味で少し、自治体といえども踏み込んでものを言わなきゃいけない時代が来ているような気がするんです。私は思うんですけれども、そういうことに関しては、どういうような考え方なのかお聞かせほしいと求めました。","respondent":"本間総務部長","answer":"今は家事の男女の負担を分担して行うというのは自然な時代になってまいりましたし、これからも努力していきたいと、こういう思いです。","id":"exchange-016"},{"speaker":"塚本委員","kind":"質問","question":"どうしてもこれを選ぶかあれを選ぶかしかできないわけですから、今日本の社会でいろいろ困っているのは、いろいろな制度が支え切れなくなってきた。男女の話を聞いているんじゃないんですから、もう一度社会の最小単位、その次の単位のことはどう考えるかというふうなことについて答えるよう求めました。","respondent":"濱野助役","answer":"ちょっとお答えになるかどうかわかりませんけれども、社会的な参加だとかという、女性としての一つの大きな目標というのがある時代だろうと思います。そういう意味では、男の再構築というものがもう１回必要になっていくのではないかなというふうに、思っている次第です。","id":"exchange-017"},{"speaker":"塚本委員","kind":"質問","question":"３回目になりますけれども、このことをイメージできなくて、どうして政策がつくれるんでしょうか。それをもう少し。","respondent":"中尾根企画部長","answer":"認識そのものは、どういう方向へ歩んでいけばいいのか、これは全体の問題としていかねばならない問題です。そういう認識におりますので、そのことだけ。","id":"exchange-018"},{"speaker":"塚本委員","kind":"意見","question":"夫婦の関係、親子の関係、そういうものを、どういうふうに社会がイメージするかによって、それは一定程度、政府が係わらなきゃいけないことですね。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-019"},{"speaker":"藤田委員","kind":"質問・要望","question":"おとといですか、女性初の２３区区長という、こういうふうに私は思うんです。ですから、そういう表現はまずないわけですから、私は考えるんです。","respondent":"阿部人権啓発課長","answer":"これはあくまで、私どもが掲げている男女共同参画をつくっていくための拠点というふうに考えています。ですから、先ほどからも申し上げたように、男女共同参画センターは、男女共同参画社会を進める上の拠点だというふうに考えております。","id":"exchange-020"},{"speaker":"藤田委員","kind":"質問・要望","question":"どうしてもそういうふうになってしまうということなんで、今後の考えがあれば、お聞かせほしいと求めました。","respondent":"阿部人権啓発課長","answer":"私ども、先ほど男女共同推進フォーラムをやっているということを言いましたけれども、それぞれの委員を公募しているわけですね。センターの運営を含めまして、藤田委員ご指摘のような民間の団体を含めまして、これからは徐々に進んでいくような方向でというふうに考えております。","id":"exchange-021"},{"speaker":"桜井委員","kind":"質問","question":"１点だけお聞きしたいんですけれども、この計画プランの中の６９ページなんですけれども、これは人権に関わる意識調査をやっていますよね。どうも課長のほうから答弁いただけなかったので、どういうふうに今後考えているのかというのを、１点伺いたいんですけれども。","respondent":"阿部人権啓発課長","answer":"６９ページにあります人権に係わる意識調査というものですけれども、これは、過去２年やってあります。平成１１年にやりまして、ですから時期が来ればそれも検討していくということで、今後定期的にという記述になっているということです。","id":"exchange-022"},{"speaker":"桜井委員","kind":"質問・要望","question":"初めてお聞きになったという業者婦人、こういう調査のところに、ぜひ検討していただきたいと思うんです。ですから、今度のこの調査のところでも１項目に入れていただきたいと思うんですけど、そこはいかがか尋ねました。","respondent":"阿部人権啓発課長","answer":"ですから、その時点でまた新たに検討しなければいけない項目もあるかと思います。ですからその際に、改めてどういう項目を調査していくのかというのは検討していきたいと、このように思います。","id":"exchange-023"},{"speaker":"桜井委員","kind":"意見","question":"できればもうちょっとていねいな資料もいただいて、していきたいという、継続を主張したいと思いますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-024"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、十分に論議を進めていただいて、できればこういった方向をつなげていただいて、条例制定化に大きな一歩を進めていただきたいなと思います。区民相談では解消できないそうした問題もあるわけですから、これは要望ですけれども、賛成の立場から申し上げました。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-025"}]},{"id":"topic-02","title":"請願第３１号、旧正田邸についての請願","agenda":"請願第３１号、旧正田邸についての請願","exchanges":[{"speaker":"土井委員","kind":"質問・要望","question":"そのうちの第１番目の国有財産で管理するというのは、これは当然のことですから、そのとおりだというふうに思います。２番目の、文化財に該当しない確認の上取り壊しを決定したと、文化財というのはさまざまなレベルがあるわけですね。","respondent":"市岡企画財政課長","answer":"国が所有者ですので、国もこれらの点については同意をしないということが、これは推測ができるわけです。現実に、今の段階で所管等にも確認した段階では、結論的には都ないしは区の指定文化財にも基本的にはならないという見解が示されております。","id":"exchange-026"},{"speaker":"土井委員","kind":"質問","question":"ですから、それは推測の域だと。その上で、今お話のあった、都のレベルではないよ、区のレベルではないよ、該当しないよというのは、どこで。","respondent":"市岡企画財政課長","answer":"東京都の指定文化財、あるいは品川区の条例に基づく指定文化財には該当しないだろうというのが、現時点での所管の解釈だということを申し上げたわけです。","id":"exchange-027"},{"speaker":"土井委員","kind":"意見","question":"それは一応の所管の解釈で、特に文化財ということになれば、当然、それなりの指定のための手続等々をする段階で、一定の皆さんが判断をすると、こういうことがまだ残されているというふうに理解をしてよろしいですねとの意見を述べました。","respondent":"市岡企画財政課長","answer":"いずれの文化財についても、所有者の同意を得て調査を行いまして、その後、区の文化財であれば、区の文化財保護審議会、ここに諮問いたしまして、答申を経て、指定をするとすれば教育委員会で決定をすると、こういう形になります。","id":"exchange-028"},{"speaker":"土井委員","kind":"質問・要望","question":"その地域的なご要望等々の中から、国レベルであったりで、保存とかはやっていくということと等が行われる。このようなこと等がいろいろあるやにも伺っているし、またそこら辺についても議論ができればいいなというふうに、今のところ思っています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-029"},{"speaker":"桜井委員","kind":"質問","question":"その経過のところをもう少し聞きたいんですけれども、区民の混乱をさけるというのは、どういう意味なんでしょうか。どうも、そこがちょっとわかりにくいんですけれども、教えていただけますか尋ねました。","respondent":"市岡企画財政課長","answer":"先ほど来申し述べているさまざまな要因を検討した上で、問題をさらに複雑にするであろうと、こういうことを混乱というふうに申し上げました。最も解決できる方法として、公園用地として区が建物除却後の購入を希望したと、こういうことです。","id":"exchange-030"},{"speaker":"桜井委員","kind":"確認","question":"一応確認をされたということが、少なくとも区が購入していくという、そういう道筋をつけたほうが混乱は避けられるということなんでしょうか。公園用地として買うという区の意向は、少なくとも土地ということに対しても、区民の残る感情があるということで購入するという理解なんか尋ねました。","respondent":"市岡企画財政課長","answer":"建物については取り壊すという方針を、その後最も適切な対応策は何かということで、こういうことを要望したということです。","id":"exchange-031"},{"speaker":"塚本委員","kind":"確認","question":"整理してお伺いしたいんですけれども、どういう流れになるかということで伺いますが、相続税の関係で物納したと。それが考えられないわけではないですから、手順として、このケースがその手順にちゃんと乗っているかどうかということを確認したいんですが。","respondent":"市岡企画財政課長","answer":"地方公共団体が公共用に使うと、公共用というのは、公園その他公共施設としてです。国が十分に考えて、裁量的に判断されると、このように考えております。","id":"exchange-032"},{"speaker":"塚本委員","kind":"質問","question":"品川区にこういうものが、国の財産としてあるんだから、早く目をつけて、くださいよと言うのがいいのか、時間的なこと。それから、今回のことも含めてお伺いしたい。","respondent":"市岡企画財政課長","answer":"答えるという立場でもないんですが、先ほど委員のほうからも、通常は物納されてから１年程度待つということが通例だというふうに言われております。","id":"exchange-033"},{"speaker":"塚本委員","kind":"質問","question":"競売にするときにも当然更地が好ましいというふうに、私ども常識として承知しておるんですけれども、これはそうなのか。そして、今回の場合はこういうことがどうしてなかったのかということをお伺いしたいと思います。","respondent":"市岡企画財政課長","answer":"土地および建物を物納されているわけですから、その時点では一定の評価があって、建物についても評価があったということもあろうかと思います。","id":"exchange-034"},{"speaker":"塚本委員","kind":"質問","question":"ということは、物納を受けた時点で建物の価値も判断しているんか尋ねました。","respondent":"市岡企画財政課長","answer":"報道によれば、土地建物が物納されたというふうに報道されておりますので、そういうことになろうと思います。ただ、幾らで評価したかとか、そういうことについてはいろいろあるかと思います。","id":"exchange-035"},{"speaker":"藤田委員","kind":"質問・要望","question":"旧正田邸の前で現在も署名をされているという、そういう光景も、私は見てまいりました。ここでちょっと確認なんですけれども、各関係方面に強く働きかけていただきたい」という、我々は解釈してよろしいんか尋ねました。","respondent":"市岡企画財政課長、中尾根企画部長","answer":"そのとおりでございまして、品川区は、建物を買うつもりもありませんし、建物の購入について、国から、それが一緒にされることもあり得ないということです。 ちょっと補足いたしますけれども、国の財務省は、更地にして品川区にはお売りすると、こういう前提だとはっきり申されておりますので、そのようにお受け取りください。","id":"exchange-036"},{"speaker":"嶋委員","kind":"質問","question":"私も五反田で生まれ育った者としては、大変感慨深いものがあります。これは国の裁量としてということなんですが、品川区以外に手を挙げているところがあった場合どうなるのか、これをちょっと伺っておきたいと思います。","respondent":"市岡企画財政課長","answer":"現時点で随意契約の対象になるような、他の地方公共団体ですけれども、手を挙げているところはございません。これはちょっと私の見解なんですけれども、仮に複数の公共団体が手を挙げた場合に、やはり地元の地方公共団体が優先するというふうに思っております。","id":"exchange-037"},{"speaker":"嶋委員","kind":"質問","question":"（「質問者の方は請願内容の範囲で」と呼ぶ者あり）そうですね、よろしくお願いしたいということも、言われました。手を挙げていただいたということで、一番ほっとしているということで、感想を述べします。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-038"},{"speaker":"林（宏）委員","kind":"意見","question":"物納されたものをどう取り扱うかと言ったときに、土地というものと、二つに分けて考えていっていいのかなと。その辺については、何らかの見解というか、情報は持っていらっしゃいますかとの意見を述べました。","respondent":"市岡企画財政課長","answer":"具体的な情報は持っていませんが、土地建物が物納されたということは、相続税の原則は現金による納税ですから、それの例外として許可をされたということで、なにがしかの評価はあったんだろうということは、報道等から十分に推測できることです。","id":"exchange-039"},{"speaker":"林（宏）委員","kind":"質問","question":"すると、さっき競売して換価するということから言うと、建物も売れる、値段がつくという判断があったのかもしれないんだけど、その辺についてはどうか尋ねました。","respondent":"市岡企画財政課長","answer":"私がその辺をお答えできる立場ではないと思いますが、「等」というふうに申し上げましたけれども、文化財等に該当するかどうかという判断。","id":"exchange-040"},{"speaker":"林（宏）委員","kind":"質問","question":"１億円の課税というか、それに対して５,０００万円の物納というのは、そのときに評価されないと１億円にならないわけじゃないですか。税金を払うときの、物納のときのものの評価というか、判断というのは、どういうふうにされるんか尋ねました。","respondent":"市岡企画財政課長","answer":"それと国庫に収納するという手続は全く別でして、現時点で評価をしているわけですから、国はそういうふうに説明をしているです。物納はありませんけれども、これについても、その時点時点での評価というふうに聞いてあります。","id":"exchange-041"},{"speaker":"林（宏）委員","kind":"意見","question":"これは５００円、これは１億円というふうにしておかないと、数字が出てこないんじゃないかと思うんですよ。価値というか、土地は幾らで建物は幾らというのがあったのではないかというふうに推測できるんだけど、その辺もうちょっとはっきりとの意見を述べました。","respondent":"中尾根企画部長","answer":"どういういきさつで物納され、どういう考え方で評価したのかというのは聞いてございませんし、その返事ももらってございません。どこまで財務省が答えてくれるかはわかりませんけど、あくまで一般論でしたらお答えできますけど、具体的なことはお答えできません。","id":"exchange-042"},{"speaker":"林（宏）委員","kind":"質問","question":"そういう計算は成り立つんですか。一般論でいいです。","respondent":"市岡企画財政課長","answer":"先ほど部長がお答えしたような、これを正田邸に当てはめてどうのこうのというのは、私ども現時点では申し上げられない。逆に私の説明が適切でなかったのかもしれないですけど、あくまでご本人が物納を撤回して、改めて現金でお支払いをするというのが基本です。","id":"exchange-043"},{"speaker":"林（宏）委員","kind":"質問","question":"本来的にそうであってほしいというのは、住んでいらっしゃる方もそうだろうと思う。まちの位置づけというか、そういうものについて、今回のことで考えたことはありますか。","respondent":"中尾根企画部長","answer":"そういうことをいろいろ考えた末に、そういう総合判断の上で、今回判断されたということです。まだ、本来あるべきものをどうすべきかということについては、手順はきちんと踏んだほうがより望ましいというのは、私どももわかっております。","id":"exchange-044"},{"speaker":"林（宏）委員","kind":"確認","question":"委員長にちょっとお願いというか確認というか、皆さん委員の人たちに確認があるんですけど、おやと思うものがある。それでちょっと矛盾を感じているということを、一点申し上げておきます。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-045"},{"speaker":"桜井委員","kind":"質問・要望","question":"この経過というんでしょうか、どういうふうな判断がされているのか、あるいはまだ判断していないのか。だから、いろいろなことをもう１回検討したいなと思うんですけれども、その上でも、今のをちょっとわかるように教えていただきたい。","respondent":"市岡企画財政課長、中尾根企画部長","answer":"ただ、当日区長が理財局へ行ったときに、これは前向きに検討してお返事をしますと、こういう回答をもらってきているところであります。したがって、建物を区が壊さないで土地を買うということは、これはもうできない関係にあります。 最後の３点目の、考え方といいますか、さまざまな意見が本当に寄せられております。だから、ベストのことはやはりできない、その中でのベターなものの選択は何かと、こういう判断で区が臨んでいるということです。","id":"exchange-046"},{"speaker":"桜井委員","kind":"質問","question":"先ほどの登録文化財ということについて、わかる方はいらっしゃいますでしょうか。私も、ここは聞き慣れないことだからどなたかわかる方がいたら説明を求めました。","respondent":"市岡企画財政課長","answer":"まあ、国の文化財保護法では、これまでの指定文化財に対して、より緩やかな保存の手法としてつくられた考えです。ただ、登録文化財についても、先ほど申し上げたとおり、文化庁は該当しないということが、はっきりしています。","id":"exchange-047"},{"speaker":"塚本委員","kind":"質問・要望","question":"取壊しは１１月いっぱいだという話しがあったにもかかわらず、いろいろな理由で、除去を免れないということが想定される。年度を超えて、予算措置をしなければ執行されなかったということも考えられないわけではないですから、区の見解をほしいと求めました。","respondent":"中尾根企画部長","answer":"それで、国が年度内に売却をするということを言っておりまして、その方針は今まで変わらないというふうに言っております。国がきちんと、そのことをどうなさるかということだというふうに受けとめております。","id":"exchange-048"},{"speaker":"塚本委員","kind":"意見","question":"現実に購入したいという意思をはっきり示されたわけですが、予算の範囲でやらなければという話もあるんだろうし、値段のことも当然あるだろうと。私どもは補正を審議するなら１２月にでもしたいというあれもありますので、今一度、その辺のことをとの意見を述べました。","respondent":"中尾根企画部長","answer":"こうおっしゃっていただきまして、前向きに検討したいということも、その場ではおっしゃっていただきました。先ほど言いましたのは、そういったことの期間も、当然私どもは踏まえた上での、国に対応をお願いしています。","id":"exchange-049"},{"speaker":"塚本委員","kind":"質問","question":"今の質問は、理事者側の想定しているのはどうなるかということを聞いたんで、これから審議しなきゃいかんです。請願の文意が少し蛇行しているのではないかということで、考え方をまとめるのに、大変苦慮しているというようなところです。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-050"},{"speaker":"土井委員","kind":"質問・要望","question":"その辺の中身等も含めてお聞きをしながら、これはものですから、私はそういう解釈をしています。区から要望を出すというのはなかなか困難だとすれば、我々の手法ではなかろうかと、こんなふうに思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-051"},{"speaker":"藤田委員","kind":"意見","question":"こうした皇后様の意思というもの、お気持ちはやっぱり大切にしていくべきではないかなと、このようなことで議論をしました。私もどういうふうにするか、考えの基本をどこに置くべきか、今思っておりますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-052"},{"speaker":"林（宏）委員","kind":"質問","question":"一般論で言って、それに対して壊さないでくれとか、公園にしてくれとかいうことは言えるんですか。納めた人が言えるんですか、一般論としてですよ、今回ではなくて。","respondent":"市岡企画財政課長","answer":"希望を述べることはできると思いますが、それは希望を述べるだけであって、国有財産として国の管理になった以上、国がその権限と責任で管理をすると、そういうことにしか過ぎないと思います。","id":"exchange-053"},{"speaker":"林（宏）委員","kind":"意見","question":"そういう考え方が成り立ちませんか。そういう話になっちゃうと、非常に困るなという気がするんだけど、考え方が間違っていたら指摘をして下さいとの意見を述べました。","respondent":"中尾根企画部長","answer":"したがいまして、あそこで区が公園として持つこと自体が要らないという判断に立てば、またそういう判断ということになると思います。あくまでもそういう基本的な考え方で、これを議会のほうにご審議いただくと、こういうことになります。","id":"exchange-054"},{"speaker":"林（宏）委員","kind":"意見","question":"だったら、やっぱり品川区としては、もうあの建物に文化的な価値はないんだからという判断をされる国のそれをきちんと支持すればいいと思うんですよ。そう思いますけどとの意見を述べました。","respondent":"中尾根企画部長","answer":"だから、全くそれは抜きに、というのは非常に難しい。この言い方の中には、そういうことも全部含めて、国は判断してくださいよと。","id":"exchange-055"},{"speaker":"林（宏）委員","kind":"質問・要望","question":"今一連の話を、流れを聞いていると、区に幾らこういう要望を出されても無理なんですよ。だから、それは伝えないと、この人たちの思いが品川区で止まってもかわいそうだな、失礼だなと思いますよ。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-056"},{"speaker":"塚本委員","kind":"質問","question":"一種の自治体の政府ですから、何らかのアクションをしてくれよと、区議会に対してはそれを言えるわけです。あるルートがつながっているわけですから、こういう意思を反映してくれと願い出ることはごく真っ当なことだと、私は思います。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-057"},{"speaker":"林（宏）委員","kind":"質問","question":"あるいは財務省に行って、残す方法はないんですかと陳情を出すとか、そういうことだって可能なわけです。ですから、この方たちの思いがどこへ向かっていったら一番可能性があるかというのを探るのを教えてあげなきゃ、僕は言っているわけです。","respondent":"中尾根企画部長","answer":"ご返事するというのが、今までのルールですので、そのように考えてございました。そのことも持ったらという、その助言に対しては、助言があったということで受けとめさせてはいただきます。","id":"exchange-058"},{"speaker":"林（宏）委員","kind":"意見","question":"どうにも僕はそれが伝わってこないので、僕は受け取れちゃうわけですよ、僕はこの文章を読むと。だから、そういうことも含めて、文章の文面、ちょっとストレートにものが伝わってこないというのが、僕の感想を改めて言っておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-059"},{"speaker":"塚本委員","kind":"提案","question":"確認できれば、現段階では思いますので、ぜひ委員長にお取り計らい願いたい。陳情・請願の扱い方等もよく承知している人ですから、そういうような段取りはいかがかと、意見として言っておきますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-060"},{"speaker":"桜井委員","kind":"質問","question":"意見陳述は、正式に提出されていますよね。意見陳述、請願者から今回出ているわけですから、先にやるべきだと思いますけれども。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-061"},{"speaker":"藤田委員","kind":"提案","question":"塚本委員からそういう提案があったんですが、（「開かれてません」と呼ぶ者あり）開かれていないですか、なるほど。塚本委員がそのようにおっしゃっているわけですから、もし、やはり紹介議員の２人の気持ちも尊重していくべきではないかということをとの意見を述べました。","respondent":"伊藤委員長","answer":"当然、藤田委員のご指摘のとおりだと思います。事前の打ち合わせ、そのような問題が起きないように運営してまいりますので、ご理解をよろしくお願いいたします。","id":"exchange-062"},{"speaker":"桜井委員","kind":"提案","question":"委員長のせっかくの提案ですけれども、ちょっとこの委員長の提案の趣旨がわからないんですが、なるかならないかわかりませんよ。ここで決まっていいんか尋ねました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-063"},{"speaker":"塚本委員","kind":"提案","question":"先ほど提案したときに会議が戻りましたけれども、質疑応答がないわけですから、そういうことですから。私はそういう意向で思っていますとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-064"},{"speaker":"土井委員","kind":"質問","question":"私がいろいろと伺っている請願代表者の方も、いろんな形でおやりになられている方というふうに伺っておりますので、ぜひ聞くべきだと考えています。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-065"},{"speaker":"桜井委員","kind":"質問","question":"ですから、聞いた上で、私どもも判断したいというふうに思っております。賛成します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-066"},{"speaker":"土井委員","kind":"質問","question":"漏れ伺うところによりますと、陳述をしたいという中身の次第について、何かお出しになっているようにも伺っておるんですけれども、委員長にはどんな形で提出されてございましょうか。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-067"},{"speaker":"藤田委員","kind":"質問・要望","question":"ですから、２人の紹介議員が陳述者とよく打ち合わせをしていただいて、それで、この議会の委員会で代表して答弁いただきたいと、このように思っております。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-068"}]},{"id":"topic-03","title":"小・中学校空調設備","agenda":"小・中学校空調設備","exchanges":[{"speaker":"桜井委員","kind":"質問","question":"それぞれ三菱冷、塩谷、それぞれの企業の資本金を教えていただけますか尋ねました。","respondent":"西島経理課長","answer":"それから、中央公設ですけれども、１,０００万円です。それから、最後になりますが、太洋テクニカですが、これが９,０００万円、それと三橋工務店ですが、これが２,０００万円、資本金は以上です。","id":"exchange-069"},{"speaker":"桜井委員","kind":"質問・要望","question":"資本金１億未満というのが大体、そういうふうに伺っているんですけれども、すべて電気ということなんでしょうか。そこの工事の内容を、ちょっとあわせて教えていただきたいというのと、中小企業の場合の考え方を教えてほしいと求めました。","respondent":"西島経理課長","answer":"中小企業の考え方ですけれども、すべて予定価格９,０００万円以上の工事ですので、１億３,０００万円ということが基準になっております。これは室内機と室外機の設置、それと配管工事、室外機から室内機に向けての配管工事が主たる工事です。","id":"exchange-070"},{"speaker":"林（宏）委員","kind":"意見","question":"入札だから差が出てくるのは当然だけど、Ａブロックの８,９００万円とＣブロックの８,２００万円、教室数はほぼ同じだよね。その辺の、これだけの、１割の差が出てくるというのはなぜかとの意見を述べました。","respondent":"西島経理課長","answer":"室外機を置く場所がそれぞれ違いますので、その関係で配管の距離が学校によってはかなり差があるということがございまして、こういう差が出てきた。","id":"exchange-071"},{"speaker":"林（宏）委員","kind":"質問","question":"ＡとＤは学級数は同じで、学校数は１校違うのに、学校数が多いほうが安い。全く同じ条件で入札をやったんか尋ねました。","respondent":"西島経理課長","answer":"これが４分の１ずつになってしまうということで、競争にならないということも考えまして、重複申し込みは可能ですということで実施をいたしました。そういうことの中で、先ほど説明いたしました形での入札を実施いたしました。","id":"exchange-072"},{"speaker":"林（宏）委員","kind":"意見","question":"それこそ地元の地元というのか、そういうような形もやっていたりしていたのは、おそらく同行された部長からお話は聞いていると思います。まあ、岡山市も落札率というのが９０％前後になっているというようなお話も聞いてきているんで、入札のあり方はこれからも検討してくださいとの意見を述べました。","respondent":"","answer":"答弁を求める発言ではないため、これに対する答弁はありません。","id":"exchange-073"},{"speaker":"桜井委員","kind":"質問","question":"そうすると、入札状況などでまた報告いただいて、またそのときに質問します。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-074"},{"speaker":"桜井委員","kind":"質問","question":"聞きたい質問を一つ、審議会、２２あるというふうに言われているんですが、その審議会の公募状況ですね。この船波議員の質問の中でも、開催日程はどういうふうにお知らせをされているのか、とりあえずお聞きします。","respondent":"小野（孝）政策担当課長","answer":"条例外で設置をしております、１５のうち六つが公募という形をとっておりまして、特段の規定によるものはございません。これは、あるいは委員長のほうで日程を調整し、他の委員たちの日程のほうも調整しながら打ち合わせという形になっているというふうに聞いております。","id":"exchange-075"},{"speaker":"桜井委員","kind":"質問・要望","question":"私はその、これは基本的な立場でもう一度お伺いしたいんですけど、一つ確認したいんです。第三次長期計画でも住民参加ということで、共同参画ということでうたわれているわけですから、そのところの考え方を新たにお聞きしたいと思います。","respondent":"小野（孝）政策担当課長","answer":"品川区の２３の審議会、これをずっと見てまいりますと、こういうものもあります。ちょっと確認をしてございませんので、必要であれば、またきちっと調べた上でご報告したいと思います。","id":"exchange-076"},{"speaker":"桜井委員","kind":"質問","question":"それだけではなくて、今後のまちづくりについてどうすべきかということも、公開するわけでしょう。ですから、なぜ踏み込めないのかなと、これは依然として明示されないんか尋ねました。","respondent":"小野（孝）政策担当課長","answer":"そういう精神でもって、第三次長期計画の中にも、公開ということを、はっきりと明示をしているものです。あるいは参加を進めるという姿勢をはっきりと示した上で、実情に合わせて、現在のところは適切なのではないかというふうに考えております。","id":"exchange-077"},{"speaker":"桜井委員","kind":"質問・要望","question":"ですから、ですから、そういう努力をぜひお願いしたい。最後に要望もあるんですけれども、もっと積極的に出していただきたいし、トップに載っていないんですね。","respondent":"中尾根企画部長","answer":"その運営の中でどうあるべきかというのが常に考えられなくちゃいけなくて、そこは技術的な問題としても、非常に難しい問題があります。こういうことを、ちょっと余分ですけど、苦言します。","id":"exchange-078"},{"speaker":"桜井委員","kind":"質問・要望","question":"当然そのとおりですけれども、私ども議会の中から住民参加ということも言っていることも、またよく注目いただきたいと思うんです。流れとして出てくるわけですから、議会軽視をしないという、おっしゃることもよくわかります。","respondent":"","answer":"この発言に対する答弁を会議録から特定できませんでした。会議録の全文をご確認ください。","id":"exchange-079"}]}],"links":[{"type":"minutes","label":"公式の会議録を読む","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/201900?Template=document&Id=1604#one"},{"type":"official","label":"公式の会議録一覧","url":"https://kaigiroku.city.shinagawa.tokyo.jp/index.php/100000?QueryType=new&Template=list&Cabinet=5&TermStart=2002-01-01&TermEnd=2002-12-31"}],"sourceMeta":{"pages":0,"characters":63282,"voices":178}}]);
